hemma_badge_energy.name:
[[[
  const T = window._hemmaT || ((k, en, v) => String(en).replace(/\{(\w+)\}/g,
    (m, p) => (v && Object.prototype.hasOwnProperty.call(v, p) ? String(v[p]) : m)));
  const esc = (t) => String(t ?? '').replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');

  const title = variables?.label
    || entity?.attributes?.friendly_name
    || T('energy.power', 'Power');

  const cur = String((typeof hass !== 'undefined' && hass?.config?.currency) || 'USD').toUpperCase();
  const SYM = { USD:'$', CAD:'$', AUD:'$', NZD:'$', MXN:'$',
                EUR:'\u20AC', GBP:'\u00A3', JPY:'\u00A5', CNY:'\u00A5',
                SEK:'kr', NOK:'kr', DKK:'kr', CHF:'Fr', INR:'\u20B9',
                BRL:'R$', PLN:'z\u0142', KRW:'\u20A9' }[cur] || '$';
  const NUM = window.hemmaNum || ((v, a, b) => Number(v).toFixed(b ?? a ?? 0));
  const money = (n) => window.hemmaMoney ? window.hemmaMoney(n, cur)
    : SYM + (n >= 100 ? Math.round(n) : n.toFixed(2));

  const resolveUnit = (u, e) => {
    u = String(u || 'auto').toLowerCase();
    if (u === 'energy') return 'kwh';
    if (u !== 'auto' && u !== '') return u;
    const dc = String(e?.attributes?.device_class || '').toLowerCase();
    const uom = String(e?.attributes?.unit_of_measurement || '');
    if (dc === 'monetary') return 'cost';
    if (dc === 'energy' || /^k?Wh$/i.test(uom)) return 'kwh';
    return 'auto';
  };

  const raw = parseFloat(entity?.state);
  const unit = resolveUnit(variables?.unit, entity);
  let value = '';
  if (Number.isFinite(raw)) {
    if (unit === 'kwh') {
      value = (raw >= 10 ? NUM(Math.round(raw), 0, 0) : NUM(raw, 1, 1)) + ' kWh';
    } else if (unit === 'cost') {
      value = money(raw);
    } else {
      value = raw >= 1000 ? NUM(raw / 1000, 1, 1) + ' kW' : NUM(Math.round(raw), 0, 0) + ' W';
    }
  }

  const cid = variables?.cost_entity;
  const cost = cid ? parseFloat(states[cid]?.state) : NaN;
  if (Number.isFinite(cost)) {
    value = value ? (value + ' · ' + money(cost)) : money(cost);
  }

  return `
    <div class="badge-wrap">
      <div class="badge-title">${esc(title)}</div>
      ${value ? `<div class="badge-sub">${esc(value)}</div>` : ''}
    </div>
  `;
]]]

hemma_badge_energy.extra_styles:
[[[
  const v = variables?.enabled;
  const enabled = (v === undefined || v === null) ? true :
    (typeof v === 'boolean') ? v :
    (typeof v === 'number') ? v !== 0 :
    !['false','0','no','off','disabled'].includes(String(v).trim().toLowerCase());
  const st = String(entity?.state ?? '').trim().toLowerCase();
  const dead = !entity?.entity_id || !st || ['unknown','unavailable'].includes(st);
  const resolveUnit = (u, e) => {
    u = String(u || 'auto').toLowerCase();
    if (u === 'energy') return 'kwh';
    if (u !== 'auto' && u !== '') return u;
    const dc = String(e?.attributes?.device_class || '').toLowerCase();
    const uom = String(e?.attributes?.unit_of_measurement || '');
    if (dc === 'monetary') return 'cost';
    if (dc === 'energy' || /^k?Wh$/i.test(uom)) return 'kwh';
    return 'auto';
  };
  const unit = resolveUnit(variables?.unit, entity);
  const isCost = unit === 'cost' || !!variables?.cost_entity;

  const rr = 13.5, C = 16, W = 3;
  const pt = (deg) => {
    const a = deg * Math.PI / 180;
    return (C + rr * Math.sin(a)).toFixed(3) + ' ' + (C - rr * Math.cos(a)).toFixed(3);
  };
  // 270 degree arc with the gap at the bottom, matching the climate gauges.
  const ring = 'M ' + pt(225) + ' A ' + rr + ' ' + rr + ' 0 1 1 ' + pt(495);

  let glyph;
  if (isCost) {
    const cur = String((typeof hass !== 'undefined' && hass?.config?.currency) || 'USD').toUpperCase();
    const SYM = { USD:'$', CAD:'$', AUD:'$', NZD:'$', MXN:'$',
                  EUR:'\u20AC', GBP:'\u00A3', JPY:'\u00A5', CNY:'\u00A5',
                  SEK:'kr', NOK:'kr', DKK:'kr', CHF:'Fr', INR:'\u20B9',
                  BRL:'R$', PLN:'z\u0142', KRW:'\u20A9' }[cur] || '$';
    const fs = SYM.length > 1 ? 11 : 15;
    glyph =
      "<text x='16' y='21.5' text-anchor='middle' fill='white' font-weight='700'" +
      " font-size='" + fs + "' font-family='-apple-system,BlinkMacSystemFont,system-ui,sans-serif'>" +
      SYM + "</text>";
  } else {
    const BW = 16.8633, BH = 26.3734, H = 15;
    const s = H / BH;
    const bolt = 'M0 14.5402C0 14.9972 0.351562 15.3371 0.84375 15.3371L7.46484 15.3371L3.97266 24.8293C3.51562 26.0363 4.76953 26.6808 5.55469 25.6965L16.207 12.384C16.4062 12.1379 16.5117 11.9035 16.5117 11.634C16.5117 11.1887 16.1602 10.8371 15.668 10.8371L9.04688 10.8371L12.5391 1.34491C12.9961 0.137874 11.7422-0.506657 10.957 0.489437L0.304688 13.7902C0.105469 14.048 0 14.2824 0 14.5402Z';
    glyph =
      "<g transform='translate(" + (C - BW * s / 2).toFixed(3) + ' ' +
      (C - H / 2).toFixed(3) + ") scale(" + s.toFixed(5) + ")'>" +
      "<path d='" + bolt + "' fill='white'/></g>";
  }

  const svg =
    "<svg xmlns='http://www.w3.org/2000/svg' width='32' height='32' viewBox='0 0 32 32'>" +
    "<path d='" + ring + "' stroke='white' stroke-width='" + W + "' stroke-linecap='round' fill='none'/>" +
    glyph + "</svg>";
  const URL = 'data:image/svg+xml,' + encodeURIComponent(svg);

  return `:host{display:${(!enabled || dead) ? 'none' : 'inline-block'} !important;}
    #img-cell, .img-cell{ position: relative; }

    #img-cell #icon, .img-cell #icon{
      color: transparent !important;
      opacity: 0 !important;
    }

    #img-cell::before,
    .img-cell::before{
      content: '';
      position: absolute;
      inset: 0;
      background-color: var(--hemma-badge-icon-color, var(--hemma-badge-energy-color, #30D158)) !important;
      -webkit-mask: url("${URL}") no-repeat center / auto 86%;
      mask: url("${URL}") no-repeat center / auto 86%;
      transform: translateZ(0);
    }`;
]]]

