hemma_now_playing_primary.name:
[[[
  const s = variables.hold_src;
  if (!s) return '';

  const esc = (t) => String(t ?? '')
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');
  const bits = s.kind === 'player'
    ? [s.subtitle]
    : [s.source, s.subtitle];
  const sub = bits.map(x => String(x || '').trim()).filter(Boolean).join(' · ');

  let bar = '';
  if ((variables.np_count || 1) <= 3
    && Number.isFinite(s.dur) && s.dur > 0 && Number.isFinite(s.pos)) {
    const elapsed = s.playing && s.posAt ? (Date.now() - s.posAt) / 1000 : 0;
    const now = Math.min(s.dur, Math.max(0, s.pos + elapsed));
    const frac = Math.max(0, Math.min(1, now / s.dur));
    const remain = Math.max(0, s.dur - now);
    const anim = s.playing && remain > 0
      ? `animation: np-advance ${remain.toFixed(1)}s linear forwards;`
      : '';
    bar = `<div class="np-track"><div class="np-fill" style="transform: scaleX(${frac.toFixed(5)}); ${anim}"></div></div>`;
  }

  // The progress bar makes this markup new on every render, which rebuilds the lines: a scrolling one is written
  // already scrolling, at the point its scroll had reached (--np-marquee-scan keeps the start time).
  const mq = this._npMq || {};
  const line = (cls, text) => {
    const m = mq[cls + '|' + text];
    if (!m) return `<div class="np-line"><span class="${cls}">${esc(text)}</span></div>`;
    const at = (m.base - (Date.now() - m.t0) / 1000).toFixed(2);
    return `<div class="np-line np-scroll" style="--np-mq:${m.mq};--np-marquee-dur:${m.dur};--np-mq-delay:${at}s">`
      + `<span class="${cls}">${esc(text)}</span>`
      + `<span class="${cls} np-marquee-clone" aria-hidden="true" style="margin-left:${m.gap}px">${esc(text)}</span></div>`;
  };
  return `
    <div class="np-meta">
      ${line('np-title', s.title)}
      ${sub ? line('np-sub', sub) : ''}
      ${bar}
    </div>
  `;
]]]

hemma_now_playing_primary.extra_styles:
:host{
  display: block;
  /* :host must track ha-card's capped width - the glass rim is :host::after (inset:0), so a flat 100% host let the rim draw wider than ha-card's own max-width on wide tracks. margin-left:auto keeps the pair right-aligned. */
  /* !important: button-card inline-clamps the host to max-width:fit-content whenever styles.card carries a width key (see hemma_mobile_now_playing.yaml), beating a plain :host rule. */
  width: var(--np-tile-width, 100%) !important;
  max-width: var(--np-max-w, calc(var(--hemma-u-np, 10px) * 40)) !important;
  margin-left: auto;
  --np-shadow: none;

  /* Artwork can't shrink below the text column height, or the column drives card height and breaks the equal insets - so column height is trimmed and the freed space goes to padding. */
  /* min(natural, slot): --np-slot-h is the stack's budget split between the live
     tiles, so one or two keep their natural size and the rest shrink exactly
     enough to fit. The 999px fallback is the mobile row, which sets no slot. */
  /* The phone's tile on every device: the artwork sets the height, the text and transport sit within it. */
  --np-pad-v: min(16px, calc(var(--np-slot-h, 999px) * 0.134));
  /* 2px less than --np-pad-v - top/bottom read as slightly heavier than left at the same value, tuned down on request. */
  --np-pad-tb: min(14px, calc(var(--np-slot-h, 999px) * 0.117));
  --np-art-size: min(108px, calc(var(--np-slot-h, 999px) - 2 * var(--np-pad-tb)));
  --np-row-gap: 7px;
  --np-track-gap: 9px;
  /* Desktop's title/sub read as loud as the entity grid's own tile names despite living in a peripheral,
     ambient corner widget — sized down a step so it reads as glanceable status, not a second headline. */
  /* Also min(): past five tiles the text column, not the artwork, is what
     would drive the card past its slot. */
  --np-title-size: min(16px, calc(var(--np-slot-h, 999px) * 0.30));
  --np-sub-size: min(14px, calc(var(--np-slot-h, 999px) * 0.26));
}

/* Minimise/expand motion, lifted from hemma_badge_base's entrance with the origin moved to the header's waveform toggle.
   Lives on ha-card because it's the element carrying the backdrop-filter — animating any ancestor moves the backdrop root up and the tile spends the animation sampling an empty layer (see hemma_badge_base's `translate` note).
   Uses translate/scale (not transform) so --np-swap's WAAPI transform animations compose instead of clobbering these mid-swap. */
:host{
  --np-enter-t: calc(1 - var(--np-min, 0));
  --np-enter-p: var(--np-min, 0);
  /* Was a 30px shift, a 20px lift and a 0.22 depth with a 0.07 squash -
     a droplet flying to the toggle. The refined motion is a uniform scale
     in place, so the shift and the squash are gone and the depth is what
     reads as a settle rather than a flight. Reduced motion takes this path
     on its own, so it has to say the same thing as the keyframes. */
  --np-enter-shift: 0px;
  --np-enter-lift: 0px;
  --np-enter-depth: 0.08;
  --np-enter-squash: 0;
  --np-enter-dur: calc(0.34s + var(--np-enter-t) * 0.14s);
  --np-enter-fade: calc(0.20s + var(--np-enter-t) * 0.05s);
  --np-enter-ease: cubic-bezier(0.34, 1.26, 0.44, 1);
}

ha-card{
  /* Real CSS enforcement of --np-max-w (see styles.card comment for why). */
  max-width: var(--np-max-w, calc(var(--hemma-u-np, 10px) * 40)) !important;
  transform-origin: 100% 0%;
  translate:
    calc(var(--np-enter-p) * var(--np-enter-shift))
    calc(var(--np-enter-p) * var(--np-enter-lift));
  scale:
    calc(1 - var(--np-enter-p) * (var(--np-enter-depth) - var(--np-enter-squash)))
    calc(1 - var(--np-enter-p) * (var(--np-enter-depth) + var(--np-enter-squash)));
  opacity: calc(var(--np-enter-t, 1) * var(--np-has-src, 1));
  /* Empty tile shouldn't stay tappable - it still occupies its slot until the row drops it. */
  pointer-events: var(--np-src-ptr, auto);
  cursor: pointer;
  transition: none !important;
  /* translate/scale/opacity above are the RESTING state only - the WAAPI spring (driven by the shell's --np-min) owns the motion, so they're deliberately excluded from this transition list. */
  transition-property: backdrop-filter, -webkit-backdrop-filter !important;
  transition-duration: .15s !important;
  transition-timing-function: ease !important;
}

/* Only :host::after gets this copy - #container::before is inside ha-card and already inherits its scale as an ancestor, so adding the same transform again would square it. */
:host::after{
  transform-origin: 100% 0%;
  translate:
    calc(var(--np-enter-p) * var(--np-enter-shift))
    calc(var(--np-enter-p) * var(--np-enter-lift));
  scale:
    calc(1 - var(--np-enter-p) * (var(--np-enter-depth) - var(--np-enter-squash)))
    calc(1 - var(--np-enter-p) * (var(--np-enter-depth) + var(--np-enter-squash)));
  /* No transition: shell drives this via the same WAAPI keyframes (pseudoElement) as ha-card, so rim/specular spring together. */
}

ha-ripple, mwc-ripple { display: none !important; }

:host{
  --hemma-card-hover-shadow: var(--np-shadow);
  --hemma-card-hover-filter: none;
}

/* Poster - same declarative binding the bloom above uses (--np-art), just sharp instead of blurred. */
.np-art-img{
  position: absolute;
  inset: 0;
  background-image: var(--np-art, none);
  background-size: cover;
  background-position: center;
  background-color: rgba(255,255,255,0.08);
}

#art::after{
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  pointer-events: none;
  box-shadow: inset 0 0 0 0.5px rgba(255,255,255,0.12);
}

/* Artwork bloom */
ha-card::before{
  content: '';
  position: absolute;
  inset: -40%;
  z-index: 0;
  background-image: var(--np-art, none);
  background-size: cover;
  background-position: center;
  filter: blur(52px) saturate(150%);
  opacity: calc(var(--np-has-art, 0) * var(--np-bloom-strength, 0.30));
  transform: translateZ(0);
  pointer-events: none;
  transition: opacity .45s ease;
}

/* Readability scrim. --np-scrim-mult (set alongside --hemma-badge-body-tint above) scales it down in light mode. */
ha-card::after{
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  background: linear-gradient(105deg,
    rgba(0,0,0,calc(var(--np-has-art, 0) * 0.42 * var(--np-scrim-mult, 1))) 0%,
    rgba(0,0,0,calc(var(--np-has-art, 0) * 0.16 * var(--np-scrim-mult, 1))) 62%,
    rgba(0,0,0,calc(var(--np-has-art, 0) * 0.30 * var(--np-scrim-mult, 1))) 100%);
  pointer-events: none;
}

/* Glass surface */
:host::after{
  content: '';
  position: absolute;
  inset: 0;
  pointer-events: none;
  border-radius: var(--np-inner-radius, calc(var(--hemma-u-np, 10px) * 2.6));
  z-index: 6;
  --np-rim-side:      var(--hemma-badge-rim-side-blur, 2px) var(--hemma-badge-rim-side-spread, -1px) rgba(0,0,0,var(--hemma-badge-rim-side, 0.98));
  --np-rim-bottom:    0 1px 1px -1px rgba(0,0,0,var(--hemma-badge-rim-bottom, 0.14));
  --np-rim-top:       0 -1px 1px -1px rgba(0,0,0,var(--hemma-badge-rim-top, 0.12));
  /* ── BOTTOM DROP SHADOW ── the same token the dropdowns float on, so the
     tile and a menu opened beside it cannot read as two different heights.
     Tune the whole shadow with --np-elevation, or `none` to remove it. */
  --np-rim-elevation: var(--np-elevation,
    var(--hemma-elevation-floating, 0 8px 20px rgba(0,0,0,0.13)));
  box-shadow:
    var(--hemma-badge-rim-side-offset, 1px) 0 var(--np-rim-side),
    calc(-1 * var(--hemma-badge-rim-side-offset, 1px)) 0 var(--np-rim-side),
    var(--np-rim-bottom),
    var(--np-rim-top),
    var(--np-rim-elevation);
  /* --np-has-src as well, exactly as ha-card does it. This pseudo is on the
     HOST, outside the card, so the card fading out left the rim and its
     drop shadow still painting. One tile per panel never showed it; a stack
     of seven with six empty drew six empty rectangles. */
  opacity: calc(var(--np-glass, 1) * var(--np-enter-t, 1) * var(--np-has-src, 1));
}

/* Specular ring + inner hairline - ONE pseudo-element. These used to be two separate #container::before
   rule blocks; an element can only have one ::before, so CSS was merging them property-by-property, and
   the second block's mismatched border-radius (17px, vs. --np-inner-radius elsewhere) silently won over
   the first — which is exactly why the hairline's straight edge stopped short of the card's actual
   (26px) rounded corner instead of tracing it. Merged so both layers share the real radius, and the
   hairline's box-shadow now rides the same top-to-bottom mask as the ring — which is also the fix for
   "the highlight should fade out as it curves around the corner" rather than cutting off. */
#container::before{
  content: '';
  position: absolute;
  /* Inset tracks --np-pad-tb/--np-pad-v (not hardcoded) so this reaches the card's true edge as padding changes; right stays literal -16px matching the padding shorthand. */
  inset: calc(-1 * var(--np-pad-tb, var(--np-pad-v, 16px))) -16px
         calc(-1 * var(--np-pad-tb, var(--np-pad-v, 16px))) calc(-1 * var(--np-pad-v, 16px));
  border-radius: var(--np-inner-radius, calc(var(--hemma-u-np, 10px) * 2.6));
  pointer-events: none;
  z-index: 5;
  padding: var(--hemma-badge-ring-thickness, 1.3px);
  backdrop-filter: var(--hemma-badge-ring-backdrop, brightness(var(--hemma-badge-ring-boost, 1.5)) saturate(var(--hemma-badge-ring-sat, 1.8)));
  -webkit-backdrop-filter: var(--hemma-badge-ring-backdrop, brightness(var(--hemma-badge-ring-boost, 1.5)) saturate(var(--hemma-badge-ring-sat, 1.8)));
  mix-blend-mode: screen;
  box-shadow:
    inset 0 0.5px 0 rgba(255,255,255,0.34),
    inset 0 0 0 0.5px rgba(255,255,255,0.10),
    inset 0 -0.5px 0 rgba(255,255,255,0.10);
  -webkit-mask:
    linear-gradient(to bottom,
      rgba(0,0,0,.5) 0%,
      rgba(0,0,0,0.15) 32%,
      rgba(0,0,0,0) 45%,
      rgba(0,0,0,0) 55%,
      rgba(0,0,0,0.07) 68%,
      rgba(0,0,0,0.05) 100%),
    linear-gradient(#000 0 0) content-box,
    linear-gradient(#000 0 0);
  -webkit-mask-composite: source-in, xor;
          mask-composite: intersect, exclude;
  opacity: var(--np-glass, 1);
  transform: translateZ(0);
  backface-visibility: hidden;
}

#container{
  position: relative;
  z-index: 2;
  /* button-card's shadow DOM makes this a flex/grid child of ha-card (default min-width:auto refuses to shrink below content) - without this, an unwrapped long title could grow ha-card past its max-width caps. */
  min-width: 0;
}

/* Hover tint */
#container::after{
  content: '';
  position: absolute;
  inset: calc(-1 * var(--np-pad-tb, var(--np-pad-v, 16px))) -16px
         calc(-1 * var(--np-pad-tb, var(--np-pad-v, 16px))) calc(-1 * var(--np-pad-v, 16px));
  border-radius: var(--np-inner-radius, calc(var(--hemma-u-np, 10px) * 2.6));
  pointer-events: none;
  z-index: 5;
  background: rgba(255,255,255,0.05);
  opacity: 0;
  transition: opacity .40s ease;
}

@media (hover: hover) {
  ha-card:hover #container::after{
    opacity: 0.6;
    transition: opacity .18s ease;
  }
}

.np-meta{
  display: flex;
  flex-direction: column;
  gap: 1px;
  min-width: 0;
}

.np-title{
  font-size: var(--np-title-size, 16px);
  font-weight: 600;
  letter-spacing: -0.2px;
  line-height: 1.15;
  color: var(--primary-text-color, #fff);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  /* overflow clips at the padding box, or descenders lose their tails. */
  padding-block: 0.16em;
  margin-block: -0.16em;
}

.np-sub{
  font-size: var(--np-sub-size, 14px);
  font-weight: 400;
  letter-spacing: -0.1px;
  line-height: 1.18;
  color: rgba(255,255,255,0.62);
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  padding-block: 0.16em;
  margin-block: -0.16em;
}

.np-track{
  margin-top: var(--np-track-gap, 12px);
  height: calc(var(--hemma-u-np, 10px) * 0.4);
  border-radius: 999px;
  background: rgba(255,255,255,0.16);
  overflow: hidden;
}

.np-fill{
  height: 100%;
  width: 100%;
  border-radius: 999px;
  background: var(--np-accent, #67f5a0);
  transform-origin: left center;
}

.np-line{
  overflow: hidden;
  min-width: 0;
}

.np-line > .np-title,
.np-line > .np-sub{
  display: inline-block;
  max-width: none;
}

/* Right fade only at rest - left fade animates in separately below (avoids dimming the first char before it's actually scrolled). */
.np-line.np-scroll{
  -webkit-mask-image: linear-gradient(90deg,
    #000 0px, #000 calc(100% - 18px), transparent 100%);
  mask-image: linear-gradient(90deg,
    #000 0px, #000 calc(100% - 18px), transparent 100%);
  animation: np-marquee-fade var(--np-marquee-dur, 12s) linear infinite;
  animation-delay: var(--np-mq-delay, 0s);
}

/* Offsets (0-12%, 24-100%) match np-marquee's own pause window below - keep them synced if either changes. */
@keyframes np-marquee-fade{
  0%, 12%{
    -webkit-mask-image: linear-gradient(90deg,
      #000 0px, #000 0px, #000 calc(100% - 18px), transparent 100%);
    mask-image: linear-gradient(90deg,
      #000 0px, #000 0px, #000 calc(100% - 18px), transparent 100%);
  }
  24%, 100%{
    -webkit-mask-image: linear-gradient(90deg,
      transparent 0px, #000 7px, #000 calc(100% - 18px), transparent 100%);
    mask-image: linear-gradient(90deg,
      transparent 0px, #000 7px, #000 calc(100% - 18px), transparent 100%);
  }
}

.np-marquee-clone{
  display: inline-block;
}

.np-line.np-scroll > .np-title,
.np-line.np-scroll > .np-sub{
  animation: np-marquee var(--np-marquee-dur, 12s) linear infinite;
}

.np-line.np-scroll > .np-title,
.np-line.np-scroll > .np-sub{
  animation-delay: var(--np-mq-delay, 0s);
}

@keyframes np-marquee{
  0%,  12% { transform: translateX(0); }
  100%     { transform: translateX(calc(-1 * var(--np-mq, 0px))); }
}

@media (prefers-reduced-motion: reduce){
  .np-line.np-scroll > .np-title,
  .np-line.np-scroll > .np-sub{ animation: none !important; }
  .np-line.np-scroll{
    animation: none !important;
    -webkit-mask-image: none;
    mask-image: none;
  }
  .np-marquee-clone{ display: none; }
}

@keyframes np-advance { to { transform: scaleX(1); } }

@media (prefers-reduced-motion: reduce) {
  .np-fill{ animation: none !important; }
}

/* Tablet (touch, 768-1400px) - desktop/mouse keeps the larger :host defaults above. */
@media (min-width: 768px) and (max-width: 1400px) and (min-height: 501px) and (pointer: coarse),
       (min-width: 768px) and (max-width: 1400px) and (min-height: 501px) and (hover: none) {
  /* The phone's tile scaled to a tablet's corner: same layout, smaller numbers. */
  :host{
    --np-art-size: min(76px, calc(var(--np-slot-h, 999px) - 2 * var(--np-pad-tb)));
    --np-title-size: min(14px, calc(var(--np-slot-h, 999px) * 0.30));
    --np-sub-size: min(12px, calc(var(--np-slot-h, 999px) * 0.26));
    --np-pad-v: min(12px, calc(var(--np-slot-h, 999px) * 0.134));
    --np-pad-tb: min(12px, calc(var(--np-slot-h, 999px) * 0.117));
    --np-row-gap: 6px;
    --np-track-gap: 8px;
  }
}

/* Mobile */
@media (max-width: 600px){
  :host{
    /* 108 not 100: art must stay ≥ text column height (~107px with 44px transport) or the column drives card height. */
    --np-art-size: 108px;
    --np-title-size: 16px;
    --np-sub-size: 14px;
    --np-pad-v: 16px;
    --np-row-gap: 7px;
    --np-track-gap: 9px;
    /* Lower than desktop: tiles are usually darker than the wallpaper, so full elevation reads as haze. */
    --np-elevation: 0 1px 6px rgba(0,0,0,0.10);
    /* Phone slots are sized by the row itself, so the desktop cap and right-align both come off here. */
    max-width: 100% !important;
    margin-left: 0;
  }
}

/* Phone landscape. Without this the tile fell through EVERY breakpoint - 932px wide fails the
   mobile query's max-width:600px, and 430px tall fails the tablet query's min-height:501px — so
   it silently used the desktop defaults (94px art, 16px padding, 15px title) on the shortest
   viewport there is. Same condition the theme uses for phone landscape.
   --np-pad-tb is restated deliberately: it is set unconditionally on :host, so it does NOT
   inherit this block's --np-pad-v (see the note on the desktop declaration). */
@media (hover: none) and (pointer: coarse) and (orientation: landscape) and (max-height: 600px) {
  :host{
    --np-art-size: 112px;
    --np-title-size: 16px;
    --np-sub-size: 14px;
    --np-pad-v: 12px;
    --np-pad-tb: 10px;
    --np-row-gap: 5px;
    --np-track-gap: 6px;
    --np-elevation: 0 1px 6px rgba(0,0,0,0.10);
    /* Slot width is owned by the row, as on portrait mobile. */
    max-width: 100% !important;
    margin-left: 0;
  }
}

hemma_popup.style:
[[[
  /* 500 for the main list plus the card's own 26px gutters. The
     attention column adds 318 on top; the main list never resizes. */
  // Must pick batteries exactly as the list below does, or the surface widens for an aside that never draws.
  const _pairs = variables.battery_entities || {};
  const _filter = variables.batteries || variables.entity_filter
    || (Object.keys(_pairs).length ? Object.keys(_pairs).map(k => _pairs[k]) : null);
  const _b = (_filter ? _filter.map(id => states[id]).filter(Boolean) : Object.values(states))
    .filter(e => e.state !== 'unavailable' && e.state !== 'unknown'
      && !isNaN(parseFloat(e.state)) && e.attributes?.device_class === 'battery');
  const _lo = _b.filter(e => Math.round(parseFloat(e.state)) <= 20).length;
  const _w = (_lo > 0 && _b.length > _lo) ? 870 : 552;
  return '--popup-min-width: min(' + _w + 'px, 92vw);'
       + ' --popup-max-width: min(' + _w + 'px, 92vw);';
]]]

popup_styles.styles:
/* No pane. The header sits on the room and each section stands in
   front of it as its own card, the way iOS groups settings on a
   background rather than inside one box. The room is still blurred,
   by the scrim, which is a sibling of the surface and so survives
   the pane going transparent. */
--hemma-popup-tint: transparent;
--hemma-popup-gutter-wide: 34px;
--hemma-popup-gutter-phone: 22px;
/* The close control's box starts at the bar's padding and the
   content starts at its own gutter; they line up only when the
   two are the same number. */
/* The popups have no pane, so headings and captions sit straight
   on the room. 6px is enough behind a panel and not enough behind
   bare text - this is scoped to the pane-less popups rather than
   raised globally, so the cover and lock sheets keep the lighter
   scrim they are built against. */
--hemma-popup-scrim-backdrop: blur(22px) saturate(1.5);
--hemma-popup-backdrop: none;
--hemma-popup-shadow: none;
/* The grain is two pseudo-elements on .glass, blending overlay and
   screen. They keep painting after the tint goes transparent, and a
   screen blend over noise is exactly the pale panel that survived
   the first attempt. */
/* Removed, not hidden: at opacity 0 the blend layer is invisible
   and costs the same as a visible one. */
--hemma-popup-grain-content: none;
--hemma-popup-grain: 0;
--hemma-popup-grain-dark: 0;
--hemma-popup-scrim: rgba(0, 0, 0, 0.26);

/* No chart here, so nothing to wait for. Read by each widget for
   itself, never by a wrapper - an animated opacity on an ancestor
   flattens the frost inside it. */
--hemma-popup-plate-enter:
  hemma-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --hemma-popup-plate-enter: none;
}

/* The surface is sized from the content by the style template
   below: two columns need the full measure, one does not, and a
   narrow card centered in a wide surface put the plate's edge 80px
   to the right of the close control. */

--hemma-popup-hero-label-size: 15px;
--hemma-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--hemma-card-hover-filter: none;
--hemma-hover-filter: none;
--hemma-card-hover-shadow: none;

--hemma-popup-row-pad-x: 26px;
--hemma-popup-row-pad-y: 15px;
--hemma-popup-plate-backdrop: blur(24px) saturate(180%);
--hemma-popup-chart-fill: rgba(10, 12, 16, 0.68);
--hemma-popup-row-fill: rgba(12, 14, 19, 0.62);
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--hemma-popup-plate-shadow:
  0 10px 24px -14px rgba(0, 0, 0, 0.32),
  0 2px 6px -4px rgba(0, 0, 0, 0.22);

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */
/* The sheet's drag handle keeps working; only the little bar
   that advertises it goes. Nothing else on these popups is a hint. */
--hemma-popup-grabber: transparent;

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--hemma-popup-chrome-enter:
  hemma-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--hemma-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--hemma-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--hemma-popup-plate-backdrop, none);
  box-shadow: var(--hemma-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

hemma_popup.content:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const iconOverrides = variables.device_icons || {};
  const nameOverrides = variables.device_names || {};
  const pairs = variables.battery_entities || {};

  const primaryOf = {};
  Object.keys(pairs).forEach(primary => {
    if (pairs[primary]) primaryOf[pairs[primary]] = primary;
  });

  const filterList = variables.batteries
    || variables.entity_filter
    || (Object.keys(pairs).length ? Object.keys(pairs).map(k => pairs[k]) : null);

  const allBatteries = (filterList
      ? filterList.map(id => states[id]).filter(Boolean)
      : Object.values(states)
    )
    .map(e => ({
      ...e,
      battery_pct: parseFloat(e.state)
    }))
    .filter(e => {
      if (e.state === 'unavailable' || e.state === 'unknown') return false;
      if (isNaN(e.battery_pct)) return false;

      return e.attributes.device_class === 'battery';
    })
    .sort((a, b) => a.battery_pct - b.battery_pct);

  const batteryEntityIds = allBatteries.map(e => e.entity_id);

  const reg = (hass && hass.entities) || {};
  const devReg = (hass && hass.devices) || {};

  const siblingsOf = {};
  Object.keys(reg).forEach(id => {
    const dev = reg[id] && reg[id].device_id;
    if (!dev) return;
    (siblingsOf[dev] = siblingsOf[dev] || []).push(id);
  });

  const STRONG_DOMAINS = ['lock', 'cover', 'vacuum', 'camera', 'climate', 'fan', 'light', 'media_player', 'humidifier', 'valve', 'lawn_mower', 'water_heater'];

  const ICON_DOMAIN = {
    lock: 'lock',
    vacuum: 'vacuum',
    camera: 'camera|mdi:cctv',
    light: 'light',
    fan: 'fan',
    media_player: 'speaker',
    climate: 'thermostat',
    humidifier: 'humidifier',
    water_heater: 'hot_water',
    person: 'person',
    valve: 'valve|mdi:valve',
    lawn_mower: 'mower|mdi:robot-mower',
    remote: 'remote|mdi:remote',
    switch: 'plug',
    device_tracker: 'phone|mdi:cellphone',
  };

  const ICON_COVER_CLASS = {
    curtain: 'curtain-closed',
    blind: 'curtain-closed',
    shade: 'curtain-closed',
    shutter: 'curtain-closed',
    awning: 'curtain-closed',
    door: 'door-closed',
    garage: 'garage|mdi:garage',
    gate: 'gate|mdi:gate',
    window: 'window|mdi:window-closed-variant',
  };

  const ICON_BINARY_CLASS = {
    motion: 'person-walking-motion',
    occupancy: 'person-walking-motion',
    presence: 'person',
    door: 'door-closed',
    opening: 'door-closed',
    window: 'window|mdi:window-closed-variant',
    garage_door: 'garage|mdi:garage',
    moisture: 'leak|mdi:water-alert',
    smoke: 'smoke|mdi:smoke-detector',
    gas: 'gas',
    vibration: 'vibration|mdi:vibrate',
    sound: 'sound|mdi:ear-hearing',
  };

  const TEXT_RULES = [
    ['iphone|pixel|galaxy|oneplus|phone', 'phone|mdi:cellphone'],
    ['ipad|tablet', 'tablet|mdi:tablet'],
    ['watch', 'watch|mdi:watch'],
    ['macbook|laptop|imac|mac ?(mini|studio|pro)', 'laptop|mdi:laptop'],
    ['airpod|headphone|earbud|buds', 'headphones|mdi:headphones'],
    ['keypad', 'keypad|mdi:dialpad'],
    ['doorbell|chime', 'doorbell'],
    ['lock|deadbolt', 'lock'],
    ['curtain|blind|shade|shutter', 'curtain-closed'],
    ['vacuum|roomba|robot', 'vacuum'],
    ['camera|cam\\b', 'camera|mdi:cctv'],
    ['motion|presence|occupancy|pir', 'motion'],
    ['thermostat|radiator|trv|climate', 'thermostat'],
    ['speaker|sonos|homepod|echo', 'speaker'],
    ['remote', 'remote|mdi:remote'],
    ['plant|soil', 'plant'],
    ['leak|moisture|water', 'leak|mdi:water-alert'],
    ['smoke|fire', 'smoke|mdi:smoke-detector'],
    ['door|contact', 'door-closed'],
    ['window', 'window|mdi:window-closed-variant'],
    ['light|lamp|bulb', 'light'],
    ['plug|outlet|socket', 'plug'],
    ['temperature|thermo', 'temp-medium'],
    ['motion|sensor', 'motion'],
  ];

  const pickIcon = spec => {
    if (!spec || spec.indexOf('|') === -1) return spec;
    const parts = spec.split('|');
    const set = window.HEMMA_ICONS;
    return (set && set[parts[0]]) ? parts[0] : parts[1];
  };

  const iconFromText = text => {
    if (!text) return null;
    const hay = String(text).toLowerCase();
    for (let i = 0; i < TEXT_RULES.length; i++) {
      if (new RegExp(TEXT_RULES[i][0]).test(hay)) return TEXT_RULES[i][1];
    }
    return null;
  };

  const iconFromEntity = id => {
    if (!id) return null;
    const domain = id.split('.')[0];
    const st = states[id];
    const cls = st && st.attributes ? st.attributes.device_class : null;

    if (domain === 'cover') return ICON_COVER_CLASS[cls] || 'curtain-closed';
    if (domain === 'binary_sensor') return ICON_BINARY_CLASS[cls] || null;
    return ICON_DOMAIN[domain] || null;
  };

  const resolveDevice = batteryId => {
    const explicitPrimary = primaryOf[batteryId] || null;
    const devId = (reg[batteryId] && reg[batteryId].device_id)
      || (explicitPrimary && reg[explicitPrimary] && reg[explicitPrimary].device_id)
      || null;
    const dev = devId ? devReg[devId] : null;
    const siblings = devId ? (siblingsOf[devId] || []) : [];

    const primary = explicitPrimary
      || siblings.find(id => STRONG_DOMAINS.indexOf(id.split('.')[0]) !== -1)
      || null;

    let icon = iconOverrides[batteryId]
      || (explicitPrimary ? iconOverrides[explicitPrimary] : null)
      || null;

    if (!icon && primary) icon = iconFromEntity(primary);
    if (!icon && dev) icon = iconFromText(dev.model) || iconFromText(dev.name_by_user || dev.name);
    if (!icon) {
      icon = siblings
        .map(id => iconFromEntity(id))
        .find(Boolean) || null;
    }
    if (!icon) {
      const bs = states[batteryId];
      icon = iconFromText(bs && bs.attributes ? bs.attributes.friendly_name : null)
        || iconFromText(batteryId);
    }
    if (!icon && primary) {
      const ps = states[primary];
      if (ps && ps.attributes && ps.attributes.icon) icon = ps.attributes.icon;
    }
    if (!icon) icon = 'battery';

    if (icon.indexOf('camera') === 0 && dev
      && /doorbell/i.test((dev.model || '') + ' ' + (dev.name_by_user || dev.name || ''))) {
      icon = 'doorbell';
    }

    icon = pickIcon(icon);

    const bs = states[batteryId];
    const rawName = (bs && bs.attributes && bs.attributes.friendly_name) || batteryId;
    let name = nameOverrides[batteryId]
      || (explicitPrimary ? nameOverrides[explicitPrimary] : null)
      || (dev ? (dev.name_by_user || dev.name) : null);

    if (!name && primary) {
      const ps = states[primary];
      name = ps && ps.attributes ? ps.attributes.friendly_name : null;
    }
    if (!name) name = rawName.replace(/\s*Battery(\s+(Level|State|Percentage))?$/i, '');

    const chargeIds = siblings.filter(id => {
      if (id.indexOf('binary_sensor.') === 0) return /_charging$/.test(id);
      if (id.indexOf('sensor.') === 0) return /_battery_state$/.test(id);
      return id.indexOf('vacuum.') === 0;
    });

    return { icon: icon, name: name, charge_ids: chargeIds };
  };

  const deviceInfo = {};
  batteryEntityIds.forEach(id => { deviceInfo[id] = resolveDevice(id); });

  const cleanCardStyle = `
    :host {
      --ha-card-box-shadow:none !important;
      --button-card-box-shadow:none !important;
      --button-card-box-shadow-hover:none !important;
    }

    ha-card::before,
    ha-card::after,
    #card::before,
    #card::after,
    #container::before,
    #container::after {
      display:none !important;
    }

    ha-ripple {
      display:none !important;
    }

    ha-card {
      cursor: default !important;
    }

    @media (max-width:600px) {
      ha-card {
        padding-left:14px !important;
        padding-right:14px !important;
      }
    }
  `;

  const roomName = variables.room_name ?? T('battery.devices', 'Devices');

  const baseCardStyle = [
    { '--ha-card-box-shadow': 'none' },
    { '--button-card-box-shadow': 'none' },
    { '--button-card-box-shadow-hover': 'none' },
    { background: 'transparent' },
    { border: 'none' },
    { boxShadow: 'none' },
    { backdropFilter: 'none' },
    { WebkitBackdropFilter: 'none' },
  ];


  /* No hero: the subject is the list, not any one number. Sectioned by
     state the way Settings does, so "is anything low" reads without a
     summary stat above it. */
  const UI = window._hemmaUI;
  if (UI) {
    if (!allBatteries.length) {
      return { type: 'vertical-stack', cards: [{
        type: 'custom:button-card',
        tap_action: { action: 'none' },
        show_icon: false, show_name: false, show_label: false, show_state: false,
        card_mod: { style: cleanCardStyle
          + '\nha-card { will-change: auto !important; }' },
        styles: {
          card: [...baseCardStyle, { padding: '6px 26px 22px 26px' }],
          grid: [{ 'grid-template-areas': '"empty"' }, { 'grid-template-columns': '1fr' }],
          custom_fields: { empty: [{ 'justify-self': 'stretch' }] },
        },
        custom_fields: { empty: UI.note(T('battery.none_found', 'No battery sensors found')) },
      }] };
    }
    const pctOf = (e) => Math.round(e.battery_pct);
    const toneOf = (v) => v <= 10 ? 'bad' : v <= 20 ? 'warn' : null;
    const rowOf = (e) => {
      const info = deviceInfo[e.entity_id] || {};
      const v = pctOf(e);
      /* "Not Charging" and "Discharging" both contain "charg", so this
         matches exact states only. */
      const charging = (info.charge_ids || []).some(id => {
        const st = states[id];
        if (!st) return false;
        const v = String(st.state || '').trim().toLowerCase();
        if (id.startsWith('binary_sensor.')) return v === 'on';
        return v === 'charging';
      });
      return {
        entity: e.entity_id,
        icon: info.icon || 'battery',
        /* No tone override: the icon tile carries the device's own tile
           color so a row reads the same here as on the dashboard. The
           low-battery warning is on the percentage and the section. */
        label: info.name || e.entity_id,
        sub: charging ? T('battery.charging', 'Charging') : null,
        value: v + '%',
        valueTone: charging ? 'good' : toneOf(v),
      };
    };

    const low  = allBatteries.filter(e => pctOf(e) <= 20);
    const rest = allBatteries.filter(e => pctOf(e) > 20);

    const areas = [];
    const fields = {};
    const fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }];
    };

    // The main list is never captioned; only the aside names itself.
    if (rest.length) {
      add('rest', UI.group(rest.map(rowOf), null, null,
        { labelInside: true }));
    }
    if (low.length) {
      add('low', UI.group(low.map(rowOf), T('common.needs_attention', 'Needs attention'), null,
        { labelInside: true }));
    }

    /* The main list holds its solo width and the attention column is
       added beside it, widening the surface: a low battery must not
       reflow the list it is not in. */
    const split = areas.length === 2;
    const splitAreas = split
      ? '"' + areas.map((a) => a.replace(/"/g, '')).join(' ') + '"'
      : areas.join(' ');
    areas.forEach((a, i) => {
      const key = a.replace(/"/g, '');
      if (fstyle[key]) {
        fstyle[key].push({ overflow: 'visible' });
        fstyle[key].push({ '--hemma-popup-plate-delay': (i * 55) + 'ms' });
      }
    });

    const listCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: cleanCardStyle
        + '\nha-card { will-change: auto !important; }' },
      styles: {
        card: [...baseCardStyle, { padding: '2px 26px 22px 26px' },
               /* Only the split layout needs the full surface. Centered
                  when there is one column, so it sits under the title
                  rather than off to one side of it. */
               { 'max-width': 'none' }, { margin: '0' }],
        grid: [
          { 'grid-template-areas': splitAreas },
          { 'grid-template-columns': split
              ? 'minmax(0, 1fr) 300px' : 'minmax(0, 1fr)' },
          { 'row-gap': '18px' },
          { 'column-gap': '18px' },
          // Or the shorter list is stretched to match the taller one.
          { 'align-items': 'start' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
      /* One column below the width the surface needs for both, so the
         main list is squeezed rather than stacked. Attention goes on
         top there. extra_styles rather than card_mod, which lands late
         enough to reflow visibly. */
      extra_styles: split
        ? '@media (max-width: 940px) { #container {'
          + ' grid-template-areas: ' + [...areas].reverse().join(' ') + ' !important;'
          + ' grid-template-columns: minmax(0, 1fr) !important; } }'
        : undefined,
    };
    return { type: 'vertical-stack', cards: [listCard] };
  }

  return { type: 'vertical-stack', cards: [] };
]]]

hemma_popup.style:
[[[
  /* 500 for the main list plus the card's own 26px gutters. The
     attention column adds 318 on top; the main list never resizes. */
  // Must pick batteries exactly as the list below does, or the surface widens for an aside that never draws.
  const _pairs = variables.battery_entities || {};
  const _filter = variables.batteries || variables.entity_filter
    || (Object.keys(_pairs).length ? Object.keys(_pairs).map(k => _pairs[k]) : null);
  const _b = (_filter ? _filter.map(id => states[id]).filter(Boolean) : Object.values(states))
    .filter(e => e.state !== 'unavailable' && e.state !== 'unknown'
      && !isNaN(parseFloat(e.state)) && e.attributes?.device_class === 'battery');
  const _lo = _b.filter(e => Math.round(parseFloat(e.state)) <= 20).length;
  const _w = (_lo > 0 && _b.length > _lo) ? 870 : 552;
  return '--popup-min-width: min(' + _w + 'px, 92vw);'
       + ' --popup-max-width: min(' + _w + 'px, 92vw);';
]]]

popup_styles.styles:
/* No pane. The header sits on the room and each section stands in
   front of it as its own card, the way iOS groups settings on a
   background rather than inside one box. The room is still blurred,
   by the scrim, which is a sibling of the surface and so survives
   the pane going transparent. */
--hemma-popup-tint: transparent;
/* The close control's box starts at the bar's padding and the
   content starts at its own gutter; they line up only when the
   two are the same number. */
/* The popups have no pane, so headings and captions sit straight
   on the room. 6px is enough behind a panel and not enough behind
   bare text - this is scoped to the pane-less popups rather than
   raised globally, so the cover and lock sheets keep the lighter
   scrim they are built against. */
--hemma-popup-scrim-backdrop: blur(22px) saturate(1.5);
--hemma-popup-backdrop: none;
--hemma-popup-shadow: none;
/* The grain is two pseudo-elements on .glass, blending overlay and
   screen. They keep painting after the tint goes transparent, and a
   screen blend over noise is exactly the pale panel that survived
   the first attempt. */
/* Removed, not hidden: at opacity 0 the blend layer is invisible
   and costs the same as a visible one. */
--hemma-popup-grain-content: none;
--hemma-popup-grain: 0;
--hemma-popup-grain-dark: 0;
--hemma-popup-scrim: rgba(0, 0, 0, 0.26);

/* No chart here, so nothing to wait for. Read by each widget for
   itself, never by a wrapper - an animated opacity on an ancestor
   flattens the frost inside it. */
--hemma-popup-plate-enter:
  hemma-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --hemma-popup-plate-enter: none;
}

/* The surface is sized from the content by the style template
   below: two columns need the full measure, one does not, and a
   narrow card centered in a wide surface put the plate's edge 80px
   to the right of the close control. */

--hemma-popup-hero-label-size: 15px;
--hemma-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--hemma-card-hover-filter: none;
--hemma-hover-filter: none;
--hemma-card-hover-shadow: none;

--hemma-popup-row-pad-x: 26px;
--hemma-popup-row-pad-y: 15px;
--hemma-popup-plate-backdrop: blur(24px) saturate(180%);
--hemma-popup-chart-fill: rgba(10, 12, 16, 0.68);
--hemma-popup-row-fill: rgba(12, 14, 19, 0.62);
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--hemma-popup-plate-shadow:
  0 10px 24px -14px rgba(0, 0, 0, 0.32),
  0 2px 6px -4px rgba(0, 0, 0, 0.22);

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */
/* The sheet's drag handle keeps working; only the little bar
   that advertises it goes. Nothing else on these popups is a hint. */
--hemma-popup-grabber: transparent;

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--hemma-popup-chrome-enter:
  hemma-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--hemma-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--hemma-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--hemma-popup-plate-backdrop, none);
  box-shadow: var(--hemma-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

