    ['door|contact', 'door-closed'],
    ['window', 'window|mdi:window-closed-variant'],
    ['light|lamp|bulb', 'light'],
    ['plug|outlet|socket', 'plug'],
    ['temperature|thermo', 'temp-medium'],
    ['motion|sensor', 'motion'],
  ];

  const pickIcon = spec => {
    if (!spec || spec.indexOf('|') === -1) return spec;
    const parts = spec.split('|');
    const set = window.HEMMA_ICONS;
    return (set && set[parts[0]]) ? parts[0] : parts[1];
  };

  const iconFromText = text => {
    if (!text) return null;
    const hay = String(text).toLowerCase();
    for (let i = 0; i < TEXT_RULES.length; i++) {
      if (new RegExp(TEXT_RULES[i][0]).test(hay)) return TEXT_RULES[i][1];
    }
    return null;
  };

  const iconFromEntity = id => {
    if (!id) return null;
    const domain = id.split('.')[0];
    const st = states[id];
    const cls = st && st.attributes ? st.attributes.device_class : null;

    if (domain === 'cover') return ICON_COVER_CLASS[cls] || 'curtain-closed';
    if (domain === 'binary_sensor') return ICON_BINARY_CLASS[cls] || null;
    return ICON_DOMAIN[domain] || null;
  };

  const resolveDevice = batteryId => {
    const explicitPrimary = primaryOf[batteryId] || null;
    const devId = (reg[batteryId] && reg[batteryId].device_id)
      || (explicitPrimary && reg[explicitPrimary] && reg[explicitPrimary].device_id)
      || null;
    const dev = devId ? devReg[devId] : null;
    const siblings = devId ? (siblingsOf[devId] || []) : [];

    const primary = explicitPrimary
      || siblings.find(id => STRONG_DOMAINS.indexOf(id.split('.')[0]) !== -1)
      || null;

    let icon = iconOverrides[batteryId]
      || (explicitPrimary ? iconOverrides[explicitPrimary] : null)
      || null;

    if (!icon && primary) icon = iconFromEntity(primary);
    if (!icon && dev) icon = iconFromText(dev.model) || iconFromText(dev.name_by_user || dev.name);
    if (!icon) {
      icon = siblings
        .map(id => iconFromEntity(id))
        .find(Boolean) || null;
    }
    if (!icon) {
      const bs = states[batteryId];
      icon = iconFromText(bs && bs.attributes ? bs.attributes.friendly_name : null)
        || iconFromText(batteryId);
    }
    if (!icon && primary) {
      const ps = states[primary];
      if (ps && ps.attributes && ps.attributes.icon) icon = ps.attributes.icon;
    }
    if (!icon) icon = 'battery';

    if (icon.indexOf('camera') === 0 && dev
      && /doorbell/i.test((dev.model || '') + ' ' + (dev.name_by_user || dev.name || ''))) {
      icon = 'doorbell';
    }

    icon = pickIcon(icon);

    const bs = states[batteryId];
    const rawName = (bs && bs.attributes && bs.attributes.friendly_name) || batteryId;
    let name = nameOverrides[batteryId]
      || (explicitPrimary ? nameOverrides[explicitPrimary] : null)
      || (dev ? (dev.name_by_user || dev.name) : null);

    if (!name && primary) {
      const ps = states[primary];
      name = ps && ps.attributes ? ps.attributes.friendly_name : null;
    }
    if (!name) name = rawName.replace(/\s*Battery(\s+(Level|State|Percentage))?$/i, '');

    const chargeIds = siblings.filter(id => {
      if (id.indexOf('binary_sensor.') === 0) return /_charging$/.test(id);
      if (id.indexOf('sensor.') === 0) return /_battery_state$/.test(id);
      return id.indexOf('vacuum.') === 0;
    });

    return { icon: icon, name: name, charge_ids: chargeIds };
  };

  const deviceInfo = {};
  batteryEntityIds.forEach(id => { deviceInfo[id] = resolveDevice(id); });

  const cleanCardStyle = `
    :host {
      --ha-card-box-shadow:none !important;
      --button-card-box-shadow:none !important;
      --button-card-box-shadow-hover:none !important;
    }

    ha-card::before,
    ha-card::after,
    #card::before,
    #card::after,
    #container::before,
    #container::after {
      display:none !important;
    }

    ha-ripple {
      display:none !important;
    }

    ha-card {
      cursor: default !important;
    }

    @media (max-width:600px) {
      ha-card {
        padding-left:14px !important;
        padding-right:14px !important;
      }
    }
  `;

  const roomName = variables.room_name ?? T('battery.devices', 'Devices');

  const baseCardStyle = [
    { '--ha-card-box-shadow': 'none' },
    { '--button-card-box-shadow': 'none' },
    { '--button-card-box-shadow-hover': 'none' },
    { background: 'transparent' },
    { border: 'none' },
    { boxShadow: 'none' },
    { backdropFilter: 'none' },
    { WebkitBackdropFilter: 'none' },
  ];


  /* No hero: the subject is the list, not any one number. Sectioned by
     state the way Settings does, so "is anything low" reads without a
     summary stat above it. */
  const UI = window._hemmaUI;
  if (UI) {
    if (!allBatteries.length) {
      return { type: 'vertical-stack', cards: [{
        type: 'custom:button-card',
        tap_action: { action: 'none' },
        show_icon: false, show_name: false, show_label: false, show_state: false,
        card_mod: { style: cleanCardStyle
          + '\nha-card { will-change: auto !important; }' },
        styles: {
          card: [...baseCardStyle, { padding: '6px 26px 22px 26px' }],
          grid: [{ 'grid-template-areas': '"empty"' }, { 'grid-template-columns': '1fr' }],
          custom_fields: { empty: [{ 'justify-self': 'stretch' }] },
        },
        custom_fields: { empty: UI.note(T('battery.none_found', 'No battery sensors found')) },
      }] };
    }
    const pctOf = (e) => Math.round(e.battery_pct);
    const toneOf = (v) => v <= 10 ? 'bad' : v <= 20 ? 'warn' : null;
    const rowOf = (e) => {
      const info = deviceInfo[e.entity_id] || {};
      const v = pctOf(e);
      /* "Not Charging" and "Discharging" both contain "charg", so this
         matches exact states only. */
      const charging = (info.charge_ids || []).some(id => {
        const st = states[id];
        if (!st) return false;
        const v = String(st.state || '').trim().toLowerCase();
        if (id.startsWith('binary_sensor.')) return v === 'on';
        return v === 'charging';
      });
      return {
        entity: e.entity_id,
        icon: info.icon || 'battery',
        /* No tone override: the icon tile carries the device's own tile
           color so a row reads the same here as on the dashboard. The
           low-battery warning is on the percentage and the section. */
        label: info.name || e.entity_id,
        sub: charging ? T('battery.charging', 'Charging') : null,
        value: v + '%',
        valueTone: charging ? 'good' : toneOf(v),
      };
    };

    const low  = allBatteries.filter(e => pctOf(e) <= 20);
    const rest = allBatteries.filter(e => pctOf(e) > 20);

    const areas = [];
    const fields = {};
    const fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }];
    };

    // The main list is never captioned; only the aside names itself.
    if (rest.length) {
      add('rest', UI.group(rest.map(rowOf), null, null,
        { labelInside: true }));
    }
    if (low.length) {
      add('low', UI.group(low.map(rowOf), T('common.needs_attention', 'Needs attention'), null,
        { labelInside: true }));
    }

    /* The main list holds its solo width and the attention column is
       added beside it, widening the surface: a low battery must not
       reflow the list it is not in. */
    const split = areas.length === 2;
    const splitAreas = split
      ? '"' + areas.map((a) => a.replace(/"/g, '')).join(' ') + '"'
      : areas.join(' ');
    areas.forEach((a, i) => {
      const key = a.replace(/"/g, '');
      if (fstyle[key]) {
        fstyle[key].push({ overflow: 'visible' });
        fstyle[key].push({ '--hemma-popup-plate-delay': (i * 55) + 'ms' });
      }
    });

    const listCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: cleanCardStyle
        + '\nha-card { will-change: auto !important; }' },
      styles: {
        card: [...baseCardStyle, { padding: '2px 26px 22px 26px' },
               /* Only the split layout needs the full surface. Centered
                  when there is one column, so it sits under the title
                  rather than off to one side of it. */
               { 'max-width': 'none' }, { margin: '0' }],
        grid: [
          { 'grid-template-areas': splitAreas },
          { 'grid-template-columns': split
              ? 'minmax(0, 1fr) 300px' : 'minmax(0, 1fr)' },
          { 'row-gap': '18px' },
          { 'column-gap': '18px' },
          // Or the shorter list is stretched to match the taller one.
          { 'align-items': 'start' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
      /* One column below the width the surface needs for both, so the
         main list is squeezed rather than stacked. Attention goes on
         top there. extra_styles rather than card_mod, which lands late
         enough to reflow visibly. */
      extra_styles: split
        ? '@media (max-width: 940px) { #container {'
          + ' grid-template-areas: ' + [...areas].reverse().join(' ') + ' !important;'
          + ' grid-template-columns: minmax(0, 1fr) !important; } }'
        : undefined,
    };
    return { type: 'vertical-stack', cards: [listCard] };
  }

  return { type: 'vertical-stack', cards: [] };
]]]

hemma_camera_alert_helper.value:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
  if (typeof window.hemmaCameraAlert !== 'function') {
    /* Ring publishes ding/motion as event.* entities whose state is the
       timestamp of the last one, so "recent" is the whole alert model.
       Reading sensor.time subscribes the caller to the minute tick, which
       is what lets a stale alert expire without another camera event. */
    window.hemmaCameraAlert = function (hass, states, cams, windowMinutes) {
      const reg = (hass && hass.entities) || {};
      const devs = {};
      cams.forEach(function (id) {
        const d = reg[id] && reg[id].device_id;
        if (d) devs[d] = true;
      });
      const span = (Number(windowMinutes) > 0 ? Number(windowMinutes) : 5) * 60000;
      const now = Date.now();
      states['sensor.time'];
      let ding = false, motion = false;
      Object.keys(reg).forEach(function (id) {
        if (id.indexOf('event.') !== 0) return;
        if (!devs[reg[id].device_id]) return;
        const t = Date.parse(states[id] && states[id].state);
        if (!isFinite(t) || now - t > span) return;
        if (/ding|doorbell|button/.test(id)) ding = true;
        else if (/motion/.test(id)) motion = true;
      });
      return ding ? T('cameras.doorbell', 'Doorbell') : motion ? T('cameras.motion_detected', 'Motion Detected') : '';
    };
  }
  return true;
]]]

popup_styles.styles:
/* No pane. The header sits on the room and each section stands in
   front of it as its own card, the way iOS groups settings on a
   background rather than inside one box. The room is still blurred,
   by the scrim, which is a sibling of the surface and so survives
   the pane going transparent. */
--hemma-popup-tint: transparent;
--hemma-popup-gutter-wide: 34px;
--hemma-popup-gutter-phone: 22px;
/* The close control's box starts at the bar's padding and the
   content starts at its own gutter; they line up only when the
   two are the same number. */
/* The popups have no pane, so headings and captions sit straight
   on the room. 6px is enough behind a panel and not enough behind
   bare text - this is scoped to the pane-less popups rather than
   raised globally, so the cover and lock sheets keep the lighter
   scrim they are built against. */
--hemma-popup-scrim-backdrop: blur(22px) saturate(1.5);
--hemma-popup-backdrop: none;
--hemma-popup-shadow: none;
/* The grain is two pseudo-elements on .glass, blending overlay and
   screen. They keep painting after the tint goes transparent, and a
   screen blend over noise is exactly the pale panel that survived
   the first attempt. */
/* Removed, not hidden: at opacity 0 the blend layer is invisible
   and costs the same as a visible one. */
--hemma-popup-grain-content: none;
--hemma-popup-grain: 0;
--hemma-popup-grain-dark: 0;
--hemma-popup-scrim: rgba(0, 0, 0, 0.26);

/* No chart to wait for. Read by each widget for itself, never by a
   wrapper - an animated opacity on an ancestor flattens the frost
   inside it. */
--hemma-popup-plate-enter:
  hemma-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --hemma-popup-plate-enter: none;
}

--hemma-popup-hero-label-size: 15px;
--hemma-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--hemma-card-hover-filter: none;
--hemma-hover-filter: none;
--hemma-card-hover-shadow: none;

--hemma-popup-row-pad-x: 26px;
--hemma-popup-row-pad-y: 15px;
--hemma-popup-plate-backdrop: blur(24px) saturate(180%);
--hemma-popup-chart-fill: rgba(10, 12, 16, 0.68);
--hemma-popup-row-fill: rgba(12, 14, 19, 0.62);
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--hemma-popup-plate-shadow:
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28);

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */
/* The sheet's drag handle keeps working; only the little bar
   that advertises it goes. Nothing else on these popups is a hint. */
--hemma-popup-grabber: transparent;

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--hemma-popup-chrome-enter:
  hemma-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--hemma-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--hemma-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--hemma-popup-plate-backdrop, none);
  box-shadow: var(--hemma-popup-plate-shadow, none);
}

.content .container > * {
  width: 100% !important;
  max-width: none !important;
  box-sizing: border-box !important;
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

hemma_popup.content:
[[[
  const L = (k, en) => { const v = hass?.localize?.(k); return (v && v !== k) ? v : en; };
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
  const reg    = (hass && hass.entities) || {};
  const nameOv = variables.camera_names || {};
  const actOv  = variables.activity_entities || {};
  const exclude = Array.isArray(variables.exclude) ? variables.exclude : [];

  /* Candidate ids come from the registry, never Object.values(states) —
     that Proxy walk subscribes this card to every entity in the house. */
  let ids;
  if (Array.isArray(variables.cameras) && variables.cameras.length) {
    ids = variables.cameras.filter(Boolean);
  } else {
    ids = Object.keys(reg).filter(id => {
      if (!id.startsWith('camera.')) return false;
      const r = reg[id] || {};
      if (r.hidden || r.hidden_by || r.entity_category) return false;
      if (r.platform === 'browser_mod') return false;
      if (/_last_recording$/.test(id)) return false;
      return true;
    });
  }
  ids = ids.filter(id => !exclude.includes(id));

  const cams = ids.map(id => ({ id: id, s: states[id] })).filter(c => c.s);

  const TPL = 26;

  /* Owns the selected camera, the live card and its hass pump.
     Only one stream is ever mounted; the grid stays on stills. */
  if (window._hemmaCAMv !== TPL) {
    window._hemmaCAMv = TPL;
    window._hemmaCAM = {
      _card: null, _timer: null,

      _ha: function () { return document.querySelector('home-assistant'); },

      svc: function (domain, service, data) {
        const ha = this._ha();
        if (ha && ha.hass) ha.hass.callService(domain, service, data);
      },

      /* Mobile: the popup's swipe-dismiss handler claims touchstart, so the
         browser never synthesises a click and onclick alone never fires. Every
         control acts on touchend instead; whichever event lands first wins and
         the other is dropped inside the 900ms window. */
      act: function (event, el, name, arg) {
        if (event) {
          if (event.type === 'touchend') {
            this._lt = Date.now();
            if (event.cancelable) event.preventDefault();
          } else if (this._lt && Date.now() - this._lt < 900) {
            return;
          }
        }
        if (name === 'open') {
          if (this.holdConsumed()) return;
          this.open(arg, el);
        }
        else if (name === 'back') this.back(el);
        else if (name === 'mute') this.toggleMute(el);
        else if (name === 'fit')  this.toggleFit(el);
        else if (name === 'rec')  this.toggleRecording(arg, el);
        else if (name === 'acc')  this.accToggle(arg, el);
        else if (name === 'fs')   this.fullscreen(el);
        else if (name === 'info') this.moreInfo(arg);
      },

      /* Tap opens the camera in this popup; hold hands off to HA's own
         more-info, so both routes out of the grid are available. */
      holdPoint: function (event) {
        if (!event) return null;
        const t = event.touches && event.touches[0];
        const x = t ? t.clientX : event.clientX;
        const y = t ? t.clientY : event.clientY;
        return (x === undefined || x === null) ? null : [x, y];
      },

      /* brightness, never transform: open() measures the tile to start the
         zoom, and a scaled tile would hand it the wrong rect. */
      holdPaint: function (on) {
        const el = this._holdEl;
        if (el && el.style) el.style.filter = on ? 'brightness(0.93)' : '';
      },

      holdEnd: function () {
        if (this._holdT) { clearTimeout(this._holdT); this._holdT = null; }
        this.holdPaint(false);
      },

      holdStart: function (event, el, camId) {
        const self = this;
        self.holdEnd();
        self._holdEl = el;
        self._holdFired = false;
        self._holdXY = self.holdPoint(event);
        self.holdPaint(true);
        self._holdT = setTimeout(function () {
          self._holdT = null;
          self._holdFired = true;
          self.holdPaint(false);
          self.moreInfo(camId);
        }, 480);
      },

      holdMove: function (event) {
        if (!this._holdT || !this._holdXY) return;
        const p = this.holdPoint(event);
        if (!p) return;
        if (Math.abs(p[0] - this._holdXY[0]) > 10 || Math.abs(p[1] - this._holdXY[1]) > 10) {
          this._holdFired = false;
          this.holdEnd();
        }
      },

      /* True once the press has already become a hold, so the tap that
         follows it is dropped rather than opening the camera too. */
      holdConsumed: function () {
        this.holdEnd();
        if (!this._holdFired) return false;
        this._holdFired = false;
        return true;
      },

      /* A one-camera popup has nothing to pick from, so it opens straight on
         the live view. Fired from a 1x1 data-URI image's onload: the element is
         in the DOM by then, which is what gives us something to climb from. */
      autoOpen: function (el, camId) {
        const root = el && el.closest('.hemma-cam-root');
        if (!root || root.dataset.hemmaAuto) return;
        root.dataset.hemmaAuto = '1';
        const detail = root.querySelector('.cam-detail[data-cam="' + camId + '"]');
        const mount = detail && detail.querySelector('.cam-stream-mount');
        if (!mount) return;
        this._fit = 'cover';
        this._muted = true;
        this.mount(camId, mount);
        this.paintFit(detail);
      },

      moreInfo: function (id) {
        const ha = this._ha();
        if (!ha) return;
        ha.dispatchEvent(new CustomEvent('hass-more-info', {
          bubbles: true, composed: true, detail: { entityId: id },
        }));
      },

      /* videoWidth is unknown until metadata lands, and the scale factor needs it.
         Show the still until the video can be revealed already zoomed. */
      settle: function () {
        const self = this;
        if (self._poll) clearInterval(self._poll);
        let n = 0;
        self._poll = setInterval(function () {
          n++;
          const v = self.video();
          if (v) {
            if (!v.dataset.hemmaHeld) {
              v.dataset.hemmaHeld = '1';
              v.style.opacity = '0';
            }
            if ((v.videoWidth && v.videoHeight) || v.readyState >= 2) {
              self.applyFit(false);
              self.applyAudio();
              v.style.opacity = '1';
              self.clearBackdrop();
              clearInterval(self._poll); self._poll = null;
              return;
            }
          }
          /* Give up after 5s and drop the still regardless: a placeholder that
             outlives the poll reads as a permanently out-of-focus camera. */
          if (n > 50) {
            if (v) v.style.opacity = '1';
            self.clearBackdrop();
            clearInterval(self._poll); self._poll = null;
          }
        }, 100);
      },

      /* The tile still is painted onto the mount as a placeholder. Once the
         stream is up it would show through the letterbox bars in contain mode,
         so it has to come off as soon as the video is visible. */
      clearBackdrop: function () {
        if (this._mount) this._mount.style.backgroundImage = '';
      },

      teardown: function () {
        this._playing = false;
        if (this._poll) { clearInterval(this._poll); this._poll = null; }
        if (this._raf) { cancelAnimationFrame(this._raf); this._raf = null; }
        if (this._audT) { clearTimeout(this._audT); this._audT = null; }
        if (this._recT) { clearTimeout(this._recT); this._recT = null; }
        if (this._probeT) { clearTimeout(this._probeT); this._probeT = null; }
        if (this._probe) { try { this._probe.remove(); } catch (e) {} this._probe = null; }
        this._mount = null;
        if (this._timer) { clearInterval(this._timer); this._timer = null; }
        if (this._card) { try { this._card.remove(); } catch (e) {} this._card = null; }
      },

      mount: function (camId, mountEl) {
        const self = this;
        self.teardown();
        self._mount = mountEl;
        self._modeText = T('cameras.live', 'Live');
        const ha = self._ha();
        if (!ha || !mountEl) return;

        /* Building a picture-entity is what pulls in hui-image, and with it
           ha-camera-stream. We throw the card away and mount the player
           ourselves: hui-image hardcodes `muted`, and ha-camera-stream reads
           that flag when it PICKS a stream, not just to set volume — muted
           lets it settle on WebRTC, which for Ring has no audio track at all.
           Mounted unmuted it prefers HLS, which carries audio; we then hold
           the <video> silent ourselves until the user asks for sound. */
        Promise.resolve(window.loadCardHelpers()).then(function (h) {
          return h.createCardElement({
            type: 'picture-entity', entity: camId, camera_view: 'live',
            show_name: false, show_state: false,
          });
        }).then(function (fallback) {
          let card;
          if (customElements.get('ha-camera-stream')) {
            card = document.createElement('ha-camera-stream');
            card.controls = false;
            card.allowExoPlayer = false;
            card.muted = false;
            card.stateObj = ha.hass.states[camId];
            card.hass = ha.hass;
            self._native = true;
          } else {
            card = fallback;
            card.hass = ha.hass;
            self._native = false;
          }
          card.style.width = '100%';
          card.style.height = '100%';
          card.style.display = 'block';
          mountEl.appendChild(card);
          self._card = card;
          self.holdAudio();
          self.settle();
          /* hass is replaced per update, so re-query rather than cache. */
          self._timer = setInterval(function () {
            if (!self._card || !self._card.isConnected) { self.teardown(); return; }
            const h2 = self._ha();
            if (h2 && h2.hass) {
              self._card.hass = h2.hass;
              if (self._native && h2.hass.states[camId] !== self._card.stateObj) {
                self._card.stateObj = h2.hass.states[camId];
              }
