            self.applyAudio();
          }, 1000);
        }).catch(function () {});
      },

      /* The player is mounted unmuted so audio gets negotiated, so the first
         frames could escape before the 1s pump silences them. Ride every frame
         for the first two seconds instead. */
      holdAudio: function () {
        const self = this;
        const until = Date.now() + 2000;
        const step = function () {
          self._raf = null;
