      /* Shared-element zoom. The ghost lives inside the popup root, not body:
         the dialog is in the top layer, and the theme's will-change on ha-card
         makes position:fixed resolve against the card rather than the viewport. */
      flip: function (root, from, to, imgUrl, radius, done) {
        const rr = root.getBoundingClientRect();
        const dur = 360;
        const g = document.createElement('div');
        g.style.cssText = 'position:absolute;z-index:50;pointer-events:none;overflow:hidden;'
          + 'background-color:#000;background-size:cover;background-position:center;'
          + 'border-radius:' + radius + 'px;'
          + 'left:' + (from.left - rr.left) + 'px;top:' + (from.top - rr.top) + 'px;'
          + 'width:' + from.width + 'px;height:' + from.height + 'px;'
          + 'transform-origin:top left;'
          + 'transition:transform ' + dur + 'ms cubic-bezier(0.32,0.72,0,1),opacity 120ms ease ' + (dur - 100) + 'ms;';
        if (imgUrl) g.style.backgroundImage = 'url("' + imgUrl + '")';
        root.appendChild(g);
        g.getBoundingClientRect();
        g.style.transform = 'translate(' + (to.left - from.left) + 'px,' + (to.top - from.top) + 'px)'
          + ' scale(' + (to.width / from.width) + ',' + (to.height / from.height) + ')';
        g.style.opacity = '0';
        setTimeout(function () { try { g.remove(); } catch (e) {} if (done) done(); }, dur + 40);
      },

      open: function (camId, el) {
        const root = el.closest('.hemma-cam-root');
        if (!root) return;
        const tile = el.closest('.hemma-cam-tile') || el;
        const from = tile.getBoundingClientRect();
        const img  = tile.querySelector('img');
        const src  = img && img.style.display !== 'none' ? img.getAttribute('src') : '';

        const grid = root.querySelector('.cam-grid');
        if (grid) grid.style.display = 'none';
        let mount = null, detail = null;
        root.querySelectorAll('.cam-detail').forEach(function (d) {
          const on = d.getAttribute('data-cam') === camId;
          d.style.display = on ? 'block' : 'none';
          if (on) { detail = d; mount = d.querySelector('.cam-stream-mount'); }
        });
        if (!mount) return;

        if (src) {
          mount.style.backgroundImage = 'url("' + src + '")';
          mount.style.backgroundSize = 'cover';
          mount.style.backgroundPosition = 'center';
        }

        const to = mount.getBoundingClientRect();
        if (detail) {
          detail.style.opacity = '0';
          detail.style.transition = 'opacity 200ms ease 140ms';
          detail.getBoundingClientRect();
          detail.style.opacity = '1';
        }
        this._fit = 'cover';
        this._muted = true;
        this.flip(root, from, to, src, 20);
        this.mount(camId, mount);
        this.paintFit(detail);
      },

      back: function (el) {
        const root = el.closest('.hemma-cam-root');
        const detail = el.closest('.cam-detail');
        const camId = detail && detail.getAttribute('data-cam');
        const mount = detail && detail.querySelector('.cam-stream-mount');
        const from = mount ? mount.getBoundingClientRect() : null;
        this.clearConfirm();
        this.teardown();
        if (mount) mount.style.backgroundImage = '';
        if (!root) return;

        root.querySelectorAll('.cam-detail').forEach(function (d) {
          d.style.display = 'none';
          d.style.opacity = '';
          d.style.transition = '';
        });
        const grid = root.querySelector('.cam-grid');
        if (grid) grid.style.display = 'block';

        const tile = camId && root.querySelector('.hemma-cam-tile[data-cam="' + camId + '"]');
        if (!tile || !from) return;
        const to  = tile.getBoundingClientRect();
        const img = tile.querySelector('img');
        const src = img && img.style.display !== 'none' ? img.getAttribute('src') : '';
        if (grid) {
          grid.style.opacity = '0';
          grid.style.transition = 'opacity 200ms ease 120ms';
          grid.getBoundingClientRect();
          grid.style.opacity = '1';
        }
        this.flip(root, from, to, src, 20);
      },

      /* The <video> is several shadow roots down inside the player. */
      video: function () {
        const find = function (root, d) {
          if (!root || d > 12) return null;
          if (root.querySelector) {
            const v = root.querySelector('video');
            if (v) return v;
          }
          const kids = root.querySelectorAll ? root.querySelectorAll('*') : [];
          for (let i = 0; i < kids.length; i++) {
            if (kids[i].shadowRoot) {
              const r = find(kids[i].shadowRoot, d + 1);
              if (r) return r;
            }
          }
          return null;
        };
        if (!this._card) return null;
        if (this._card.tagName === 'VIDEO') return this._card;
        return find(this._card.shadowRoot || this._card, 0);
      },

      /* Ring's sensor is squarer than the 16:9 frame, so cover crops instead of
         letterboxing. The chain between mount and <video> has to fill for it to bite. */
      /* Runs once a second off the hass pump, so it must not touch a property
         that is already correct — rewriting inline styles under the cursor
         resets whatever the browser is drawing on top of the video. */
      applyFit: function (animate) {
        const v = this.video();
        if (!v) return;
        const mode = this.fitMode();
        const mount = this._mount;
        const set = function (el, prop, val) {
          if (el && el.style && el.style[prop] !== val) el.style[prop] = val;
        };

        set(v, 'width', '100%');
        set(v, 'height', '100%');
        set(v, 'transformOrigin', 'center center');
        set(v, 'transition', (animate ? 'transform 0.38s cubic-bezier(0.32,0.72,0,1)' : 'transform 0s')
          + ', opacity 0.18s ease');

        /* Fill every wrapper between the mount and the <video>, crossing shadow
           boundaries. Generous guard: HA nests card > image > stream > player. */
        let n = v.parentElement || (v.getRootNode() && v.getRootNode().host);
        let guard = 0;
        while (n && n !== mount && guard++ < 40) {
          set(n, 'height', '100%');
          set(n, 'width', '100%');
          n = n.parentElement || (n.getRootNode() && n.getRootNode().host);
        }

        /* object-fit can't animate, so hold `contain` and scale by exactly the
           cover/contain ratio. If the intrinsic size isn't known yet, fall back to
           plain object-fit so the frame is never left un-filled. */
        let k = 1;
        let measured = false;
        if (mode === 'cover' && v.videoWidth && v.videoHeight && mount) {
          const r = mount.getBoundingClientRect();
          if (r.width && r.height) {
            const fit  = Math.min(r.width / v.videoWidth, r.height / v.videoHeight);
            const fill = Math.max(r.width / v.videoWidth, r.height / v.videoHeight);
            if (fit > 0) { k = fill / fit; measured = true; }
          }
        }
        set(v, 'objectFit', (mode === 'cover' && !measured) ? 'cover' : 'contain');
        set(v, 'transform', 'scale(' + k.toFixed(4) + ')');
      },

      /* Not persisted: every open starts filled, the way Apple's does. */
      fitMode: function () {
        if (!this._fit) this._fit = 'cover';
        return this._fit;
      },

      toggleFit: function (el) {
        this._fit = this.fitMode() === 'cover' ? 'contain' : 'cover';
        this.applyFit(true);
        this.paintFit(el.closest('.cam-detail'));
      },

      /* One flag the CSS can select on: the active background is written
         inline, so a hover rule cannot otherwise tell a lit button from a
         dark one. */
      mark: function (el, on) {
        if (!el) return;
        if (on) el.setAttribute('data-on', '1');
        else el.removeAttribute('data-on');
      },

      paintFit: function (scope) {
        const on = this.fitMode() === 'cover';
        const btns = scope ? scope.querySelectorAll('.cam-fit') : [];
        for (let i = 0; i < btns.length; i++) {
          const b = btns[i];
          const ic = b.querySelector('ha-icon');
          b.setAttribute('data-tip', on ? T('cameras.zoom_to_fit', 'Zoom to Fit') : T('cameras.zoom_to_fill', 'Zoom to Fill'));
          this.mark(b, on);
          b.style.background = on ? 'rgba(255,255,255,0.92)' : 'var(--hemma-glass-pill-fill, rgba(255,255,255,0.12))';
          b.style.color = on ? '#1c1c1e' : 'rgba(255,255,255,0.92)';
