        this.mark(btn, !off);
        if (btn) {
          btn.style.background = off
            ? 'var(--hemma-glass-pill-fill, rgba(255,255,255,0.12))'
            : 'rgba(255,255,255,0.92)';
          btn.style.color = off ? 'rgba(255,255,255,0.92)' : '#1c1c1e';
          if (ic) ic.style.color = off ? 'rgba(255,255,255,0.92)' : '#1c1c1e';
        }
      },

      toggleMute: function (el) {
        const self = this;
        self._muted = self._muted === false;
        self.applyAudio();
        const scope = el.closest('.cam-detail');
        if (!scope) return;
        self.syncAudio(scope);
        if (self._audT) { clearTimeout(self._audT); self._audT = null; }
