      paintAcc: function (el, state) {
        if (!el || !state) return;
        const open = state === 'open';
        const self = this;
        self.mark(el, open);
        self.morph(el, function () {
          el.style.background = open ? 'rgba(255,255,255,0.92)' : 'var(--hemma-glass-pill-fill, rgba(255,255,255,0.12))';
          el.style.color = open ? '#1c1c1e' : 'rgba(255,255,255,0.92)';
          const ic = el.querySelector('ha-icon');
          const tx = el.querySelector('span');
