           decoder has actually run, so an immediate verdict always reads
           "no audio" even when there is some. */
        self._audT = setTimeout(function () {
          self._audT = null;
          if (self._muted === false && !self.hasAudio()) {
            self.setMode(scope, T('cameras.no_audio', '{mode} · no audio', { mode: self._modeText || T('cameras.live', 'Live') }));
          }
        }, 1500);
      },

      /* Apple's gesture: tap the picture to fill the screen. The frame goes,
         not the <video>, so the rounded mask and the aspect box travel with it.
         iOS has no element fullscreen — there only the video can go. */
      /* The browser can leave fullscreen without us — Esc, the system gesture,
         iOS's own Done button — so the glyph follows the document, not our call. */
      paintFs: function () {
        const on = !!(document.fullscreenElement || document.webkitFullscreenElement);
        const scope = this._fsScope;
        const b = scope && scope.querySelector('.cam-fs');
        const ic = b && b.querySelector('ha-icon');
        if (ic) ic.setAttribute('icon', on ? 'mdi:arrow-collapse' : 'mdi:arrow-expand');
      },

      watchFs: function () {
        if (this._fsBound) return;
        this._fsBound = true;
        const self = this;
        const upd = function () { self.paintFs(); };
        document.addEventListener('fullscreenchange', upd);
        document.addEventListener('webkitfullscreenchange', upd);
      },

      fullscreen: function (el) {
        const scope = el.closest('.cam-detail');
        this._fsScope = scope;
        this.watchFs();
        const box = scope && scope.querySelector('.cam-frame');
        const d = document;
        if (d.fullscreenElement || d.webkitFullscreenElement) {
          if (d.exitFullscreen) d.exitFullscreen();
          else if (d.webkitExitFullscreen) d.webkitExitFullscreen();
          return;
        }
        const landscape = function () {
          try {
            const o = window.screen && window.screen.orientation;
            if (o && o.lock) {
              const p = o.lock('landscape');
              if (p && p.catch) p.catch(function () {});
