          if (txt) el.removeAttribute('data-tip');
          else el.setAttribute('data-tip', el.getAttribute('data-label-shut') || '');
        });
      },

      /* One button owns playback: it lights up while the recording runs and
         the next tap drops back to live, so there is no second "go live"
         control needing room in the row. */
      toggleRecording: function (recId, el) {
        const scope = el.closest('.cam-detail');
        const camId = scope && scope.getAttribute('data-cam');
        if (this._playing) { this.goLive(camId, el); return; }
        if (this._probe) {
          /* Still loading. Live never stopped, so dropping the probe is enough. */
          try { this._probe.remove(); } catch (e) {}
          this._probe = null;
          if (this._probeT) { clearTimeout(this._probeT); this._probeT = null; }
          this.paintRec(scope, false);
          return;
        }
        this.playRecording(recId, el);
      },

      /* Live is still running underneath, so just say so and put the header back. */
      unavailable: function (scope) {
        const self = this;
        self.setMode(scope, T('cameras.recording_unavailable', 'Recording unavailable'));
        if (self._recT) clearTimeout(self._recT);
        self._recT = setTimeout(function () {
          self._recT = null;
          self.setMode(scope, self._modeText || T('cameras.live', 'Live'));
        }, 1800);
      },

      paintRec: function (scope, playing) {
        const b = scope && scope.querySelector('.cam-rec');
        if (!b) return;
        const ic = b.querySelector('ha-icon');
        b.style.background = playing
          ? 'rgba(255,255,255,0.92)'
          : 'var(--hemma-glass-pill-fill, rgba(255,255,255,0.12))';
        b.style.color = playing ? '#1c1c1e' : 'rgba(255,255,255,0.92)';
        b.setAttribute('data-tip', playing ? T('cameras.live', 'Live') : T('cameras.last_recording', 'Last Recording'));
        this.mark(b, playing);
        if (ic) ic.style.color = playing ? '#1c1c1e' : 'rgba(255,255,255,0.92)';
      },

      /* Plays the recording in the same frame — no second dialog. The clip
         loads behind the live stream and only swaps in once it can actually
         play, so a recording that never arrives costs nothing on screen. */
      playRecording: function (recId, el) {
        const self = this;
        const scope = el.closest('.cam-detail');
        const ha = self._ha();
        const st = ha && ha.hass && ha.hass.states[recId];
        const url = st && st.attributes && st.attributes.video_url;
        const mount = scope && scope.querySelector('.cam-stream-mount');
        if (!mount) return;
        if (!url) { self.unavailable(scope); return; }

        const v = document.createElement('video');
        v.src = url; v.controls = true; v.playsInline = true; v.preload = 'auto';
        v.muted = self._muted !== false;
        v.setAttribute('playsinline', '');
        v.style.cssText = 'position:absolute;inset:0;width:100%;height:100%;'
          + 'object-fit:contain;background:#000;display:block;z-index:3;'
          + 'opacity:0;transition:opacity 180ms ease;';
        mount.appendChild(v);
        self._probe = v;
        self.paintRec(scope, true);

        let done = false;
        const fail = function () {
          if (done) return; done = true;
          if (self._probeT) { clearTimeout(self._probeT); self._probeT = null; }
          if (self._probe === v) self._probe = null;
          try { v.remove(); } catch (e) {}
          self.paintRec(scope, false);
          self.unavailable(scope);
        };
        const ready = function () {
          if (done) return; done = true;
          if (self._probeT) { clearTimeout(self._probeT); self._probeT = null; }
          self._probe = null;
          self.teardown();
          self._mount = mount;
          self._card = v;
          self._playing = true;
          self.clearBackdrop();
