  /* Temp Stat Card */
  const tempStatCard = {
    type: 'custom:button-card',
    entity: tempId || qualId,
    tap_action: tempId ? { action: 'more-info' } : { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: tempId ? tapStyle : noHoverStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { c: [{ 'justify-self': 'start' }] },
    },
    custom_fields: {
      c: `[[[
        const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
        const tempId = ${_tid};
        const s = tempId ? states[tempId] : null;
        const raw = parseFloat(s?.state);
        const v = isNaN(raw) ? null : raw;
        const tempUnit = s?.attributes?.unit_of_measurement || '°';
        const isFahrenheit = tempUnit === '°F';
        const tempStr = v != null ? (isFahrenheit ? Math.round(v).toString() : (window.hemmaNum || ((x, a, b) => Number(x).toFixed(b ?? a ?? 0)))(v, 1, 1)) : '—';
        const graphTempColor =
          v == null ? 'var(--hemma-badge-temp-comfortable-color, #67F5A0)' :
          isFahrenheit ? (
            v < 76 ? 'var(--hemma-badge-temp-comfortable-color, #67F5A0)' :
            v < 82 ? '#FF9230' : '#FF4245'
          ) : (
            v < 24 ? 'var(--hemma-badge-temp-comfortable-color, #67F5A0)' :
            v < 28 ? '#FF9230' : '#FF4245'
          );
        return '<div>'
          + '<div style="display:flex;align-items:baseline;gap:3px;padding-right:6px;">'
            + '<span style="font-size:26px;font-weight:400;color:var(--hemma-popup-tiles-text-primary);">' + tempStr + '</span>'
            + '<span style="font-size:13px;color:var(--hemma-popup-tiles-text-secondary);">' + tempUnit + '</span>'
          + '</div>'
          + '<div style="display:flex;align-items:center;gap:6px;margin-top:7px;">'
            + '<span style="width:8px;height:8px;background:' + graphTempColor + ';border-radius:50%;display:inline-block;flex-shrink:0;"></span>'
            + '<span style="font-size:14px;color:var(--hemma-popup-tiles-text-secondary);">' + T('climate.temp_short', 'Temp') + '</span>'
          + '</div>'
        + '</div>';
      ]]]`,
    },
  };

  /* Humid Stat Card */
  const humidStatCard = {
    type: 'custom:button-card',
    entity: humidId || qualId,
    tap_action: humidId ? { action: 'more-info' } : { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: humidId ? tapStyle : noHoverStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { c: [{ 'justify-self': 'start' }] },
    },
    custom_fields: {
      c: `[[[
        const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
        const humidId = ${_hid};
        const s = humidId ? states[humidId] : null;
        const raw = parseFloat(s?.state);
        const v = isNaN(raw) ? null : raw;
        const humidStr = v != null ? v.toFixed(0) : '—';
        const humidColor =
          v == null        ? 'rgba(255,255,255,0.7)' :
          v < 20 || v > 75 ? 'var(--hemma-popup-red-color, #ff4245)'    :
          v < 30 || v > 65 ? 'var(--hemma-popup-orange-color, #ff9230)' :
          v < 35 || v > 60 ? 'var(--hemma-popup-yellow-color, #ffd600)' :
          'var(--hemma-badge-climate-color, #C7CED6)';
        return '<div>'
          + '<div style="display:flex;align-items:baseline;gap:3px;padding-left:6px;">'
            + '<span style="font-size:26px;font-weight:400;color:var(--hemma-popup-tiles-text-primary);">' + humidStr + '</span>'
            + '<span style="font-size:13px;color:var(--hemma-popup-tiles-text-secondary);">%</span>'
          + '</div>'
          + '<div style="display:flex;align-items:center;gap:6px;margin-top:7px;margin-left:6px;">'
            + '<span style="width:8px;height:8px;background:' + humidColor + ';border-radius:50%;display:inline-block;flex-shrink:0;transition:background .4s ease;"></span>'
            + '<span style="font-size:14px;color:var(--hemma-popup-tiles-text-secondary);">' + T('humidity.title', 'Humidity') + '</span>'
          + '</div>'
        + '</div>';
      ]]]`,
    },
  };

  /* Stats Row */
  const statsRowCard = {
    type: 'custom:button-card',
    entity: tempId || qualId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: wrapperStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [
        { display: 'flex' }, { 'flex-direction': 'row' }, { 'align-items': 'flex-start' },
        { 'justify-content': 'flex-start' }, { gap: '0' },
      ],
      custom_fields: {
        temp_s:  [{ flex: '0 0 auto' }, { order: '1' }],
        div:     [{ flex: '0 0 auto' }, { 'align-self': 'stretch' }, { order: '2' }],
        humid_s: [{ flex: '0 0 auto' }, { order: '3' }],
      },
    },
    custom_fields: {
      temp_s:  { card: tempStatCard },
      div:     '<div style="width:2px;height:100%;background:rgba(255,255,255,0.09);margin:0 12px;"></div>',
      humid_s: { card: humidStatCard },
    },
  };

  /* Header Card */
  const headerCard = {
    type: 'custom:button-card',
    entity: qualId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '28px 28px 44px 28px' },
      ],
      grid: [
        { 'grid-template-areas': '"title right" "stats right"' },
        { 'grid-template-columns': '1fr auto' },
        { 'align-items': 'flex-start' },
        { gap: '16px 28px' },
      ],
      custom_fields: {
        title: [{ 'justify-self': 'start' }, { 'text-align': 'left' }],
        stats: [{ 'justify-self': 'start' }, { 'text-align': 'left' }],
        right: [{ 'justify-self': 'end' }, { 'align-self': 'flex-start' }],
      },
    },
    custom_fields: {
      title: `[[[
        const qualId = ${_qid};
        const sensors = ${_sns};
        const roomName = ${_room};
        ${_safe}
        ${_thresh}
        ${_scoreBlock}
        return '<div style="font-family:var(--primary-font-family,system-ui);color:var(--hemma-popup-tiles-text-primary);text-align:left;">'
          + '<div style="font-size:22px;font-weight:400;letter-spacing:-.5px;margin-top:20px;margin-bottom:16px;line-height:1.4;overflow:visible;">' + advice + '</div>'
        + '</div>';
      ]]]`,
      stats: { card: statsRowCard },
      right: { card: rightColCard },
    },
  };

  /* Graph Card */
  const humidV = safeNum(humidId);
  const humidGraphColor =
    humidV == null ? '#00c3d0' :
    (humidV < 20 || humidV > 75) ? '#FF4245' :
    (humidV < 30 || humidV > 65) ? '#FF9230' :
    (humidV < 35 || humidV > 60) ? '#FFD600' :
    '#00c3d0';

  const climateYAxis = [];
  const climateSeries = [];
  if (tempId) {
    climateYAxis.push({ id: 'temp', align_to: 5, show: true, apex_config: { stepSize: 5, decimalsInFloat: 0, floating: true, labels: { offsetX: 4, offsetY: -8, align: 'left', style: { colors: 'rgba(255,255,255,0.42)', fontSize: '11px', fontFamily: 'var(--primary-font-family, system-ui)' } } } });
    climateSeries.push({
      entity: tempId,
      name: T('climate.temp_short', 'Temp'),
      color: graphTempColor,
      type: 'area',
      curve: 'smooth',
      stroke_width: 2.5,
      float_precision: 1,
      extend_to: 'now',
      yaxis_id: 'temp',
      group_by: { func: 'avg', duration: '1h', fill: 'last' },
    });
  }
  if (humidId) {
    climateYAxis.push({ id: 'humid', show: false });
    climateSeries.push({
      entity: humidId,
      name: T('humidity.title', 'Humidity'),
      color: humidGraphColor,
      type: 'area',
      curve: 'smooth',
      stroke_width: 2.5,
      float_precision: 0,
      extend_to: 'now',
      yaxis_id: 'humid',
      group_by: { func: 'avg', duration: '1h', fill: 'last' },
    });
  }

  /* Bottom-of-chart time labels. Follows the same clock as the
     tooltip - _use12hr reads Home Assistant's own time_format from the
     user profile and falls back to the browser locale, so America gets
     1:20 PM without anything to configure. Uppercase TT here and
     lowercase tt in the tooltip, because the axis is set small and
     lowercase am/pm reads as noise at 11px. */
  const axisTimeFormat = _use12hr ? 'h:mm TT' : 'HH:mm';
  const graphCard = {
    type: 'custom:apexcharts-card',
    graph_span: '6h',
    header: { show: false },
    yaxis: climateYAxis.length ? climateYAxis : [{ min: 0, max: 100, show: true, apex_config: { tickAmount: 2, floating: true, labels: { offsetX: 4, offsetY: -8, align: 'left', style: { colors: 'rgba(255,255,255,0.42)', fontSize: '11px', fontFamily: 'var(--primary-font-family, system-ui)' } } } }],
    series: climateSeries,
    apex_config: {
      noData: { text: '' },
      chart: {
        events: { mounted: chartEnter, updated: chartEnter },
        height: 104,
        background: 'transparent',
        toolbar: { show: false },
        zoom: { enabled: false },
        animations: { enabled: true, speed: 300, animateGradually: { enabled: false }, dynamicAnimation: { speed: 300 } },
      },
      theme: { mode: 'dark' },
      stroke: { curve: 'smooth', width: 2.5, lineCap: 'round' },
      grid: {
        show: true,
        borderColor: 'rgba(255,255,255,0.10)',
        strokeDashArray: 0,
        xaxis: { lines: { show: false } },
        yaxis: { lines: { show: true } },
        padding: { left: 0, right: 0, top: -6, bottom: -4 },
      },
      xaxis: {
        labels: {
          show: true, rotate: 0, hideOverlappingLabels: true,
          datetimeUTC: false, format: axisTimeFormat,
          style: { colors: 'rgba(255,255,255,0.42)', fontSize: '11px',
                   fontFamily: 'var(--primary-font-family, system-ui)' },
        },
        axisBorder: { show: false },
        axisTicks: { show: false },
        tooltip: { enabled: false },
      },
      dataLabels: { enabled: false },
      legend: { show: false },
      tooltip: {
        enabled: true,
        shared: true,
        intersect: false,
        theme: 'dark',
        x: { show: true, format: tooltipTimeFormat },
        fixed: { enabled: false },
      },
      fill: {
        type: 'gradient',
        gradient: { type: 'vertical', shadeIntensity: 0, opacityFrom: 0.16, opacityTo: 0.0, stops: [0, 100] },
      },
      markers: { size: 0, hover: { size: 5 } },
    },
    card_mod: { style: graphStyle },
  };

  /* Sensor Tile Helpers */
  const cleanSensorName = (eid) => {
    const fn = states[eid]?.attributes?.friendly_name || eid.split('.').pop() || eid;
    const pName = (variables.room_name || '').trim();
    let name = fn;
    if (pName) {
      const esc = pName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      name = name.replace(new RegExp('^' + esc + '\\s*', 'i'), '');
    }
    return name.replace(/_/g, ' ').trim().replace(/\b\w/g, c => c.toUpperCase());
  };

  const makeSensorCard = (eid) => {
    const name = cleanSensorName(eid);
    const info = sensorThresh(eid);

    return {
      type: 'custom:button-card',
      entity: eid,
      tap_action: { action: 'more-info' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: tileTapStyle },
      styles: {
        card: [
          { background: 'rgba(255,255,255,0.045)' }, { border: 'none' }, { borderRadius: '24px' },
          { boxShadow: 'none' }, { backdropFilter: 'none' }, { WebkitBackdropFilter: 'none' },
          { padding: '18px 18px 16px 18px' },
        ],
        grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
        custom_fields: { c: [{ 'justify-self': 'stretch' }, { overflow: 'visible' }] },
      },
      custom_fields: {
        c: `[[[
          const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
          const s = states['${eid}'];
          const raw = parseFloat(s?.state);
          const v = (s?.state === 'unavailable' || s?.state === 'unknown' || isNaN(raw)) ? null : raw;
          const name = ${JSON.stringify(name)};
          const good     = ${info.good};
          const moderate = ${info.moderate};
          const high     = ${info.high};
          const unit     = ${JSON.stringify(info.unit)};

          let label, color;
          if (v == null || good == null) {
            label = v == null ? '—' : T('climate.value', 'Value');
            color = 'rgba(255,255,255,0.4)';
          } else if (v <= good)     { label=T('air_quality.good', 'Good');     color='var(--hemma-badge-air-quality-good-color)'; }
          else if (v <= moderate)   { label=T('air_quality.moderate', 'Moderate'); color='var(--hemma-badge-air-quality-moderate-color)'; }
          else if (v <= high)       { label=T('air_quality.poor', 'Poor');     color='var(--hemma-badge-air-quality-poor-color)'; }
          else                      { label=T('air_quality.bad', 'Bad');      color='var(--hemma-badge-air-quality-bad-color)'; }

          let pct = 0;
          if (v != null && good != null) {
            if (v <= good)     pct = (v / good) * 50;
            else if (v <= moderate) pct = 50 + ((v - good)     / (moderate - good))     * 25;
            else if (v <= high)     pct = 75 + ((v - moderate) / (high - moderate))     * 15;
            else                    pct = Math.min(100, 90 + ((v - high) / Math.max(high, 1)) * 10);
          }

          const gradient = color;

          const valStr = v != null ? (window.hemmaNum || ((x, a, b) => Number(x).toFixed(b ?? a ?? 0)))(v, 0, 2) : '—';

          return '<div style="margin-top:1px;min-width:0;overflow:hidden;">'
            + '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;gap:8px;">'
              + '<span style="font-size:13px;color:var(--hemma-popup-tiles-text-primary);font-weight:600;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;letter-spacing:.01em;">' + name + '</span>'
              + '<span style="font-size:13px;color:' + color + ';white-space:nowrap;font-weight:600;letter-spacing:.01em;flex-shrink:0;">' + label + '</span>'
            + '</div>'
            + '<div style="display:flex;align-items:baseline;gap:3px;">'
              + '<span style="font-size:20px;font-weight:400;color:var(--hemma-popup-tiles-text-primary);line-height:1;white-space:nowrap;">' + valStr + '</span>'
              + '<span style="font-size:12px;color:var(--hemma-popup-tiles-text-muted);white-space:nowrap;">' + unit + '</span>'
            + '</div>'
            + '<div style="position:relative;height:8px;width:100%;background:var(--hemma-popup-progress-track, rgba(255,255,255,0.09));border-radius:999px;overflow:hidden;margin-top:10px;">'
              + '<div style="position:absolute;inset:0 auto 0 0;width:' + pct.toFixed(1) + '%;border-radius:999px;background:' + gradient + ';transition:width .35s ease;"></div>'
            + '</div>'
          + '</div>';
        ]]]`,
      },
    };
  };

  /* Sensor Tiles Grid */
  const cnt    = sensors.length;
  const cols   = 2;
  const sKeys  = sensors.map((_, i) => 's' + i);
  const gcd    = (a, b) => b === 0 ? a : gcd(b, a % b);
  const rem    = cnt % cols;
  let tileAreas, tileCols;
  if (rem === 0) {
    tileCols = 'repeat(' + cols + ', 1fr)';
    const rows = [];
    for (let i = 0; i < cnt; i += cols) rows.push('"' + sKeys.slice(i, i + cols).join(' ') + '"');
    tileAreas = rows.join(' ');
  } else {
    const lcm      = cols * rem / gcd(cols, rem);
    const fullSpan = lcm / cols;
    const lastSpan = lcm / rem;
    tileCols       = 'repeat(' + lcm + ', 1fr)';
    const rows     = [];
    const fullRows = Math.floor(cnt / cols);
    for (let r = 0; r < fullRows; r++) {
      const row = sKeys.slice(r * cols, (r + 1) * cols).map(k => Array(fullSpan).fill(k).join(' ')).join(' ');
      rows.push('"' + row + '"');
    }
    const lastRow = sKeys.slice(fullRows * cols).map(k => Array(lastSpan).fill(k).join(' ')).join(' ');
    rows.push('"' + lastRow + '"');
    tileAreas = rows.join(' ');
  }

  const tileCustomFields = {};
  const tileFieldStyles  = {};
  sensors.forEach((eid, i) => {
    tileCustomFields['s' + i] = { card: makeSensorCard(eid) };
    tileFieldStyles['s' + i]  = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
  });

  const tilesCard = cnt === 0 ? null : {
    type: 'custom:button-card',
    entity: qualId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '0px 28px 20px 28px' },
      ],
      grid: [
        { 'grid-template-areas': tileAreas },
        { 'grid-template-columns': tileCols },
        { gap: '8px' },
        { 'align-items': 'start' },
      ],
      custom_fields: tileFieldStyles,
    },
    custom_fields: tileCustomFields,
  };

  /* Shared popup anatomy: hero, chart, grouped rows. The four tiles
     become readings, carrying range on the number itself - a "Good"
     repeated down the column is noise. */
  const UI = window._hemmaUI;
  if (UI) {
    /* _scoreBlock is a source string injected into nested cards, so its
       score/label/advice never exist out here. Same rules, evaluated in
       this scope. */
    const _aq = (qualId ? states[qualId]?.state : '' || '').toLowerCase() || '';
    let scoreLabel = L('state.default.unknown', 'Unknown'), advice = T('air_quality.unavailable', 'Air quality unavailable'), score = 3;
    switch (_aq) {
      case 'excellent': scoreLabel=T('air_quality.excellent', 'Excellent'); advice=T('air_quality.is_great', 'Air quality is great');  score=5; break;
      case 'good':      scoreLabel=T('air_quality.good', 'Good');      advice=T('air_quality.is_good', 'Air quality is good');    score=4; break;
      case 'moderate':  scoreLabel=T('air_quality.moderate', 'Moderate');  advice=T('air_quality.is_moderate', 'Air quality is moderate'); score=3; break;
      case 'fair':      scoreLabel=T('air_quality.fair', 'Fair');      advice=T('air_quality.is_moderate', 'Air quality is moderate'); score=3; break;
      case 'poor':      scoreLabel=T('air_quality.poor', 'Poor');      advice=T('air_quality.consider_ventilating', 'Consider ventilating');   score=2; break;
      case 'bad': case 'very bad': case 'very poor':
        scoreLabel=T('air_quality.bad', 'Bad'); advice=T('air_quality.ventilate_now', 'Ventilate now'); score=1; break;
    }
    const _active = sensors.filter(eid => safeNum(eid) != null);
    if (_active.length) {
      const _levels = _active.map(eid => {
        const v = safeNum(eid), t = sensorThresh(eid);
        if (t.good == null) return 0;
        if (v <= t.good) return 0;
        if (v <= t.moderate) return 1;
        if (v <= t.high) return 2;
        return 3;
      });
      switch (Math.max(..._levels)) {
        case 0: scoreLabel=T('air_quality.excellent', 'Excellent'); advice=T('air_quality.is_great', 'Air quality is great');  score=5; break;
        case 1: scoreLabel=T('air_quality.moderate', 'Moderate');  advice=T('air_quality.is_moderate', 'Air quality is moderate'); score=3; break;
        case 2: scoreLabel=T('air_quality.poor', 'Poor');      advice=T('air_quality.consider_ventilating', 'Consider ventilating');   score=2; break;
        default: scoreLabel=T('air_quality.bad', 'Bad');      advice=T('air_quality.ventilate_now', 'Ventilate now');          score=1; break;
      }
      _active.forEach(eid => {
        const id = eid.toLowerCase(), v = safeNum(eid), t = sensorThresh(eid);
        if (v == null || t.good == null || v <= t.good) return;
        if (id.includes('pm25') || id.includes('pm2_5')) advice = T('air_quality.particles_elevated', 'Particles elevated');
        if (id.includes('voc')) advice = T('air_quality.vocs', 'VOCs detected – ventilate');
        if (id.includes('no2') || id.includes('nitrogen_dioxide')) advice = T('air_quality.no2', 'NO₂ detected – ventilate');
        if (id.includes('co2') || id.includes('carbon')) {
          advice = v > t.high ? T('air_quality.co2_high', 'CO₂ high – open windows') : T('air_quality.co2_elevated', 'CO₂ elevated – ventilate');
        }
      });
    }

    const areas = [], fields = {}, fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
    };

    const heroTone = score >= 4 ? 'good' : score === 3 ? null : score === 2 ? 'warn' : 'bad';
    const t = safeNum(tempId);
    const h = safeNum(humidId);
    const tUnit = states[tempId]?.attributes?.unit_of_measurement || '\u00b0';
    const bits = [];
    if (t != null) bits.push(Math.round(t) + tUnit);
    if (h != null) bits.push(T('climate.pct_humidity', '{n}% humidity', { n: Math.round(h) }));

    const metricAreas = [], metricFields = {}, metricStyle = {};
    const addMetric = (n2, html) => {
      metricAreas.push('"' + n2 + '"');
      metricFields[n2] = html;
      metricStyle[n2] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
    };

    /* "Excellent" already says it - "Air quality is great" underneath is
       the same sentence twice, and the room name is context you had from
       the card you tapped. The bar carries the name now. */
    addMetric('head', UI.hero({
      compact: true,
      label: T('air_quality.label', 'Air quality'),
      value: scoreLabel,
    }));

    /* The chart goes under the number it explains, not at the foot of
       the sheet. Health, Battery and Stocks all do this: headline,
       chart, then the lists. It was last only because that is where the
       pre-redesign layout left it. As a field inside the content card
       rather than a sibling in the stack, so it can sit between the
       hero and the first group - and the side gutter comes from the
       card, so the chart drops its own. */
    addMetric('chart', { card: graphCard });

    const legendSeries = [];
    if (t != null) legendSeries.push({
      color: graphTempColor, value: Math.round(t) + tUnit, label: T('temp.title', 'Temperature') });
    if (h != null) legendSeries.push({
      color: humidGraphColor, value: Math.round(h) + '%', label: T('humidity.title', 'Humidity') });
    if (legendSeries.length) {
      addMetric('legend', UI.legend(legendSeries));
    }

    const sensorGlyph = (eid) => {
      const id = (eid || '').toLowerCase();
      const dc = (states[eid]?.attributes?.device_class || '').toLowerCase();
      if (id.includes('co2') || id.includes('carbon') || dc === 'carbon_dioxide') {
        return { icon: 'co2-fill', tone: 'var(--hemma-color-teal, #00C3D0)' };
      }
      if (id.includes('pm25') || id.includes('pm2_5') || id.includes('pm10')
          || dc === 'pm25' || dc === 'pm10') {
        return { icon: 'allergens-fill', tone: 'var(--hemma-color-amber, #ffb254)' };
      }
      if (id.includes('voc') || id.includes('volatile_organic')
          || dc.includes('volatile_organic')) {
        return { icon: 'mdi:air-filter', tone: 'var(--hemma-color-purple, #9333ea)' };
      }
      return { icon: 'mdi:air-filter', tone: 'var(--hemma-color-blue, #0A84FF)' };
    };

    const readings = sensors.map((eid) => {
      const v = safeNum(eid);
      const th = sensorThresh(eid);
      let tone = null;
      if (v != null && th && th.good != null) {
        tone = v <= th.good ? 'good' : v <= th.moderate ? null : v <= th.high ? 'warn' : 'bad';
      }
      const unit = states[eid]?.attributes?.unit_of_measurement || th?.unit || '';
      const glyph = sensorGlyph(eid);
      return {
        entity: eid,
        icon: glyph.icon,
        iconTone: glyph.tone,
        label: cleanSensorName(eid),
        value: v == null ? '\u2014' : (window.hemmaNum || ((x, a, b) => Number(x).toFixed(b ?? a ?? 0)))(v, 0, 1) + (unit ? ' ' + unit : ''),
        valueTone: tone,
      };
    });
    if (readings.length) add('read', UI.group(readings, null));

    /* One object: the number, its status and the curve it describes, on
       a single plate. They were two stacked blocks - a floating stat
       with a graph under it - which is the part that never read as
       Apple. Health, Battery and Stocks all bind the headline to the
       chart. The plate moved here from the chart card, which is
       transparent inside it now. */
    const metricCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      extra_styles: '@keyframes hemma-plate-hold { from, to { opacity: 0; } }'
        + ' @keyframes hemma-plate-in {'
        + ' from { opacity: 0; transform: perspective(900px) translateZ(-70px); }'
        + ' to { opacity: 1; transform: perspective(900px) translateZ(0); } }'
        + ' ha-card { animation: var(--hemma-popup-plate-enter, none);'
        + ' animation-delay: var(--hemma-popup-plate-delay, 0ms); }'
        + ' apexcharts-card:not([data-hemma-ready]) { opacity: 0; }'
        + ' apexcharts-card { transition: opacity'
        + ' var(--hemma-popup-chart-enter, 140ms)'
        + ' var(--hemma-popup-chart-enter-ease, ease-out); }'
        + ' @media (prefers-reduced-motion: reduce) {'
        + ' apexcharts-card { transition: none; } }',
      card_mod: { style: [
        ':host { --ha-card-box-shadow: none !important;'
          + ' --button-card-box-shadow: none !important;'
          + ' --button-card-box-shadow-hover: var(--hemma-popup-plate-shadow, none) !important;'
          + ' --hemma-card-hover-shadow: var(--hemma-popup-plate-shadow, none) !important;'
          + ' --hemma-card-hover-filter: none !important;'
          + ' --hemma-hover-filter: none !important;'
          + ' --ha-card-backdrop-filter: none !important; }',
        'ha-card { background: var(--hemma-popup-chart-fill, rgba(0,0,0,0.26)) !important;'
          + ' border: none !important;'
          + ' border-radius: var(--hemma-popup-row-radius, 20px) !important;'
          + ' box-shadow: var(--hemma-popup-plate-shadow, none) !important;'
          + ' backdrop-filter: var(--hemma-popup-plate-backdrop, none) !important;'
          + ' -webkit-backdrop-filter: var(--hemma-popup-plate-backdrop, none) !important;'
          + ' overflow: visible !important;'
          + ' will-change: auto !important; cursor: default !important; }',
        '#container > * { --hemma-card-hover-shadow: none !important;'
          + ' --button-card-box-shadow-hover: none !important; }',
        'ha-card::before, ha-card::after { display: none !important; }',
        'ha-card:hover { box-shadow: var(--hemma-popup-plate-shadow, none) !important;'
          + ' background: var(--hemma-popup-chart-fill, rgba(0,0,0,0.26)) !important;'
          + ' border-color: transparent !important; filter: none !important; }',
        'ha-ripple { display: none !important; }',
      ].join('\n') },
      styles: {
        card: [
          { background: 'var(--hemma-popup-chart-fill, rgba(0,0,0,0.26))' },
          { 'border-radius': 'var(--hemma-popup-row-radius, 20px)' },
          { 'backdrop-filter': 'var(--hemma-popup-plate-backdrop, none)' },
          { '-webkit-backdrop-filter': 'var(--hemma-popup-plate-backdrop, none)' },
          { 'box-shadow': 'var(--hemma-popup-plate-shadow, none)' },
          { border: 'none' }, { padding: '30px 28px 26px 28px' },
        ],
        grid: [{ 'grid-template-areas': metricAreas.join(' ') },
               { 'grid-template-columns': 'minmax(0, 1fr)' },
               { 'row-gap': '0' }],
        custom_fields: metricStyle,
      },
      custom_fields: metricFields,
    };
    areas.unshift('"metric"');
    fields.metric = { card: metricCard };
    fstyle.metric = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];

    areas.forEach((a, i) => {
      const key = a.replace(/"/g, '');
      if (fstyle[key]) {
        fstyle[key].push({ '--hemma-popup-plate-delay': (i * 55) + 'ms' });
      }
    });


    const uiCard = {
      type: 'custom:button-card',
      card_mod: { style: contentCardStyle
        + '\nha-card { will-change: auto !important; }' },
      entity: qualId,
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: '6px 26px 22px 26px' },
        ],
        grid: [
          { 'grid-template-areas': areas.join(' ') },
          { 'grid-template-columns': 'minmax(0, 1fr)' },
          { 'row-gap': '28px' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
    };

    return { type: 'vertical-stack', cards: [uiCard] };
  }

  const cards = [headerCard, graphCard];
  if (tilesCard) cards.push(tilesCard);
  return { type: 'vertical-stack', cards };
]]]

popup_styles.styles:
/* The pane stays - these are control sheets. Only the close control
   keeps what it gained: a surface of its own, and room above it so
   the fill is not against the top edge of the sheet. */
.header { padding-top: var(--hemma-popup-header-gap, 10px); }
/* Equal inset on both axes: the bar's own padding plus the
   close control's 2px optical nudge has to come to the same
   number as the padding above it, or the circle sits further
   from the left edge than it does from the top. */
--hemma-popup-header-gap: 14px;
  --hemma-popup-gutter-wide: 20px;
  --hemma-popup-row-radius: 30px;
  /* The inactive presets read brighter than the tiles under them. */
  --hemma-popup-seg-fill: rgba(255, 255, 255, 0.10);
  --hemma-popup-seg-fill-hover: rgba(255, 255, 255, 0.16);
/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--hemma-popup-chrome-enter:
  hemma-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
.header-close {
  border-radius: 50%;
  background: var(--hemma-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--hemma-popup-plate-backdrop, blur(24px) saturate(180%));
  -webkit-backdrop-filter: var(--hemma-popup-plate-backdrop, blur(24px) saturate(180%));
  box-shadow: var(--hemma-popup-plate-shadow, none);
}

hemma_popup.content:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
  const L = (k, en) => { const v = hass?.localize?.(k); return (v && v !== k) ? v : en; };
  /* Variables */
  const groupId  = variables.cover_entity || entity?.entity_id || null;
  const coverIds = Array.isArray(variables.covers) && variables.covers.length > 0
                 ? variables.covers
                 : (groupId ? [groupId] : []);
  const HZ_SYS   = variables.smart_automation_entity || null;       // shade-automation switch
  const HZ_HEUTE = variables.smart_automation_today_entity || null; // today's automation override
  const _hzSys   = JSON.stringify(HZ_SYS);
  const _gid      = JSON.stringify(groupId);
  const _coverIds = JSON.stringify(coverIds);
  const _countSnip = `
    const coverIds = ${_coverIds};
    const openIds = coverIds.filter(id => ['open','opening','stopping'].includes(states[id]?.state));
    const oc = openIds.length, tot = coverIds.length;
    const allClosed = oc === 0 && tot > 0;
    const allOpen   = oc === tot && tot > 0;
    const badgeColor = allClosed ? 'var(--hemma-popup-green-color,#30D158)' : '#0A84FF';
  `;

  /* Styles */
  const wrapperStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
