    'ha-card { border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; background: transparent !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; }',
