    custom_fields: {
      title: '<div style="font-family:var(--primary-font-family,system-ui);color:var(--hemma-popup-tiles-text-primary,#ffffff);text-align:left;">'
        + '</div>',
    },
  };

  /* Smart automation toggle */
  let hitzeschutzCard = null;
  if (HZ_SYS) {
    const hzToggle = {
      type: 'custom:button-card',
      entity: HZ_SYS,
      show_name: false, show_state: false, show_icon: false,
      tap_action: { action: 'call-service', service: 'switch.toggle', service_data: { entity_id: HZ_SYS } },
      haptic: 'medium',
      custom_fields: {
        svg: `[[[
          const isOn = states[${_hzSys}]?.state === 'on';
          const KF_ID = 'hemma-toggle-kf-v1';
          if (!document.getElementById(KF_ID)) {
            const kf = document.createElement('style');
            kf.id = KF_ID;
            kf.textContent = [
              '@keyframes hemma-thumb-on-d{from{transform:translateX(0)}to{transform:translateX(18px)}}',
