          const W = mob ? 38 : 44, H = 26, r = mob ? 8 : 9, cx0 = 14;
          const SW = W + 2;
          const travel = mob ? 12 : 18;
          const stateKey = '_hemma_toggle_cover_automation_' + ${_hzSys};
          const shouldAnimate = window[stateKey] !== undefined && window[stateKey] !== isOn;
          window[stateKey] = isOn;
          const anim = isOn ? (mob ? 'hemma-thumb-on-m' : 'hemma-thumb-on-d') : (mob ? 'hemma-thumb-off-m' : 'hemma-thumb-off-d');
          const animStyle = shouldAnimate ? ('animation:' + anim + ' 0.2s ease forwards;') : '';
          const circleCx = (!shouldAnimate && isOn) ? cx0 + travel : cx0;
          const trackFill = 'var(--hemma-popup-orange-color,#ff9230)';
          const offColor  = 'rgba(255,255,255,0.8)';
          if (isOn) {
            return '<svg width="' + SW + '" height="' + H + '" viewBox="0 0 ' + SW + ' ' + H + '" style="display:block;">'
              + '<rect x="2" y="1" width="' + (W-2) + '" height="' + (H-2) + '" rx="' + ((H-2)/2) + '" fill="' + trackFill + '"/>'
              + '<circle cx="' + circleCx + '" cy="' + (H/2) + '" r="' + r + '" fill="rgba(255,255,255,0.92)" style="' + animStyle + '"/>'
              + '</svg>';
          } else {
            return '<svg width="' + SW + '" height="' + H + '" viewBox="0 0 ' + SW + ' ' + H + '" style="display:block;">'
