          { overflow: 'visible !important' }, { '--button-card-ripple-color': 'transparent !important' },
          { 'border-radius': '0 !important' },
        ],
        grid: [{ padding: '0 !important' }, { overflow: 'visible !important' }],
        custom_fields: { svg: [{ 'line-height': '0' }] },
