      extra_styles: [
        ':host { display: block !important; width: 46px !important; height: 26px !important; overflow: visible !important; cursor: pointer; }',
        '@media (max-width: 767px), (max-height: 600px) { :host { width: 40px !important; height: 26px !important; } }',
        'ha-card, #container { overflow: visible !important; background: transparent !important; --ha-card-background: transparent !important; }',
        '@media (hover: hover) { :host { transition: filter 0.2s ease; } :host(:hover) { filter: brightness(1.5) !important; } }',
      ].join('\n'),
    };

    const hzTileInner = {
      type: 'custom:button-card',
      entity: HZ_HEUTE || HZ_SYS,
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
