        },
      },
      custom_fields: {
        head: `[[[
          const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
          const autoName = (states[${_hzSys}]?.attributes?.friendly_name) || T('covers.automation', 'Cover Automation');
          return '<div style="display:flex;align-items:center;gap:8px;flex-wrap:wrap;">'
            + '<span style="font-size:14px;color:var(--hemma-popup-tiles-text-primary,#ffffff);font-weight:500;">' + autoName + '</span>'
          + '</div>';
        ]]]`,
        action: { card: hzToggle },
      },
    };

    hitzeschutzCard = {
      type: 'custom:button-card',
