  /* Curtain SVGs */
  const CURTAIN_OPEN_URI = 'data:image/svg+xml;base64,';
  const CURTAIN_CLOSED_URI = 'data:image/svg+xml;base64,';

  /* Palette matches hemma_popup_light's makeLightCard, teal instead of yellow. */
  const _cc = {
    onBg:    'rgba(255,255,255,0.94)',
    onName:  'rgba(0,0,0,0.85)',
    onLabel: 'rgba(0,0,0,0.50)',
    offBg:   'rgba(255,255,255,0.11)',
    offName: 'rgba(255,255,255,0.90)',
    offLabel:'rgba(255,255,255,0.50)',
  };

  const makeCoverCard = (coverId) => {
    const _cid = JSON.stringify(coverId);
    return {
      type: 'custom:button-card',
      entity: coverId,
      show_icon: false,
      show_entity_picture: true,
      entity_picture: window.hemmaIconUrl('curtain-open'),
      tap_action: { action: 'more-info' },
      hold_action: { action: 'more-info' },
      double_tap_action: { action: 'none' },
      icon_tap_action: { action: 'toggle' },
      show_name: true,
      show_state: false,
      show_label: true,
      label: `[[[
        const e = states[${_cid}];
        const s = e?.state || 'unknown';
        const lbl = s.charAt(0).toUpperCase() + s.slice(1);
        const pos = e?.attributes?.current_position;
        return (pos != null) ? lbl + ' · ' + Math.round(Number(pos)) + '%' : lbl;
      ]]]`,
      extra_styles: ':host{--hemma-card-hover-filter:brightness(1.10);width:100%!important;max-width:none!important;display:block!important;box-sizing:border-box!important;--button-card-ripple-color:transparent!important;--button-card-ripple-hover-color:transparent!important;--ha-ripple-color:transparent!important;--ha-ripple-hover-color:transparent!important;}ha-card{transition:background 0.45s ease,transform var(--hemma-popup-tile-hover-duration,0.2s) ease,filter var(--hemma-popup-tile-hover-duration,0.2s) ease!important;transform:scale(1)!important;}ha-card:hover{transform:scale(var(--hemma-popup-tile-hover-scale,1.01))!important;}ha-card:active{transform:scale(1)!important;}@media (hover:hover){ha-card:hover{filter:var(--hemma-card-hover-filter,brightness(1.06))!important;}ha-card:hover::after{background:var(--lc-hover-tint,rgba(255,255,255,0.06))!important;}}ha-card::before{display:none!important;}ha-card::after{content:""!important;position:absolute!important;inset:0!important;border-radius:inherit!important;background:transparent!important;transition:background var(--hemma-popup-tile-hover-duration,0.2s) ease!important;pointer-events:none!important;}ha-ripple{display:none!important;}div#img-cell{position:relative!important;overflow:hidden!important;transition:transform var(--hemma-popup-tile-hover-duration,0.2s) ease!important;}div#img-cell::before{display:none!important;}div#img-cell::after{content:""!important;display:block!important;position:absolute!important;inset:0!important;margin:auto!important;width:60%!important;height:60%!important;background-color:var(--cc-clr,#ffffff)!important;-webkit-mask-image:var(--cc-mask)!important;-webkit-mask-repeat:no-repeat!important;-webkit-mask-position:center!important;-webkit-mask-size:contain!important;mask-image:var(--cc-mask)!important;mask-repeat:no-repeat!important;mask-position:center!important;mask-size:contain!important;opacity:var(--cc-io,0.9)!important;pointer-events:none!important;transform:translateZ(0)!important;will-change:transform!important;}div#img-cell:hover,div#img-cell:active{transform:scale(1.03)!important;}#img-cell img{opacity:0!important;}',
      styles: {
        card: [
          { background: `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"${_cc.onBg}":"${_cc.offBg}";]]]` },
          { '--cc-nc': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"${_cc.onName}":"${_cc.offName}";]]]` },
          { '--cc-lc': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"${_cc.onLabel}":"${_cc.offLabel}";]]]` },
          { '--cc-io': `[[[ return "1";]]]` },
          { '--cc-clr': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"#ffffff":"var(--hemma-color-teal, #00c3d0)";]]]` },
          { '--cc-mask': `[[[
              const s = (states[${_cid}]?.state||'').toLowerCase();
              const open = ['open','opening'].includes(s);
              return "url('" + (open ? ${JSON.stringify(CURTAIN_OPEN_URI)} : ${JSON.stringify(CURTAIN_CLOSED_URI)}) + "')";
            ]]]` },
          { '--hemma-card-hover-filter': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"none":"brightness(1.10)";]]]` },
          { '--lc-hover-tint': `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"transparent":"rgba(255,255,255,0.06)";]]]` },
          { border: 'none' },
          { 'box-shadow': 'none' },
          { 'border-radius': '26px' },
          { cursor: 'pointer' },
          { padding: '12px 12px' },
          { width: '100%' },
        ],
        grid: [
          { 'grid-template-areas': '"i n" "i l"' },
          { 'grid-template-columns': 'auto 1fr' },
          { 'grid-template-rows': 'auto auto' },
          { 'column-gap': '10px' },
          { 'row-gap': '1px' },
          { 'align-items': 'start' },
        ],
        img_cell: [
          { background: `[[[ const s=(states[${_cid}]?.state||'').toLowerCase(); return ['open','opening'].includes(s)?"var(--hemma-color-teal, #00c3d0)":"rgba(255,255,255,0.10)";]]]` },
          { 'border-radius': '50%' },
          { width: '38px' },
          { height: '38px' },
          { 'min-width': '38px' },
          { display: 'flex' },
          { 'align-items': 'center' },
          { 'justify-content': 'center' },
          { 'align-self': 'center' },
        ],
        entity_picture: [
          { width: '100%' },
          { height: '100%' },
          { 'object-fit': 'contain' },
        ],
        name: [
          { 'font-size': '14px' },
          { 'font-weight': '500' },
          { color: 'var(--cc-nc)' },
          { 'text-align': 'left' },
          { 'justify-self': 'start' },
          { 'align-self': 'end' },
          { 'line-height': '1.2' },
          { overflow: 'hidden' },
          { 'text-overflow': 'ellipsis' },
          { 'white-space': 'nowrap' },
        ],
        label: [
          { 'font-size': '12px' },
          { color: 'var(--cc-lc)' },
          { 'text-align': 'left' },
          { 'justify-self': 'start' },
          { 'align-self': 'start' },
          { 'line-height': '1.2' },
        ],
      },
    };
  };

  /* Dynamic grid */
  const colCount = coverIds.length > 1 ? 2 : 1;
  let tileAreas;
  if (colCount === 1) {
    tileAreas = coverIds.map((_, i) => '"t' + i + '"').join(' ');
  } else {
    const rows = [];
    for (let i = 0; i < coverIds.length; i += 2) {
      if (i + 1 < coverIds.length) {
        rows.push('"t' + i + ' t' + (i + 1) + '"');
      } else {
        rows.push('"t' + i + ' t' + i + '"');
      }
    }
    tileAreas = rows.join(' ');
  }
  const tileColDef = colCount === 1 ? '1fr' : '1fr 1fr';

  const tileCF = {}, tileFS = {};
  coverIds.forEach((id, i) => {
    tileCF['t' + i] = { card: makeCoverCard(id) };
    tileFS['t' + i] = [{ 'justify-self': 'stretch' }, { 'text-align': 'left' }];
  });

  const tilesCard = {
    type: 'custom:button-card',
    entity: groupId,
    tap_action: { action: 'none' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: contentCardStyle },
    styles: {
      card: [
        { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
        { padding: '16px 28px 20px 28px' },
      ],
      grid: [
        { 'grid-template-areas': tileAreas },
        { 'grid-template-columns': tileColDef },
        { gap: '10px' },
        { 'align-items': 'start' },
      ],
      custom_fields: tileFS,
    },
    custom_fields: tileCF,
  };

  /* Shared popup anatomy. Position is the subject, so it is the hero;
     the preset pills become a segmented control; each cover becomes a
     row carrying its own position. */
  const UI = window._hemmaUI;
  if (UI) {
    const posOf = (id) => {
      const p = states[id]?.attributes?.current_position;
      return typeof p === 'number' ? Math.round(p) : null;
    };
    const openStates = ['open', 'opening', 'stopping'];
    const known = coverIds.map(posOf).filter(v => v != null);
    const avg = known.length
      ? Math.round(known.reduce((a, b) => a + b, 0) / known.length)
      : null;
    const openCount = coverIds.filter(id => openStates.includes(states[id]?.state)).length;
    const allClosed = openCount === 0 && coverIds.length > 0;
    const allOpen = openCount === coverIds.length && coverIds.length > 0;

    const areas = [], fields = {}, fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }];
    };

    /* The more-info state header: the word, then how long it has read
       that way, centered over the control. The percentage lives on the
       slider and on each row, so it is not repeated here. A [[[ ]]]
       template, not a string, or the time never ticks. */
    const _cids = JSON.stringify(coverIds);
    add('hero', `[[[
      const L = (k, en) => { const v = hass?.localize?.(k); return (v && v !== k) ? v : en; };
      const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
      const ids = ${_cids};
      const ago = (iso) => {
        if (!iso) return null;
        const ms = Date.now() - new Date(iso).getTime();
        if (isNaN(ms) || ms < 0) return null;
        const m = ms/60000, h = m/60, d = h/24;
        if (m < 1) return T('time.just_now', 'just now');
        if (m < 60) return (Math.floor(m)===1 ? T('time.minute_ago', '{n} minute ago', { n: 1 }) : T('time.minutes_ago', '{n} minutes ago', { n: Math.floor(m) }));
        if (h < 24) return (Math.floor(h)===1 ? T('time.hour_ago', '{n} hour ago', { n: 1 }) : T('time.hours_ago', '{n} hours ago', { n: Math.floor(h) }));
        if (d < 7)  return (Math.floor(d)===1 ? T('time.day_ago', '{n} day ago', { n: 1 }) : T('time.days_ago', '{n} days ago', { n: Math.floor(d) }));
        return T('time.short.weeks', '{n}w ago', { n: Math.floor(d/7) });
      };
      const posOf = (id) => {
        const p = states[id]?.attributes?.current_position;
        return typeof p === 'number' ? Math.round(p) : null;
      };
      const openStates = ['open', 'opening', 'stopping'];
      const known = ids.map(posOf).filter(v => v != null);
      const avg = known.length
        ? Math.round(known.reduce((a, b) => a + b, 0) / known.length)
        : null;
      const tot = ids.length;
      const openCount = ids.filter(id => openStates.includes(states[id]?.state)).length;
      const moving = ids.some(id => ['opening','closing'].includes(states[id]?.state));
      const part = avg != null && avg > 0 && avg < 100;
      const value = moving
        ? (ids.some(id => states[id]?.state === 'opening') ? T('covers.opening', 'Opening…') : T('covers.closing', 'Closing…'))
        : openCount === 0 ? (tot === 1 ? L('component.cover.entity_component._.state.closed', 'Closed') : T('covers.all_closed', 'All closed'))
        : openCount === tot ? (part ? T('covers.partly_open', 'Partly open') : (tot === 1 ? L('component.cover.entity_component._.state.open', 'Open') : T('covers.all_open', 'All open')))
        : T('covers.n_open', '{n} open', { n: openCount });
      const newest = ids.map(id => states[id]?.last_changed).filter(Boolean).sort().pop();
      return window._hemmaUI.hero({
        value: value,
        sub: ago(newest),
        center: true,
      });
    ]]]`);

    /* The height goes to the control: a grab-anywhere vertical track,
       the way Home does blinds. */
    const coverIcon = (() => {
      const id = (coverIds[0] || '').toLowerCase();
      const dc = (states[coverIds[0]]?.attributes?.device_class || '').toLowerCase();
      if (dc === 'blind' || id.includes('blind')) return 'blinds-vertical-open';
      if (dc === 'shade' || id.includes('shade')) return 'roller-shade-open';
      return 'curtain-open';
    })();
    add('slider', UI.slider({
      /* Shorter than the shared control height by the presets row this
         popup has and the lock does not, so both sheets land their
         tiles on the same line. */
      height: 267,
      value: avg == null ? (allClosed ? 0 : 100) : avg,
      invert: true,
      live: { entities: coverIds, attr: 'current_position' },
      icon: coverIcon,
      svc: { domain: 'cover', service: 'set_cover_position',
             target: { entity_id: coverIds }, field: 'position' },
    }));

    const setTo = (pos) => ({
      domain: 'cover', service: 'set_cover_position',
      target: { entity_id: coverIds }, data: { position: pos },
    });
    add('presets', UI.segments([
      { label: T('covers.close', 'Close'), svc: setTo(0),   active: avg === 0 },
      { label: '25%',   svc: setTo(25),  active: avg === 25 },
      { label: '50%',   svc: setTo(50),  active: avg === 50 },
      { label: '75%',   svc: setTo(75),  active: avg === 75 },
      { label: T('covers.open', 'Open'),  svc: setTo(100), active: avg === 100 },
    ]));

    /* Sectioned by device class. A header earns its place by telling
       two things apart, so one type gets one section named for what it
       actually is - never the generic "Cover". */
    /* The taxonomy lives in hemma-core so the tile template resolves the
       same pair. The literal is only a guard for a stale core. */
    const CURTAIN = { key: 'curtain', label: 'Curtains',
                      open: 'curtain-open', closed: 'curtain-closed' };
    const kindOf = (id) => (window.hemmaCoverKind
      ? window.hemmaCoverKind(states[id]?.attributes?.device_class, id)
      : CURTAIN);

    const KIND = {};
    const byKind = {};
    coverIds.forEach((id) => {
      const k = kindOf(id);
      KIND[k.key] = k;
      (byKind[k.key] = byKind[k.key] || []).push(id);
    });
    const kinds = Object.keys(byKind);

    /* No per-row bar. The trailing word IS the state, the way the lock
       rows read - a 4px line under a row that already prints the number
       says the same thing twice, and it is not a control: it would be a
       drag target well under the 44px minimum, fighting the row's own
       tap-to-open. WORDS is shared so the first paint and the live
       repaint cannot drift apart. */
    const WORDS = {
      state: { opening: T('covers.opening', 'Opening…'), closing: T('covers.closing', 'Closing…') },
      attr: 'current_position',
      exact: { '0': L('component.cover.entity_component._.state.closed', 'Closed'), '100': L('component.cover.entity_component._.state.open', 'Open') },
      tpl: T('covers.pct_open', '{n}% open'),
      fallbackState: { open: L('component.cover.entity_component._.state.open', 'Open'), closed: L('component.cover.entity_component._.state.closed', 'Closed'), stopping: T('covers.stopped', 'Stopped') },
    };
    const wordFor = (id) => {
      const st = states[id]?.state;
      if (WORDS.state[st]) return WORDS.state[st];
      const p = posOf(id);
      if (p == null) return WORDS.fallbackState[st] || L('state.default.unknown', 'Unknown');
      return WORDS.exact[String(p)] || WORDS.tpl.replace('{n}', String(p));
    };

    const rowFor = (id, k) => {
      const open = openStates.includes(states[id]?.state);
      return {
        entity: id,
        icon: open ? KIND[k].open : KIND[k].closed,
        label: hass?.entities?.[id]?.name
          || states[id]?.attributes?.friendly_name || id,
        value: wordFor(id),
        liveWords: WORDS,
      };
    };

    /* A heading earns its place by telling two things apart. With one
       kind, or with grouping off, there is nothing to tell apart. */
    const grouped = variables.group_by_type !== false && kinds.length > 1;
    if (grouped) {
      kinds.forEach((k, i) => {
        add('k' + i, UI.group(byKind[k].map(id => rowFor(id, k)), KIND[k].label));
      });
    } else {
      const all = [];
      kinds.forEach((k) => byKind[k].forEach((id) => all.push(rowFor(id, k))));
      if (all.length) add('k0', UI.group(all, null));
    }

    if (HZ_SYS && states[HZ_SYS]) {
      const on = states[HZ_SYS].state === 'on';
      add('auto', UI.group([{
        icon: 'scenes',
        label: hass?.entities?.[HZ_SYS]?.name
          || states[HZ_SYS].attributes?.friendly_name || T('covers.shade_automation', 'Shade automation'),
        value: on ? L('component.automation.entity_component._.state.on', 'On') : L('component.automation.entity_component._.state.off', 'Off'),
        valueTone: on ? 'good' : null,
        svc: { domain: 'homeassistant', service: on ? 'turn_off' : 'turn_on',
               target: { entity_id: HZ_SYS } },
      }], T('common.automation', 'Automation')));
    }

    const uiCard = {
      type: 'custom:button-card',
      card_mod: { style: contentCardStyle
        + '\n:host { --ha-card-backdrop-filter: none !important; --ha-card-background: transparent !important; --card-background-color: transparent !important; --ha-card-box-shadow: none !important; --ha-card-border-width: 0px !important; }'
        + '\nha-card::before, ha-card::after, #card::before, #card::after, #container::before, #container::after { display: none !important; }'
        + '\nha-card { will-change: auto !important; }'
        + '\n#container { background: transparent !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; }' },
      entity: groupId || undefined,
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: '6px 26px 22px 26px' },
        ],
        grid: [
          { 'grid-template-areas': areas.join(' ') },
          { 'grid-template-columns': '1fr' },
          { 'row-gap': '28px' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
    };
    return { type: 'vertical-stack', cards: [uiCard] };
  }

  const stackCards = [headerCard, controlsCard, tilesCard];
  if (hitzeschutzCard) stackCards.splice(1, 0, hitzeschutzCard);
  return { type: 'vertical-stack', cards: stackCards };
]]]

popup_styles.styles:
--hemma-popup-plate-enter:
  hemma-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --hemma-popup-plate-enter: none;
}

/* No pane. The header sits on the room and each section stands in
   front of it as its own card, the way iOS groups settings on a
   background rather than inside one box. The room is still blurred,
   by the scrim, which is a sibling of the surface and so survives
   the pane going transparent. */
--hemma-popup-tint: transparent;
/* The totals read as one line when the label is a hair from the
   number - "This month" was touching "36 kWh". */
--hemma-popup-value-gap-wide: 28px;
--hemma-popup-gutter-wide: 34px;
--hemma-popup-gutter-phone: 22px;
/* The close control's box starts at the bar's padding and the
   content starts at its own gutter; they line up only when the
   two are the same number. */
/* The popups have no pane, so headings and captions sit straight
   on the room. 6px is enough behind a panel and not enough behind
   bare text - this is scoped to the pane-less popups rather than
   raised globally, so the cover and lock sheets keep the lighter
   scrim they are built against. */
--hemma-popup-scrim-backdrop: blur(22px) saturate(1.5);
--hemma-popup-backdrop: none;
--hemma-popup-shadow: none;
/* The grain is two pseudo-elements on .glass, blending overlay and
   screen. They keep painting after the tint goes transparent, and a
   screen blend over noise is exactly the pale panel that survived
   the first attempt. */
/* Removed, not hidden: at opacity 0 the blend layer is invisible
   and costs the same as a visible one. */
--hemma-popup-grain-content: none;
--hemma-popup-grain: 0;
--hemma-popup-grain-dark: 0;
--hemma-popup-scrim: rgba(0, 0, 0, 0.26);

/* Held. A chart has to fetch its history, so revealing the widgets
   first only meant watching the graph arrive late. hemma-popup
   stamps data-hemma-charts-ready once every chart in the popup has
   drawn, or gives up on one that never will, and the entry below
   swaps the hold for the entrance. Read by each widget for itself,
   never by a wrapper. */
--hemma-popup-plate-enter: hemma-plate-hold 10s linear both;

/* Wide enough for the aside; .surface caps itself at
   calc(100vw - 16px), so a narrow screen shrinks instead. */
--popup-min-width: 900px;
--popup-max-width: 920px;
--hemma-popup-aside-w: 300px;

--hemma-popup-hero-label-size: 15px;
--hemma-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--hemma-card-hover-filter: none;
--hemma-hover-filter: none;
--hemma-card-hover-shadow: none;

--hemma-popup-row-pad-x: 26px;
--hemma-popup-row-pad-y: 15px;
--hemma-popup-plate-backdrop: blur(24px) saturate(180%);
--hemma-popup-chart-fill: rgba(10, 12, 16, 0.68);
--hemma-popup-row-fill: rgba(12, 14, 19, 0.62);
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--hemma-popup-plate-shadow:
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28);

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */
/* The sheet's drag handle keeps working; only the little bar
   that advertises it goes. Nothing else on these popups is a hint. */
--hemma-popup-grabber: transparent;

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--hemma-popup-chrome-enter:
  hemma-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--hemma-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--hemma-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--hemma-popup-plate-backdrop, none);
  box-shadow: var(--hemma-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

hemma_popup.content:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
  const powerId     = variables.entity_power || entity?.entity_id;
  const todayId     = variables.entity_usage_today;
  const monthId     = variables.entity_usage_month;
  const costTodayId = variables.entity_cost_today;
  const costMonthId = variables.entity_cost_month;
  const roomName    = variables.room_name || T('filter.energy', 'Energy');

  const safeNum = (id) => {
    if (!id) return null;
    const s = states[id] && states[id].state;
    if (!s || s === 'unknown' || s === 'unavailable') return null;
    const n = parseFloat(s);
    return isNaN(n) ? null : n;
  };

  const costCurrency = (costTodayId && states[costTodayId]?.attributes?.unit_of_measurement)
    || (costMonthId  && states[costMonthId]?.attributes?.unit_of_measurement)
    || '';

  const power = safeNum(powerId);

  window._hc = window._hc || {};
  const _ck = 'hemma_energy_v2_' + (powerId || 'x');
  const _memoSub = (subKey, dep, factory) => {
    const key = _ck + '_' + subKey;
    if (window._hc[key]?.h === dep) return window._hc[key].r;
    const r = factory();
    window._hc[key] = { h: dep, r };
    return r;
  };

  const tNormal  = Number(variables.normal_threshold  ?? 200);
  const tHeavy   = Number(variables.heavy_threshold   ?? 1000);
  const tExtreme = Number(variables.extreme_threshold ?? 3000);

  // Usage tier — drives the graph line and the memo keys below
  const statusLabel = power >= tExtreme ? T('energy.extreme', 'Extreme') : power >= tHeavy ? T('energy.heavy', 'Heavy') : power >= tNormal ? T('energy.normal', 'Normal') : T('energy.idle', 'Idle');
  // apexcharts can't resolve CSS vars, so these mirror the Apple palette literally
  /* ApexCharts writes the color into an SVG attribute, which does not
     accept var(), so the token is resolved to a literal here. The line
     no longer changes hue with load - the tier is the chip's job, and a
     series in the status palette reads as a verdict. */
  const _cssVar = (name, fallback) => {
    try {
      const v = getComputedStyle(document.documentElement).getPropertyValue(name).trim();
      return v || fallback;
    } catch (e) { return fallback; }
  };
  const SERIES_1    = _cssVar('--hemma-series-1', '#64D2FF');
  const graphColor  = SERIES_1;

  // Safe JSON literals for inner templates
  const _pid  = JSON.stringify(powerId     || '');
  const _tid  = JSON.stringify(todayId     || '');
  const _mid  = JSON.stringify(monthId     || '');
  const _ctid = JSON.stringify(costTodayId || '');
  const _cmid = JSON.stringify(costMonthId || '');
  const _cur  = JSON.stringify(costCurrency);

  // Shared helper snippets
  const _safe = "const safeNum=(id)=>{if(!id)return null;const s=states[id]&&states[id].state;if(!s||s==='unknown'||s==='unavailable')return null;const n=parseFloat(s);return isNaN(n)?null:n;};";
  const _fmt  = "const NUM=window.hemmaNum||((v,a,b)=>Number(v).toFixed(b==null?(a||0):b));const fmtPower=(v)=>v==null?'—':NUM(Math.round(v),0,0);const fmtEnergy=(v)=>{if(v==null)return'—';if(v<1)return NUM(v,2,2);if(v<10)return NUM(v,1,1);return NUM(Math.round(v),0,0);};const fmtMoney=(v,u)=>window.hemmaMoney?window.hemmaMoney(v,u,2):u+v.toFixed(2);";

  // Power → color
  const _powerScore = `
    const tNormal = ${tNormal}, tHeavy = ${tHeavy}, tExtreme = ${tExtreme};
    const power = safeNum(powerId);
    let color = 'var(--hemma-popup-green-color, #30D158)', label = T('energy.idle', 'Idle');
    if (power >= tExtreme)     { color = 'var(--hemma-popup-red-color, #ff4245)';    label = T('energy.extreme', 'Extreme'); }
    else if (power >= tHeavy)  { color = 'var(--hemma-popup-orange-color, #ff9230)'; label = T('energy.heavy', 'Heavy'); }
    else if (power >= tNormal) { color = 'var(--hemma-popup-yellow-color, #ffd600)'; label = T('energy.normal', 'Normal'); }
  `;

  // Tooltip time format
  const _tf = hass?.locale?.time_format;
  const _use12hr = _tf === '12' || (_tf !== '24' && new Intl.DateTimeFormat(hass?.locale?.language || 'en', { hour: 'numeric' }).resolvedOptions().hour12);
  const tooltipTimeFormat = _use12hr ? 'h:mm tt' : 'HH:mm';

  /* Styles */

  const noHoverStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; pointer-events: none !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const wrapperStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important; cursor: default !important; }',
    'ha-card:hover { box-shadow: none !important; }',
    '#container { overflow: visible !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const contentCardStyle = wrapperStyle + '\n@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }';

  const tileTapStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: inset 0 1px 0.5px -0.5px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-top-tight,0.20) * 1.5)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-bottom-tight,0.15) * 1.5)), inset 0 3px 6px -3px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-top-soft,0.08) * 1.5)), inset 0 -3px 6px -3px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-bottom-soft,0.05) * 1.5)) !important; }',
    'ha-card { background: var(--hemma-popup-tiles-fill, rgba(255,255,255,0.08)) !important; border: none !important; border-radius: 24px !important; box-shadow: inset 0 1px 0.5px -0.5px rgba(255,255,255,var(--hemma-popup-tiles-glow-top-tight,0.20)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,var(--hemma-popup-tiles-glow-bottom-tight,0.15)), inset 0 3px 6px -3px rgba(255,255,255,var(--hemma-popup-tiles-glow-top-soft,0.08)), inset 0 -3px 6px -3px rgba(255,255,255,var(--hemma-popup-tiles-glow-bottom-soft,0.05)) !important; backdrop-filter: var(--hemma-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; -webkit-backdrop-filter: var(--hemma-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; cursor: pointer !important; transform: scale(1) !important; transition: background-color var(--hemma-popup-tile-hover-duration, 0.2s) ease, transform var(--hemma-popup-tile-hover-duration, 0.2s) ease, box-shadow 0.2s ease !important; }',
    'ha-card:hover { background: var(--hemma-popup-tile-hover, rgba(255,255,255,0.09)) !important; transform: scale(var(--hemma-popup-tile-hover-scale, 1.01)) !important; }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  const tapStyle = [
    ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; pointer-events: auto !important; }',
    'ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important; }',
    'ha-card #container { transition: opacity 0.18s ease, filter 0.18s ease !important; }',
    'ha-card:hover #container { filter: brightness(1.12) saturate(1.08) drop-shadow(0 0 10px rgba(255,255,255,0.05)); }',
    'ha-ripple { display: none !important; }',
  ].join('\n');

  /* card_mod lands too late to hide the empty chart shell, so the
     entrance animation runs from apex_config instead. EVAL: is
     apexcharts-card's hook for a function in a serialised config. */
  const chartEnter = 'EVAL:' + [
    'function (ctx) {',
    '  try {',
    '    var graph = ctx && ctx.el;',
    '    if (!graph) return;',
    '    /* The host is what .content hides until this stamps it. Reveal',
    '       even on noData, or an empty chart stays invisible. */',
    '    /* mounted fires on the empty first render too, which is how a',
    '       chart with nothing in it got revealed and then redrawn. Wait',
    '       for a series with points; the 1600ms net still reveals a',
    '       chart that genuinely has no data. */',
    '    var g = ctx && ctx.w && ctx.w.globals;',
    '    var some = g && g.series && g.series.some(function (sr) {',
    '      return sr && sr.length;',
    '    });',
    '    if (!some) return;',
    '    var host = graph.getRootNode && graph.getRootNode().host;',
    '    var n = host, guard = 0;',
    '    while (n && guard++ < 6 && n.tagName !== "APEXCHARTS-CARD") {',
    '      n = n.parentElement || (n.getRootNode && n.getRootNode().host);',
    '    }',
    '    if (n && n.setAttribute) n.setAttribute("data-hemma-ready", "1");',
    '  } catch (e) {}',
    '}',
  ].join('\n');

  const graphStyle = `
    :host {
      position: relative !important;
      z-index: 1 !important;
      --ha-card-box-shadow: none !important;
      --button-card-box-shadow: none !important;
      --button-card-box-shadow-hover: none !important;
    }

    /* A ground to read the scale against. Apple's charts sit on a
       committed surface - the reference is lines on black - and a
       labeled axis over a room photo is unreadable at any opacity.
       Same fill and radius as the row groups, so the chart belongs to
       the same family as everything above it. */
    ha-card {
      background: transparent !important;
      border: none !important;
      border-radius: 0 !important;
      box-shadow: none !important;
      backdrop-filter: none !important;
      -webkit-backdrop-filter: none !important;
      overflow: visible !important;
      margin: 0 !important;
      padding: 0 !important;
      /* The theme puts will-change: filter, transform on every ha-card,
         and will-change: transform makes any descendant backdrop-filter
         inert. That is why the tooltip's blur never showed - the rule
         was applied and had nothing to do. The content cards opted out
         already; this one had not. */
      will-change: auto !important;
      --primary-color: transparent !important;
    }

    @media (max-width: 600px) { ha-card { margin: 0 !important; } }

    ha-card:hover {
      box-shadow: none !important;
      border-color: transparent !important;
    }

    #spinner-wrapper { display: none !important; }

    #graph {
      margin: 0 !important;
      padding: 8px 0 !important;
      overflow: visible !important;
      background: transparent !important;
    }

    .apexcharts-canvas {
      overflow: visible !important;
      background: transparent !important;
    }

    .apexcharts-canvas > svg {
      /* The edge fade is gone. It was how the chart blended into the
         photo when it had no surface of its own; over a plate with a
         labeled axis it ate the axis labels and clipped both ends of
         every line. Apple's chart has hard edges because it has a
         ground. */
      overflow: visible !important;
    }

    .apexcharts-tooltip {
      transition: opacity 0.12s ease !important;
      display: inline-block !important;
      width: max-content !important;
      max-width: 160px !important;
      min-width: 80px !important;
      white-space: nowrap !important;
      /* Flat, and lighter than the plate it sits on. The blur stays -
         it lifts the colors of whatever it covers - but the specular
         rim goes: four inset highlights and a lightening gradient are
         a glass object, and these widgets are not glass objects. Health
         and Stocks both use a plain raised slab for this. */
      /* Black, not a gray. 46/48/54 carried a blue cast that read as a
         different material from the plate under it; the blur behind is
         what keeps it from going flat, so the fill can just be dark.
         One variable across every popup that draws a chart. */
      background: var(--hemma-chart-tooltip-fill,
        rgba(0, 0, 0, 0.72)) !important;
      backdrop-filter: var(--hemma-chart-tooltip-backdrop,
        blur(16px) saturate(1.4)) !important;
      -webkit-backdrop-filter: var(--hemma-chart-tooltip-backdrop,
        blur(16px) saturate(1.4)) !important;
      border: none !important;
      border-radius: 14px !important;
      box-shadow: var(--hemma-chart-tooltip-shadow,
        0 10px 24px -12px rgba(0, 0, 0, 0.65),
        0 2px 6px -3px rgba(0, 0, 0, 0.40)) !important;
      overflow: hidden !important;
    }

    .apexcharts-tooltip-title,
    .apexcharts-tooltip-series-group {
      width: auto !important;
      max-width: 120px !important;
    }

    .apexcharts-tooltip-title {
      background: transparent !important;
      border-bottom: none !important;
      font-size: 10px !important;
      color: rgba(255,255,255,0.58) !important;
      font-weight: 600 !important;
      padding: 9px 12px 2px !important;
      margin: 0 !important;
      letter-spacing: 0.07em !important;
      text-transform: uppercase !important;
    }

    .apexcharts-tooltip-series-group {
      background: transparent !important;
      padding: 0 12px 9px !important;
      align-items: center !important;
    }

    .apexcharts-tooltip-series-group.apexcharts-active {
      background: transparent !important;
    }

    .apexcharts-tooltip-marker { display: none !important; }
    .apexcharts-tooltip-text-y-label { display: none !important; }

    .apexcharts-tooltip-text-y-value {
      color: rgba(255,255,255,0.98) !important;
      font-weight: 700 !important;
      font-size: 16px !important;
      margin-left: 0 !important;
    }

    .apexcharts-xcrosshairs {
      stroke: rgba(255,255,255,0.14) !important;
      stroke-dasharray: 3 3 !important;
      stroke-width: 1 !important;
    }

    .apexcharts-xaxistooltip { display: none !important; }
    .apexcharts-ycrosshairs { display: none !important; }
  `;

  /* Power Gauge */
  const gaugeCard = _memoSub('gauge', String(powerId), () => ({
    type: 'custom:button-card',
    entity: powerId,
    tap_action: { action: 'more-info' },
    show_icon: false, show_name: false, show_label: false, show_state: false,
    card_mod: { style: tapStyle },
    styles: {
      card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '0' }],
      grid: [{ 'grid-template-areas': '"c"' }, { 'grid-template-columns': '1fr' }],
      custom_fields: { c: [{ 'justify-self': 'end' }] },
    },
    custom_fields: {
      c: `[[[
        const powerId = ${_pid};
        ${_safe}
        ${_fmt}
        ${_powerScore}
        const circ = 2 * Math.PI * 42;
        const dashOffset = circ - Math.min((power || 0) / 5000, 1) * circ;
        return '<div style="position:relative;width:120px;height:120px;">'
          + '<svg viewBox="0 0 100 100" style="width:100%;height:100%;transform:rotate(-90deg);">'
            + '<circle cx="50" cy="50" r="42" fill="none" stroke="var(--hemma-popup-progress-track, rgba(255,255,255,0.08))" stroke-width="7"/>'
            + '<circle cx="50" cy="50" r="42" fill="none" stroke="' + color + '" stroke-width="7" stroke-linecap="round" stroke-dasharray="' + circ.toFixed(2) + '" stroke-dashoffset="' + dashOffset.toFixed(2) + '"/>'
          + '</svg>'
          + '<div style="position:absolute;inset:0;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:4px;">'
