  const _fmt  = "const NUM=window.hemmaNum||((v,a,b)=>Number(v).toFixed(b==null?(a||0):b));const fmtPower=(v)=>v==null?'—':NUM(Math.round(v),0,0);const fmtEnergy=(v)=>{if(v==null)return'—';if(v<1)return NUM(v,2,2);if(v<10)return NUM(v,1,1);return NUM(Math.round(v),0,0);};const fmtMoney=(v,u)=>window.hemmaMoney?window.hemmaMoney(v,u,2):u+v.toFixed(2);";

