    else if (power >= tHeavy)  { color = 'var(--hemma-popup-orange-color, #ff9230)'; label = T('energy.heavy', 'Heavy'); }
    else if (power >= tNormal) { color = 'var(--hemma-popup-yellow-color, #ffd600)'; label = T('energy.normal', 'Normal'); }
  `;

