      --button-card-box-shadow-hover: none !important;
    }

    /* A ground to read the scale against. Apple's charts sit on a
       committed surface - the reference is lines on black - and a
       labeled axis over a room photo is unreadable at any opacity.
       Same fill and radius as the row groups, so the chart belongs to
       the same family as everything above it. */
    ha-card {
      background: transparent !important;
      border: none !important;
      border-radius: 0 !important;
      box-shadow: none !important;
      backdrop-filter: none !important;
      -webkit-backdrop-filter: none !important;
      overflow: visible !important;
      margin: 0 !important;
