  const dir = (!dlOk || (ulOk && ul > dl)) ? T('network.upload', 'Upload') : T('network.download', 'Download');

  let advice;

  if (dlOk || ulOk) {
    advice = max < idle
      ? T('network.connection_idle', 'Connection idle')
      : T('network.activity', '{tier} {dir}', { tier, dir });
