      custom_fields: { d: [{ 'justify-self': 'stretch' }, { overflow: 'visible' }] },
    },
    custom_fields: {
      d: '<div style="height:5px;background:rgba(255,255,255,0.07);border-radius:20px;"></div>',
    },
  };

  /* Action Buttons */

  const makeActionButton = (entityId, label, statusId, confirmHelper, doneHelper) => {
    const s = entityId ? states[entityId] : null;
    const nameLabel = label
      || (statusId && (hass?.entities?.[statusId]?.name || states[statusId]?.attributes?.friendly_name))
      || hass?.entities?.[entityId]?.name
      || s?.attributes?.friendly_name
      || (entityId ? entityId.split('.')[1].replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()) : '—');
    const iconAttr = ((statusId && (hass?.entities?.[statusId]?.icon || states[statusId]?.attributes?.icon))
      || (entityId && (hass?.entities?.[entityId]?.icon || s?.attributes?.icon))
      || 'mdi:restart').replace(/'/g, "\\'");

    const _esc = nameLabel.replace(/\\/g, '\\\\').replace(/'/g, "\\'");
    const _ch  = confirmHelper || '';
    const _dh  = doneHelper    || '';
    const _sid = statusId || '';

    const cancelPillStyle = [
      ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
      'ha-card { min-height: 0 !important; background: rgba(255,255,255,0.08) !important; border: none !important; border-radius: 999px !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: pointer !important; transition: background 0.15s ease !important; }',
      'ha-card:hover { background: rgba(255,255,255,0.14) !important; }',
      'ha-ripple { display: none !important; }',
    ].join('\n');

    const actionPillModStyle = [
      ':host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }',
      'ha-card { min-height: 0 !important; border-radius: 999px !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: pointer !important; }',
      '@keyframes hemma-confirm-pop { from { opacity: 0.2; transform: scale(0.86); } to { opacity: 1; transform: scale(1); } }',
      'ha-ripple { display: none !important; }',
    ].join('\n');

    /* Tap actions */
    const cancelTap = _ch
      ? { action: 'call-service', service: 'input_boolean.turn_off', service_data: { entity_id: _ch } }
      : { action: 'none' };

    /* Cancel */
    const cancelPillCard = {
      type: 'custom:button-card', name: L('ui.common.cancel', 'Cancel'), tap_action: cancelTap,
      show_icon: false, show_name: true, show_label: false, show_state: false,
      card_mod: { style: cancelPillStyle },
      styles: {
        card: [{ padding: '10px 14px' }],
        name: [{ 'font-size': '13px' }, { 'font-weight': '600' }, { color: 'rgba(255,255,255,0.6)' }, { 'white-space': 'nowrap' }, { 'line-height': '20px' }, { 'font-family': 'var(--primary-font-family,system-ui)' }],
      },
    };

    /* Smart action */
    // Name
    const actionName = (_ch || _dh) ? `[[[
      const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
      const ch = '${_ch}', dh = '${_dh}';
      if (dh && states[dh]?.state === 'on') return '';
      if (ch && states[ch]?.state === 'on') return T('network.confirm', 'Confirm');
      return T('network.restart', 'Restart');
    ]]]` : T('network.restart', 'Restart');

    const actionShowName = _dh ? `[[[return states['${_dh}']?.state !== 'on']]]` : true;
    const actionShowIcon = _dh ? `[[[return states['${_dh}']?.state === 'on']]]` : false;
    const actionIcon     = _dh ? `[[[return states['${_dh}']?.state === 'on' ? 'mdi:check-bold' : null]]]` : null;

    // Background
    const actionBg = (_ch || _dh) ? `[[[
      const ch = '${_ch}', dh = '${_dh}';
      if (dh && states[dh]?.state === 'on') return 'color-mix(in srgb,#44e371 24%,transparent)';
      if (ch && states[ch]?.state === 'on') return 'color-mix(in srgb,#ff4245 26%,transparent)';
      return 'rgba(255,255,255,0.13)';
    ]]]` : 'rgba(255,255,255,0.13)';

    const actionBorder = (_ch || _dh) ? `[[[
      const ch = '${_ch}', dh = '${_dh}';
      if (dh && states[dh]?.state === 'on') return '1px solid color-mix(in srgb,#44e371 55%,transparent)';
      if (ch && states[ch]?.state === 'on') return '1px solid color-mix(in srgb,#ff4245 55%,transparent)';
      return '1px solid transparent';
    ]]]` : '1px solid transparent';

    // ha-card animation
    const actionAnim = (_ch || _dh) ? `[[[
      const ch = '${_ch}', dh = '${_dh}';
      return (states[ch]?.state === 'on' || states[dh]?.state === 'on') ? 'hemma-confirm-pop' : 'none';
    ]]]` : 'none';

    // Container div animation
    const actionContainerAnim = (_ch || _dh) ? `[[[
      const ch = '${_ch}', dh = '${_dh}';
      return (states[ch]?.state === 'on' || states[dh]?.state === 'on') ? 'none' : 'hemma-action-swap';
    ]]]` : 'none';

    const actionColor = (_ch || _dh) ? `[[[
      const ch = '${_ch}', dh = '${_dh}';
      if (dh && states[dh]?.state === 'on') return 'var(--hemma-badge-network-online-color,#44e371)';
      if (ch && states[ch]?.state === 'on') return 'var(--hemma-popup-red-color,#ff4245)';
      return 'var(--hemma-popup-tiles-text-primary)';
    ]]]` : 'var(--hemma-popup-tiles-text-primary)';

    const actionFontWeight = (_ch || _dh) ? `[[[
      const ch = '${_ch}', dh = '${_dh}';
      return (ch && states[ch]?.state === 'on') || (dh && states[dh]?.state === 'on') ? '700' : '600';
    ]]]` : '600';

    const actionPillCard = {
      type: 'custom:button-card', entity: entityId || dlId,
      name: actionName,
      tap_action: entityId && _ch
        ? { action: 'call-service', service: 'script.turn_on', service_data: { entity_id: 'script.hemma_restart_toggle', variables: { button_entity: entityId, helper_entity: _ch, done_entity: _dh } } }
        : (entityId ? { action: 'call-service', service: 'button.press', service_data: { entity_id: entityId } } : { action: 'none' }),
      show_icon: actionShowIcon, show_name: actionShowName, show_label: false, show_state: false,
      icon: actionIcon,
      card_mod: { style: actionPillModStyle },
      styles: {
        card: [
          { padding: '10px 18px' },
          { transition: 'background 0.35s ease, border-color 0.35s ease' },
          { background: actionBg },
          { border: actionBorder },
          { 'animation-name': actionAnim },
          { 'animation-duration': '0.26s' },
          { 'animation-timing-function': 'cubic-bezier(0.34,1.26,0.64,1)' },
          { 'animation-fill-mode': 'forwards' },
        ],
        name: [
          { 'font-size': '13px' }, { 'white-space': 'nowrap' }, { 'letter-spacing': '.01em' }, { 'font-family': 'var(--primary-font-family,system-ui)' },
          { 'line-height': '20px' },
          { transition: 'color 0.35s ease' },
          { 'font-weight': actionFontWeight },
          { color: actionColor },
        ],
        icon: [
          { color: 'var(--hemma-badge-network-online-color,#44e371)' },
          { width: '20px' }, { height: '20px' },
        ],
      },
    };

    /* Display */
    const infoOpacity = (_ch || _dh)
      ? `[[[return (states['${_ch}']?.state === 'on' || states['${_dh}']?.state === 'on') ? '0' : '1']]]`
      : '1';
    const infoPE = (_ch || _dh)
      ? `[[[return (states['${_ch}']?.state === 'on' || states['${_dh}']?.state === 'on') ? 'none' : 'auto']]]`
      : 'auto';
    // animation-fill-mode:both applies from{opacity:0} the same tick display:flex takes effect.
    const caVisible = _ch
      ? `states['${_ch}']?.state === 'on' && states['${_dh}']?.state !== 'on'`
      : 'false';
    const caDisplay      = _ch ? `[[[return ${caVisible} ? 'flex' : 'none']]]` : 'none';
    const caContainerAnim = _ch ? `[[[return ${caVisible} ? 'hemma-ca-in' : 'none']]]` : 'none';

    /* Info field */
    const infoField = _sid ? `[[[
      const L = (k, en) => { const v = hass?.localize?.(k); return (v && v !== k) ? v : en; };
      const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split(String.fromCharCode(123) + p + String.fromCharCode(125)).join(String(v[p])); return s; });
      const sid = '${_sid}', name = '${_esc}';
      const ss = states[sid];
      const unav = !ss || ss.state === 'unavailable' || ss.state === 'unknown';
      let stc = 'rgba(255,255,255,0.4)', stt = unav ? L('state.default.unknown', 'Unknown') : null;
      if (!unav) { if (ss.state === 'on') { stt = T('network.connected', 'Connected'); stc = 'var(--hemma-badge-network-online-color,#44e371)'; } else { stt = T('network.offline', 'Offline'); stc = 'var(--hemma-badge-network-offline-color,#ff4245)'; } }
      const sr = stt ? '<div style="margin-top:0;"><span style="font-size:12px;color:' + stc + ';font-weight:500;letter-spacing:.01em;">' + stt + '</span></div>' : '';
      return '<div style="display:flex;flex-direction:column;align-items:flex-start;">'
        + '<span style="font-size:13px;font-weight:600;color:var(--hemma-popup-tiles-text-primary);letter-spacing:.01em;white-space:nowrap;">' + name + '</span>'
        + sr + '</div>';
    ]]]` : '<div style="display:flex;flex-direction:column;align-items:flex-start;"><span style="font-size:13px;font-weight:600;color:var(--hemma-popup-tiles-text-primary);letter-spacing:.01em;white-space:nowrap;">' + nameLabel + '</span></div>';

    /* Outer tile */
    const outerTap = _ch ? {
      action: `[[[return states['${_ch}']?.state === 'on' ? 'call-service' : '${_sid || entityId ? 'more-info' : 'none'}']]]`,
      service: 'input_boolean.turn_off',
      service_data: { entity_id: _ch },
      entity: statusId || entityId,
    } : (statusId ? { action: 'more-info', entity: statusId } : (entityId ? { action: 'more-info' } : { action: 'none' }));

    return {
      ...baseCard,
      entity: entityId || dlId,
      tap_action: outerTap,
      card_mod: { style: tileTapStyle },
      styles: {
        card: [{ padding: '18px 18px 16px 18px' }],
        grid: [{ display: 'flex' }, { 'flex-direction': 'row' }, { 'align-items': 'center' }, { gap: '10px' }],
        custom_fields: {
          icon:   [{ flex: '0 0 auto' }],
          info:   [{ flex: '1 1 auto' }, { 'min-width': '0' }, { 'text-align': 'left' }, { transition: 'opacity 0.3s ease' }, { opacity: infoOpacity }, { 'pointer-events': infoPE }],
          ca:     [{ 'flex-shrink': '0' }, { overflow: 'hidden' }, { display: caDisplay }, { 'animation-name': caContainerAnim }, { 'animation-duration': '0.3s' }, { 'animation-timing-function': 'ease' }, { 'animation-fill-mode': 'both' }],
          action: [{ 'flex-shrink': '0' }, { 'animation-name': actionContainerAnim }, { 'animation-duration': '0.3s' }, { 'animation-timing-function': 'ease' }, { 'animation-fill-mode': 'both' }],
        },
      },
      custom_fields: {
        icon:   '<ha-icon icon="' + iconAttr + '" style="--mdc-icon-size:22px;width:22px;height:22px;display:flex;align-items:center;justify-content:center;flex-shrink:0;color:var(--hemma-popup-tiles-text-muted);"></ha-icon>',
        info:   infoField,
        ca:     { card: cancelPillCard },
        action: entityId ? { card: actionPillCard } : '<div></div>',
      },
    };
  };

  const actionCount = (action1Id ? 1 : 0) + (action2Id ? 1 : 0);
  const actionAreas = actionCount === 1 ? (action1Id ? '"a1"' : '"a2"') : '"a1 a2"';
  const actionCols  = actionCount === 1 ? '1fr' : '1fr 1fr';

  const actionsCard = hasActions ? {
    ...baseCard,
    entity: dlId,
    tap_action: { action: 'none' },
    card_mod: { style: contentCardStyle + '\n@media (max-width:600px){#container{grid-template-columns:1fr !important;grid-template-areas:"a1" "a2" !important;}}' },
    styles: {
      card: [
        { background: 'transparent' },
        { border: 'none' },
        { 'box-shadow': 'none' },
        { padding: '0 28px 20px 28px' },
      ],
      grid: [
        { 'grid-template-areas': actionAreas },
        { 'grid-template-columns': actionCols },
        { gap: '8px' },
        { 'align-items': 'start' },
      ],
      custom_fields: {
        a1: [{ 'grid-area': 'a1' }, { 'justify-self': 'stretch' }],
        a2: [{ 'grid-area': 'a2' }, { 'justify-self': 'stretch' }],
      },
    },
    custom_fields: {
      a1: action1Id ? { card: makeActionButton(action1Id, action1Label, action1Stat, action1ConfirmHelper, action1DoneHelper) } : '<div></div>',
      a2: action2Id ? { card: makeActionButton(action2Id, action2Label, action2Stat, action2ConfirmHelper, action2DoneHelper) } : '<div></div>',
    },
  } : null;

  /* Final Stack */

  /* Shared popup anatomy. The advice caption becomes the hero, the
     Download|Upload block becomes the graph's own legend, and the four
     tiles plus the restart buttons become grouped rows. */
  const UI = window._hemmaUI;
  let _cards;
  if (UI) {
    const NUM = (window.hemmaNum || ((x, a, b) => Number(x).toFixed(b ?? a ?? 0)));
    const fmt = (v) => v == null ? '\u2014' : (v >= 100 ? NUM(Math.round(v), 0, 0) : NUM(v, 0, 1));
    const dlCol = SERIES_1;
    const ulCol = SERIES_2;

    const areas = [], fields = {}, fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
    };

    const tone = !online ? 'bad' : (tier === T('network.heavy', 'Heavy') ? 'warn' : 'good');
    const metricAreas = [], metricFields = {}, metricStyle = {};
    const addMetric = (n2, html) => {
      metricAreas.push('"' + n2 + '"');
      metricFields[n2] = html;
      metricStyle[n2] = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];
    };

    addMetric('head', UI.hero({
      compact: true,
      label: T('network.connection', 'Connection'),
      value: online ? advice : T('network.offline', 'Offline'),
      trailingLabel: ping != null ? T('network.ping', 'Ping') : null,
      trailing: ping != null ? Math.round(ping) + ' ms' : null,
    }));

    /* The chart goes under the number it explains, not at the foot of
       the sheet. Health, Battery and Stocks all do this: headline,
       chart, then the lists. It was last only because that is where the
       pre-redesign layout left it. As a field inside the content card
       rather than a sibling in the stack, so it can sit between the
       hero and the first group - and the side gutter comes from the
       card, so the chart drops its own. */
    addMetric('chart', { card: graphCard });
    addMetric('legend', UI.legend([
      { color: dlCol, value: fmt(dl), label: T('network.mbps_down', 'Mbit/s down') },
      { color: ulCol, value: fmt(ul), label: T('network.mbps_up', 'Mbit/s up') },
    ]));

    const throughput = [];
    const push = (label, icon, id) => {
      const v = safeNum(id);
      if (id) throughput.push({ icon: icon,
        iconTone: /upload/i.test(label) ? ulCol : dlCol,
        label: label, value: T('network.mbps', '{v} Mbit/s', { v: fmt(v) }), entity: id });
    };
    push(T('network.wired_download', 'Wired download'), 'arrow-down', wiredDlId);
    push(T('network.wired_upload', 'Wired upload'),   'arrow-up',   wiredUlId);
    push(T('network.wifi_download', 'Wi-Fi download'), 'wifi',       wifiDlId);
    push(T('network.wifi_upload', 'Wi-Fi upload'),   'wifi',       wifiUlId);
    if (throughput.length) {
      add('tp', UI.group(throughput, null, null, { labelInside: true }));
    }

    /* Confirm lives in the row and is entirely client-side: the popup
       content is built once, so anything that needs the template to
       re-evaluate cannot update in place. */
    const devices = [];
    const nameFor = (id, label, statId) => label
      || (statId && (hass?.entities?.[statId]?.name || states[statId]?.attributes?.friendly_name))
      || hass?.entities?.[id]?.name
      || states[id]?.attributes?.friendly_name
      || (id ? id.split('.')[1].replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase()) : T('network.device', 'Device'));
    const deviceGlyph = (id, label) => {
      const t = ((label || '') + ' ' + (id || '')).toLowerCase();
      if (/mesh|wifi|wi-fi|access.?point|ap\b/.test(t)) return 'mesh';
      if (/internet|wan|status|modem|gateway|isp/.test(t)) return 'network';
      return 'access_point';
    };
    const addDevice = (id, label, statId) => {
      if (!id) return;
      const dom = id.split('.')[0];
      devices.push({
        icon: deviceGlyph(id, nameFor(id, label, statId)),
        label: nameFor(id, label, statId),
        entity: statId || id,
        action: T('network.restart', 'Restart'),
        confirm: true,
        svc: dom === 'button'
          ? { domain: 'button', service: 'press', target: { entity_id: id } }
          : { domain: 'homeassistant', service: 'turn_on', target: { entity_id: id } },
      });
    };
    addDevice(action1Id, action1Label, action1Stat);
    addDevice(action2Id, action2Label, action2Stat);
    if (devices.length) {
      add('dev', UI.group(devices, null, null, { labelInside: true }));
    }

    /* One object: the number, its status and the curve it describes, on
       a single plate. They were two stacked blocks - a floating stat
       with a graph under it - which is the part that never read as
       Apple. Health, Battery and Stocks all bind the headline to the
       chart. The plate moved here from the chart card, which is
       transparent inside it now. */
    const metricCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      extra_styles: '@keyframes hemma-plate-hold { from, to { opacity: 0; } }'
        + ' @keyframes hemma-plate-in {'
        + ' from { opacity: 0; transform: perspective(900px) translateZ(-70px); }'
        + ' to { opacity: 1; transform: perspective(900px) translateZ(0); } }'
        + ' ha-card { animation: var(--hemma-popup-plate-enter, none);'
        + ' animation-delay: var(--hemma-popup-plate-delay, 0ms); }'
        + ' apexcharts-card:not([data-hemma-ready]) { opacity: 0; }'
        + ' apexcharts-card { transition: opacity'
        + ' var(--hemma-popup-chart-enter, 140ms)'
        + ' var(--hemma-popup-chart-enter-ease, ease-out); }'
        + ' @media (prefers-reduced-motion: reduce) {'
        + ' apexcharts-card { transition: none; } }',
      card_mod: { style: [
        ':host { --ha-card-box-shadow: none !important;'
          + ' --button-card-box-shadow: none !important;'
          + ' --button-card-box-shadow-hover: var(--hemma-popup-plate-shadow, none) !important;'
          + ' --hemma-card-hover-shadow: var(--hemma-popup-plate-shadow, none) !important;'
          + ' --hemma-card-hover-filter: none !important;'
          + ' --hemma-hover-filter: none !important;'
          + ' --ha-card-backdrop-filter: none !important; }',
        'ha-card { background: var(--hemma-popup-chart-fill, rgba(0,0,0,0.26)) !important;'
          + ' border: none !important;'
          + ' border-radius: var(--hemma-popup-row-radius, 20px) !important;'
          + ' box-shadow: var(--hemma-popup-plate-shadow, none) !important;'
          + ' backdrop-filter: var(--hemma-popup-plate-backdrop, none) !important;'
          + ' -webkit-backdrop-filter: var(--hemma-popup-plate-backdrop, none) !important;'
          + ' overflow: visible !important;'
          + ' will-change: auto !important; cursor: default !important; }',
        '#container > * { --hemma-card-hover-shadow: none !important;'
          + ' --button-card-box-shadow-hover: none !important; }',
        'ha-card::before, ha-card::after { display: none !important; }',
        'ha-card:hover { box-shadow: var(--hemma-popup-plate-shadow, none) !important;'
          + ' background: var(--hemma-popup-chart-fill, rgba(0,0,0,0.26)) !important;'
          + ' border-color: transparent !important; filter: none !important; }',
        'ha-ripple { display: none !important; }',
      ].join('\n') },
      styles: {
        card: [
          { background: 'var(--hemma-popup-chart-fill, rgba(0,0,0,0.26))' },
          { 'border-radius': 'var(--hemma-popup-row-radius, 20px)' },
          { 'backdrop-filter': 'var(--hemma-popup-plate-backdrop, none)' },
          { '-webkit-backdrop-filter': 'var(--hemma-popup-plate-backdrop, none)' },
          { 'box-shadow': 'var(--hemma-popup-plate-shadow, none)' },
          { border: 'none' }, { padding: '30px 28px 26px 28px' },
        ],
        grid: [{ 'grid-template-areas': metricAreas.join(' ') },
               { 'grid-template-columns': 'minmax(0, 1fr)' },
               { 'row-gap': '0' }],
        custom_fields: metricStyle,
      },
      custom_fields: metricFields,
    };
    areas.unshift('"metric"');
    fields.metric = { card: metricCard };
    fstyle.metric = [{ 'justify-self': 'stretch' }, { overflow: 'visible' }];

    const aside = fstyle.dev ? 'dev' : null;
    const mainAreas = areas
      .map((a) => a.replace(/"/g, ''))
      .filter((k) => k !== aside);
    const sideBySide = !!aside && mainAreas.length >= 1;
    const sideAreas = sideBySide
      ? mainAreas.map((k, i) => '"' + k + ' ' + (i === 0 ? aside : '.') + '"').join(' ')
      : '';

    const order = sideBySide ? [mainAreas[0], aside].concat(mainAreas.slice(1))
                             : areas.map((a) => a.replace(/"/g, ''));
    order.forEach((key, i) => {
      if (fstyle[key]) {
        fstyle[key].push({ '--hemma-popup-plate-delay': (i * 55) + 'ms' });
      }
    });


    const uiCard = {
      type: 'custom:button-card',
      card_mod: { style: contentCardStyle
        + '\nha-card { will-change: auto !important; }' },
      extra_styles: sideBySide
        ? '@media (max-width: 760px) { #container {'
          + ' grid-template-areas: ' + areas.join(' ') + ' !important;'
          + ' grid-template-columns: minmax(0, 1fr) !important; } }'
        : undefined,
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: '6px 26px 22px 26px' },
        ],
        grid: [
          { 'grid-template-areas': sideBySide ? sideAreas : areas.join(' ') },
          { 'grid-template-columns': sideBySide
              ? 'minmax(0, 1fr) fit-content(var(--hemma-popup-aside-max, 420px))'
              : 'minmax(0, 1fr)' },
          { 'row-gap': '18px' },
