popup_styles.styles:
/* No pane. The header sits on the room and each section stands in
   front of it as its own card, the way iOS groups settings on a
   background rather than inside one box. The room is still blurred,
   by the scrim, which is a sibling of the surface and so survives
   the pane going transparent. */
--hemma-popup-tint: transparent;
--hemma-popup-gutter-wide: 34px;
--hemma-popup-gutter-phone: 22px;
/* The close control's box starts at the bar's padding and the
   content starts at its own gutter; they line up only when the
   two are the same number. */
/* The popups have no pane, so headings and captions sit straight
   on the room. 6px is enough behind a panel and not enough behind
   bare text - this is scoped to the pane-less popups rather than
   raised globally, so the cover and lock sheets keep the lighter
   scrim they are built against. */
--hemma-popup-scrim-backdrop: blur(22px) saturate(1.5);
--hemma-popup-backdrop: none;
--hemma-popup-shadow: none;
/* The grain is two pseudo-elements on .glass, blending overlay and
   screen. They keep painting after the tint goes transparent, and a
   screen blend over noise is exactly the pale panel that survived
   the first attempt. */
/* Removed, not hidden: at opacity 0 the blend layer is invisible
   and costs the same as a visible one. */
--hemma-popup-grain-content: none;
--hemma-popup-grain: 0;
--hemma-popup-grain-dark: 0;
--hemma-popup-scrim: rgba(0, 0, 0, 0.26);

/* No chart here, so nothing to wait for: the widgets arrive as
   soon as they are built. Read by each widget for itself, never by
   a wrapper - an animated opacity on an ancestor flattens the frost
   inside it. */
--hemma-popup-plate-enter:
  hemma-plate-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
@media (prefers-reduced-motion: reduce) {
  --hemma-popup-plate-enter: none;
}

--hemma-popup-hero-label-size: 15px;
--hemma-popup-row-radius: 26px;
/* Frosted, not opaque. The pane's blur used to sit under these, and
   .content still nulls --ha-card-backdrop-filter for every card in
   the popup, so the frost has to be asked for here. The fills drop
   to let it read. */
/* The theme lifts every ha-card with filter: brightness(1.01) on
   hover. A filter on an ancestor makes every descendant's
   backdrop-filter inert, so hovering the empty space around a
   widget - the wrapper card - knocked the frost out of both of
   them. Killed popup-wide; the plate re-declares its own shadow. */
--hemma-card-hover-filter: none;
--hemma-hover-filter: none;
--hemma-card-hover-shadow: none;

--hemma-popup-row-pad-x: 26px;
--hemma-popup-row-pad-y: 15px;
--hemma-popup-plate-backdrop: blur(24px) saturate(180%);
--hemma-popup-chart-fill: rgba(10, 12, 16, 0.68);
--hemma-popup-row-fill: rgba(12, 14, 19, 0.62);
/* Lifted, not slabbed: one wide soft pass carries the height, one
   short contact pass keeps the edge from dissolving into the room. */
--hemma-popup-plate-shadow:
  0 18px 40px -22px rgba(0, 0, 0, 0.50),
  0 2px 8px -5px rgba(0, 0, 0, 0.28);

/* visionOS puts nothing bare on the room: the only chrome outside a
   window is its close control, and that control is itself a glass
   object. The title was printed twice - here and in the widget
   eight pixels below - so it goes, clipped rather than removed so a
   screen reader still gets it. */
/* The sheet's drag handle keeps working; only the little bar
   that advertises it goes. Nothing else on these popups is a hint. */
--hemma-popup-grabber: transparent;

/* The chrome arrives with the first plate instead of being there
   on frame one while everything under it fades in. */
--hemma-popup-chrome-enter:
  hemma-popup-chrome-in 320ms cubic-bezier(0.2, 0.8, 0.3, 1) both;
.content { animation: none; }
/* The title lives in the bar now, centered and level with the
   close control, so it is no longer hidden. */
.header-title { font-size: 20px; font-weight: 600; letter-spacing: -0.01em; }
/* 48px is left alone: the base sizes it so the glyph's ink lands on
   the same left margin as the widgets below. */
.header-close {
  border-radius: 50%;
  background: var(--hemma-popup-row-fill, rgba(255, 255, 255, 0.10));
  backdrop-filter: var(--hemma-popup-plate-backdrop, none);
  -webkit-backdrop-filter: var(--hemma-popup-plate-backdrop, none);
  box-shadow: var(--hemma-popup-plate-shadow, none);
}

ha-adaptive-dialog, ha-dialog, wa-drawer {
  --ha-card-backdrop-filter: none;
  --ha-card-background: transparent;
  --card-background-color: transparent;
  --ha-card-box-shadow: none;
  --ha-card-border-width: 0px;
}

hemma_popup.content:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const plant      = entity?.entity_id;
  const _plantName = plant ? plant.replace(/^[^.]+\./, '') : '';
  const plantAttrs = states[plant]?.attributes || {};
  const sensors    = Array.isArray(variables.sensors) ? variables.sensors.filter(Boolean) : [];

  const _ck = 'hemma_plant_v6_' + (plant || 'x');
  const _ch = [variables.room_name || '', states[plant]?.state, JSON.stringify(states[plant]?.attributes), ...sensors.map(s => states[s]?.state)].join('|');
  window._hc = window._hc || {};
  if (window._hc[_ck]?.h === _ch) return window._hc[_ck].r;

  const safeNum = (id) => {
    if (!id) return null;
    const s = states[id]?.state;
    if (!s || s === 'unavailable' || s === 'unknown') return null;
    const n = parseFloat(s);
    return isNaN(n) ? null : n;
  };

  const getSensorType = (eid) => {
    const id = eid.toLowerCase();
    if (id.includes('moisture'))                       return 'moisture';
    if (id.includes('illumin') || id.includes('lux')) return 'illuminance';
    if (id.includes('temp'))                           return 'temperature';
    if (id.includes('conductiv'))                      return 'conductivity';
    if (id.includes('humid'))                          return 'humidity';
    if (id.includes('battery'))                        return 'battery';
    return null;
  };

  const getThreshold = (type, dir) => {
    if (!type || type === 'battery' || !_plantName) return null;
    const slug = type === 'moisture' ? 'soil_moisture'
      : type === 'humidity' ? 'air_humidity'
      : type;
    const v = safeNum(`number.${_plantName}_${dir}_${slug}`);
    return v !== null ? v : safeNum(`number.${_plantName}_${dir}_${type}`);
  };

  const plantState = states[plant]?.state;
  const plantIsOk  = plantState === 'ok';
  const plantIsBad = plantState === 'problem';

  const gradable = sensors.filter(s => {
    const t = getSensorType(s);
    return t && t !== 'battery';
  });
  const readable = gradable.filter(s => safeNum(s) != null);

  /* `problems` and *_status are both absent until the integration is
   * fully set up, so the plant's own state is the authoritative gate. */
  const badTypes = {};
  if (plantIsBad) {
    (Array.isArray(plantAttrs.problems) ? plantAttrs.problems : []).forEach(p => {
      if (p && p.sensor_type) badTypes[p.sensor_type] = String(p.status || '').toLowerCase();
    });
    gradable.forEach(s => {
      const t = getSensorType(s);
      const v = plantAttrs[t + '_status'];
      if (!badTypes[t] && v && v !== 'ok' && v !== 'null') badTypes[t] = String(v).toLowerCase();
    });
  }

  /* A `problem` plant can arrive with no per-sensor detail at all -
   * the integration returns {} for extra_state_attributes until
   * plant_complete. We then know something is wrong but not what, so
   * no tile may claim to be OK. */
  const blind = !plantIsOk && !gradable.some(s => {
    const t = getSensorType(s);
    return badTypes[t] != null || Object.prototype.hasOwnProperty.call(plantAttrs, t + '_status');
  });

  const C_HEALTHY    = 'var(--hemma-badge-plant-healthy-color, #44e371)';
  const C_STRUGGLING = 'var(--hemma-badge-plant-struggling-color, #ff9230)';

  let advice;
  if (plantIsOk) {
    advice = T('plant.is_healthy', 'Plant is healthy');
  } else if (plantIsBad && blind) {
    advice = T('common.needs_attention', 'Needs attention');
  } else if (plantIsBad) {
    const maxScore = readable.length || gradable.length || 1;
    const badCount = Math.min(Object.keys(badTypes).length || 1, maxScore);
    const ratio    = (maxScore - badCount) / maxScore;

    if (ratio >= 0.8)      advice = T('plant.needs_some_attention', 'Needs some attention');
    else if (ratio >= 0.6) advice = T('plant.is_struggling', 'Plant is struggling');
    else if (ratio >= 0.4) advice = T('plant.needs_immediate_care', 'Needs immediate care');
    else                   advice = T('plant.needs_urgent_attention', 'Needs urgent attention');

    const dir = (t) => badTypes[t];
    if (dir('temperature'))  advice = dir('temperature')  === 'low' ? T('plant.too_cold', 'Too cold') : T('plant.too_warm', 'Too warm');
    if (dir('humidity'))     advice = dir('humidity')     === 'low' ? T('plant.air_too_dry', 'Air is too dry') : T('plant.air_too_humid', 'Air is too humid');
    if (dir('conductivity')) advice = dir('conductivity') === 'low' ? T('plant.needs_fertilizing', 'Needs fertilizing') : T('plant.too_much_fertilizer', 'Too much fertilizer');
    if (dir('illuminance'))  advice = dir('illuminance')  === 'low' ? T('plant.needs_more_light', 'Needs more light') : T('plant.too_much_light', 'Getting too much light');
    if (dir('moisture'))     advice = dir('moisture')     === 'low' ? T('plant.needs_watering', 'Needs watering') : T('plant.soil_too_wet', 'Soil is too wet');
  } else {
    advice = readable.length ? T('plant.waiting_for_data', 'Waiting for plant data') : T('plant.sensor_unavailable', 'Sensor data unavailable');
  }

  const cleanName = (eid) => {
    const fallback = states[eid]?.attributes?.friendly_name || eid.split('.').pop() || '';
    const pName    = (entity?.attributes?.friendly_name || '').trim();
    let name       = fallback;
    if (pName) {
      const esc = pName.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
      name = name.replace(new RegExp('^' + esc + '\\s*', 'i'), '');
    }
    return name.replace(/_/g, ' ').trim().replace(/\w\S*/g, t => t.charAt(0).toUpperCase() + t.slice(1).toLowerCase());
  };

  /* Styles */
  const wrapperStyle = `
    :host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; }
    ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; cursor: default !important; }
    ha-card:hover { box-shadow: none !important; }
    ha-ripple { display: none !important; }
  `;

  const contentCardStyle = wrapperStyle + `@media (max-width: 600px) { ha-card { padding-left: 14px !important; padding-right: 14px !important; } }`;

  const tapStyle = `
    :host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: none !important; pointer-events: auto !important; }
    ha-card { background: transparent !important; border: none !important; border-radius: 0 !important; box-shadow: none !important; backdrop-filter: none !important; -webkit-backdrop-filter: none !important; overflow: visible !important; }
    ha-card #container { transition: opacity 0.18s ease, filter 0.18s ease !important; }
    ha-card:hover #container { filter: brightness(1.12) saturate(1.08) drop-shadow(0 0 10px rgba(255,255,255,0.05)); }
    ha-ripple { display: none !important; }
  `;

  const tileTapStyle = `
    :host { --ha-card-box-shadow: none !important; --button-card-box-shadow: none !important; --button-card-box-shadow-hover: inset 0 1px 0.5px -0.5px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-top-tight,0.20) * 1.5)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-bottom-tight,0.15) * 1.5)), inset 0 3px 6px -3px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-top-soft,0.08) * 1.5)), inset 0 -3px 6px -3px rgba(255,255,255,calc(var(--hemma-popup-tiles-glow-bottom-soft,0.05) * 1.5)) !important; }
    ha-card { background: var(--hemma-popup-tiles-fill, rgba(255,255,255,0.08)) !important; border: none !important; border-radius: 24px !important; box-shadow: inset 0 1px 0.5px -0.5px rgba(255,255,255,var(--hemma-popup-tiles-glow-top-tight,0.20)), inset 0 -1px 0.5px -0.5px rgba(255,255,255,var(--hemma-popup-tiles-glow-bottom-tight,0.15)), inset 0 3px 6px -3px rgba(255,255,255,var(--hemma-popup-tiles-glow-top-soft,0.08)), inset 0 -3px 6px -3px rgba(255,255,255,var(--hemma-popup-tiles-glow-bottom-soft,0.05)) !important; backdrop-filter: var(--hemma-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; -webkit-backdrop-filter: var(--hemma-popup-tiles-backdrop, blur(10px) saturate(1.1)) !important; cursor: pointer !important; transform: scale(1) !important; transition: background-color var(--hemma-popup-tile-hover-duration, 0.2s) ease, transform var(--hemma-popup-tile-hover-duration, 0.2s) ease, box-shadow 0.2s ease !important; }
    ha-card:hover { background: var(--hemma-popup-tile-hover, rgba(255,255,255,0.09)) !important; transform: scale(var(--hemma-popup-tile-hover-scale, 1.01)) !important; }
    ha-ripple { display: none !important; }
  `;

  const cards = [];

  /* Shared popup anatomy. One subject - the plant - so the hero carries
     the verdict, and each sensor is one row: name and value.

     The bar and the target line are gone from healthy rows. Health,
     Home and the Batteries widget all put name-and-value in the list
     and keep the range in the detail view you tap through to; the only
     bar Apple shows in a list is iPhone Storage's, and that is one bar
     for the whole, not one per row. Three encodings of one reading read
     as a dashboard, not as Settings.

     The target comes back only on a reading the plant has actually
     flagged - the explanation appears when there is something to
     explain. Which is flagged stays the integration's call, never
     recomputed here from the thresholds. */
  const UI = window._hemmaUI;
  if (UI) {
    /* Soil water is water, so it reads teal like the other readings
       rather than green like a leaf. There is no sun in hemma-icons -
       mdi carries it, and hueFor picks the hue off the name. */
    const ICON_FOR = {
      moisture: 'mdi:water',
      humidity: 'humidity',
      illuminance: 'mdi:white-balance-sunny',
      temperature: 'temp-medium',
      conductivity: 'mdi:beaker-outline',
      battery: 'battery',
    };

    const rowFor = (eid) => {
      const type = getSensorType(eid);
      const val = safeNum(eid);
      const unit = states[eid]?.attributes?.unit_of_measurement || '';
      const minOpt = type ? getThreshold(type, 'min') : null;
      const maxOpt = type ? getThreshold(type, 'max') : null;
      const isOk = !type || !badTypes[type];
      const noVerdict = val == null || (blind && type && type !== 'battery');

      /* The unit rides the band once, not on both ends: "800-6.0k lx",
         not "800 lx-6.0k lx". No space before % or a degree sign, a
         space before everything else - Apple's own rule. */
      const n = (v) => v == null ? ''
        : v >= 1000 ? (window.hemmaNum || ((x, a, b) => Number(x).toFixed(b ?? a ?? 0)))(v / 1000, 0, v >= 10000 ? 0 : 1) + 'k'
        : String(Math.round(v));
      const u = !unit ? ''
        : (unit === '%' || unit.charAt(0) === '\u00b0') ? unit
        : ' ' + unit;

      const band = (minOpt != null && maxOpt != null)
        ? T('plant.target_range', 'Target {min}–{max}{u}', { min: n(minOpt), max: n(maxOpt), u })
        : minOpt != null ? T('plant.target_above', 'Target above {v}{u}', { v: n(minOpt), u })
        : maxOpt != null ? T('plant.target_below', 'Target below {v}{u}', { v: n(maxOpt), u })
        : null;

      const tone = noVerdict ? null : (isOk ? null : 'warn');
      return {
        entity: eid,
        icon: ICON_FOR[type] || 'plant',
        label: cleanName(eid),
        // Only on a flagged reading: a healthy row is name and value.
        sub: tone ? band : null,
        value: val == null ? '\u2014' : n(val) + u,
        valueTone: tone,
      };
    };

    const areas = [], fields = {}, fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }];
    };

    /* One statement, not two. "Healthy" over "Plant is healthy" said
       the same thing twice; when something IS wrong the advice is the
       more useful of the pair, so it becomes the value outright -
       "Needs watering" beats "Problem" with the reason underneath.
       No tone on it: the row's own value is what flags, and a
       colored headline on top of that is the third time of asking. */
    /* Bare on the room, the way Apple's device sheets name themselves:
       the plant over its condition, no card. A title inside a plate is
       a banner, and the caption inside the first plate said it twice. */
    /* The watering line is computed from history, which arrives after
       the popup is already up, so the slot is drawn empty and filled by
       plantWater(). The id carries the entity so a second plant popup
       cannot paint into the first one's caption. */
    const _moist = sensors.find(e => getSensorType(e) === 'moisture') || null;
    const _capId = 'plantcap-' + String(plant || 'x').replace(/[^a-zA-Z0-9]/g, '_');
    add('head', UI.headline ? UI.headline({
      title: (variables.room_name || plantAttrs.friendly_name || '').trim() || T('plant.title', 'Plant'),
      state: plantIsOk ? T('state.healthy', 'Healthy') : (advice || T('common.needs_attention', 'Needs attention')),
      barTitle: true,
      // the lock and cover measure, so the sheets read alike
      measure: 'sheet',
      captionSlot: !!_moist,
      captionId: _capId,
    }) : '');

    if (_moist) {
      const _dry = getThreshold('moisture', 'min');
      add('watercap', `[[[
        const el = document.querySelector('home-assistant');
        const find = (root) => {
          if (!root) return null;
          const hit = root.getElementById ? root.getElementById('${_capId}') : null;
          if (hit) return hit;
          const kids = root.querySelectorAll ? root.querySelectorAll('*') : [];
          for (const k of kids) if (k.shadowRoot) {
            const f = find(k.shadowRoot); if (f) return f;
          }
          return null;
        };
        setTimeout(() => {
          const node = find(document);
          if (node && window._hemmaUI && window._hemmaUI.plantWater) {
            window._hemmaUI.plantWater(node, '${_moist}', ${_dry == null ? 'null' : _dry});
          }
        }, 60);
        return '';
      ]]]`);
      fstyle.watercap = [{ display: 'none' }, { height: '0' }, { width: '0' }];
    }


    /* One widget, no headings. Splitting the readings into "Needs
       attention" and "All other readings" said twice what the rows
       already say - a reading that is out of range is colored and
       carries its target, and the condition line at the top names the
       state. The ones that need attention simply sort first. */
    const problem = sensors.filter((e) => {
      const t = getSensorType(e);
      return t && badTypes[t];
    });
    const rest = sensors.filter((e) => problem.indexOf(e) < 0);
    const ordered = problem.concat(rest);
    if (ordered.length) add('all', UI.group(ordered.map(rowFor), null, null,
      { labelInside: true }));
    if (!sensors.length) add('none', UI.note(T('plant.none_configured', 'No plant sensors configured')));

    areas.forEach((a, i) => {
      const key = a.replace(/"/g, '');
      if (fstyle[key]) {
        fstyle[key].push({ overflow: 'visible' });
        fstyle[key].push({ '--hemma-popup-plate-delay': (i * 55) + 'ms' });
      }
    });

    cards.push({
      type: 'custom:button-card',
      entity: plant,
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: contentCardStyle
        + '\nha-card { will-change: auto !important; }' },
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: '6px 26px 22px 26px' },
        ],
        grid: [
          { 'grid-template-areas': areas.join(' ') },
          { 'grid-template-columns': '1fr' },
          { 'row-gap': '18px' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
    });
  }


  const _r = { type: 'vertical-stack', cards };
  window._hc[_ck] = { h: _ch, r: _r };
  return _r;
]]]

