   .sort((a, b) => new Date(b.airdate || 0) - new Date(a.airdate || 0));
  const N = items.length;

  /* helpers */
  const esc = s => String(s ?? '')
    .replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;')
    .replace(/"/g,'&quot;').replace(/'/g,'&#39;');

  const resolveUrl = raw => {
    if (!raw) return '';
    const s = String(raw);
