      card_mod: { style: noHoverStyle },
      styles: {
        card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '28px 28px 0 28px' }],
        grid: [{ 'grid-template-areas': '"title badge"' }, { 'grid-template-columns': '1fr auto' }, { 'align-items': 'flex-start' }],
        custom_fields: {
          title: [{ 'justify-self': 'start' }, { 'text-align': 'left' }],
          badge: [{ 'justify-self': 'end' }, { 'align-self': 'flex-start' }],
        },
      },
      custom_fields: {
        title: '<div style="font-family:var(--primary-font-family,system-ui);color:var(--hemma-popup-tiles-text-primary);">'
          + '</div>',
        badge: { card: emptyBadge },
      },
    };

    const emptyAdvice = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: noHoverStyle },
      styles: {
        card: [{ background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' }, { padding: '20px 28px 18px 28px' }],
        grid: [{ 'grid-template-areas': '"body"' }, { 'grid-template-columns': '1fr' }],
        custom_fields: { body: [{ 'justify-self': 'stretch' }, { width: '100%' }, { 'text-align': 'left' }] },
      },
      custom_fields: {
        body: '<div style="font-family:var(--primary-font-family,system-ui);">'
          + '<div style="font-size:22px;color:var(--primary-text-color,#ffffff);font-weight:400;letter-spacing:-.5px;">' + T('plex.nothing_added', 'Nothing recently added') + '</div>'
          + '</div>',
      },
    };

    return { type: 'vertical-stack', cards: [emptyHeader, emptyAdvice] };
  }

  /* responsive layout */
  const isMobile     = window.innerWidth < 600;
  const slideH       = isMobile ? 420 : 330;
  const swipeH       = slideH + 14;

  /* shared extra_styles for transparent button-cards */
  const transparentStyles = 'ha-card{'
    + 'background:transparent!important;'
    + 'border:none!important;'
    + 'box-shadow:none!important;'
    + '-webkit-backdrop-filter:none!important;'
    + 'backdrop-filter:none!important;'
    + 'will-change:auto!important;'
    + 'padding:0!important;'
    + 'border-radius:0!important;'
    // visible, or this wrapper clips the shelves' plate shadows square.
    + 'overflow:visible!important;'
    + 'cursor:default!important;'
    + '}'
    + '#container{padding:0!important;height:100%!important;}'
    + 'ha-ripple{display:none!important;}';


