      // A show leads with its show name; a film with its own.
      title: clean(item.title),
      // Films: the genres. Shows: the episode, numbered.
      line2: item._isTV
        ? (function () {
            const show = clean(item.title);
            const ep = clean(item.episode);
            const num = clean(item.number);
            const named = ep && (!show || show.toLowerCase() !== ep.toLowerCase());
            if (num && named) return num + ' \u00b7 ' + ep;
            return num || (named ? ep : null);
          })()
