       landed, not the whole library. */
    const movies = items.filter(i => !i._isTV).slice(0, 3).map(toCard);
    const shows  = items.filter(i =>  i._isTV).slice(0, 3).map(toCard);

    const areas = [], fields = {}, fstyle = {};
    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }];
    };
    /* One stagger sequence across both shelves: each row spends a
       slot on its heading, then one per cell. */
    let seq = 0;
    /* One tile per item, not one plate per section. Movies and TV Shows
       are headings over a set of objects; the objects are the items, and
       each one carries its own art and caption on one surface. */
    const addRow = (name, list, label) => {
      add(name, UI.mediaRow(list, label, { index: seq, tiles: true }));
      fstyle[name].push({ overflow: 'visible' });
      seq += list.length + 1;
    };
    if (movies.length) addRow('movies', movies, T('plex.movies', 'Movies'));
    if (shows.length)  addRow('shows',  shows,  T('plex.tv_shows', 'TV Shows'));

    /* This config is baked when the tile renders, so the fanart can be
       fetched on idle long before the popup is opened. */
    if (UI.prime) UI.prime(movies.concat(shows).map(c => c.image));

    const uiCard = {
      type: 'custom:button-card',
      card_mod: { style: transparentStyles },
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      extra_styles: transparentStyles,
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: '16px 0 20px 0' }, { 'border-radius': '0' },
        ],
        grid: [
          { 'grid-template-areas': areas.join(' ') },
          { 'grid-template-columns': '1fr' },
          { 'row-gap': '20px' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
    };
    return { type: 'vertical-stack', cards: [uiCard] };
  }

]]]

