    const add = (name, html) => {
      areas.push('"' + name + '"');
      fields[name] = html;
      fstyle[name] = [{ 'justify-self': 'stretch' }];
      /* A section heading belongs to its list, so it pulls back some of
         the grid's 18px row gap - but only some. At -14px the heading
         sat 12px off the plate, which was right for a line of text and
         too tight once the heading carried an action beside it. -4px
         leaves 22px, which reads as a heading over a card rather than a
         label stuck to one. */
      if (/head$/.test(name)) {
        fstyle[name].push({ 'margin-bottom': '-4px' });
      }
    };

    /* Restored: the brand logo was there before the redesign and I
       dropped it. HA serves it as /api/brands/... which 403s from a raw
       <img> since 2026.7, so it is rewritten to the public host. An
       entity with no logo passes image: null and gets the placeholder,
       which keeps every row the same shape. */
    const logoOf = (e) => {
      let pic = e?.attributes?.entity_picture || null;
      if (pic && pic.startsWith('/api/brands/')) {
        const parts = pic.split('/');
        pic = 'https://brands.home-assistant.io/_/'
          + parts[parts.length - 2] + '/' + parts[parts.length - 1];
      }
      return pic;
    };

    const n = updates.length;
    /* No chip. "Pending" restated what "1 update available" already
       says, and as a fixed-width object beside the value it landed on
       top of the sub-line on a phone. The only status worth its own
       color is a restart that is actually outstanding, and that is a
       sentence, so it belongs in the sub. */
    /* No headline when there are updates. The hero slot is built for a
       STATE WORD - "Bad", "Normal", "Light Upload" - and a bare "2" at
       40px does not fill it the way a word does; the count is already
       the length of the list underneath. When there is nothing to do,
       though, there is no list to speak for itself, so "Up to date"
       stays: that is a state word, and it is the whole answer - and
       "Up to date" is not the answer while a restart is still owed, so
       the outstanding one gets the slot instead. */
    if (!n && !restartEntities.length) {
      add('hero', UI.hero({ label: T('updates.status', 'Status'), value: T('updates.up_to_date', 'Up to date') }));
    }

    /* The action is a ROW in the group it acts on, not a card of its
       own floating above one. Home puts "Add Automation" at the foot of
       the automations group; Settings puts "Erase All Content and
       Settings" inside its section. A standalone block was a bar the
       width of the popup for a single tap. */
    const busy = updates.filter(e => e.attributes.in_progress).length;

    /* A real button-card, not markup. button-card's `confirmation:` is
       what puts Home Assistant's own dialog in front of the action -
       that is the native prompt this popup had before the redesign, and
       the reason a restart could never happen on one stray tap. A div
       handled by our delegated listener calls the service directly and
       has no dialog at all.
       Sized to its label and centered: a pill, not a bar the width of
       the sheet. */
    /* A section header that can carry an action: caption left, button
       right, on one line. This is the App Store's Updates screen and it
       is why the button is not floating under the list any more - an
       action that applies to a section belongs to that section's
       heading, not to the space below it.
       It has to be a card rather than group()'s own labelAction,
       because labelAction fires the service through our delegated
       listener with no dialog in front of it. The whole point of the
       button being a real button-card is tap_action.confirmation, and
       that is the native prompt this popup fought to get back. */
    const headText = (text) =>
      '<div style="font-family:var(--primary-font-family, system-ui);'
        + 'font-size:15px;font-weight:600;letter-spacing:-0.01em;'
        + 'text-align:left;color:var(--hemma-popup-tiles-text-primary, #fff);">'
        + text + '</div>';

    const sectionHead = (caption, btn) => ({
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: [
        ':host { --ha-card-box-shadow: none !important;'
          + ' --button-card-box-shadow: none !important;'
          + ' --button-card-box-shadow-hover: none !important;'
          + ' --ha-card-backdrop-filter: none !important; }',
        'ha-card { background: transparent !important; border: none !important;'
          + ' box-shadow: none !important; backdrop-filter: none !important;'
          + ' -webkit-backdrop-filter: none !important; padding: 0 !important;'
          + ' border-radius: 0 !important; overflow: visible !important;'
          + ' will-change: auto !important; cursor: default !important; }',
        '#container { overflow: visible !important; }',
        '#t, #b { overflow: visible !important; text-overflow: clip !important; }',
        'ha-ripple { display: none !important; }',
      ].join('\n') },
      styles: {
        card: [{ background: 'transparent' }, { border: 'none' },
               { 'box-shadow': 'none' }, { padding: '0 4px 8px' }],
        grid: [{ 'grid-template-areas': btn ? '"t b"' : '"t"' },
               { 'grid-template-columns': btn ? '1fr max-content' : '1fr' },
               { 'align-items': 'center' }, { 'column-gap': '12px' }],
        /* overflow: visible on both. button-card puts an `ellipsis`
           class on every custom field wrapper, and it clips - which
           with a nowrap text button trims its last characters at the
           trailing edge. Same class that squared off the plate shadows
           in the widget popups. */
        custom_fields: btn
          ? { t: [{ 'justify-self': 'start' }, { overflow: 'visible' }],
              b: [{ 'justify-self': 'end' }, { overflow: 'visible' }] }
          : { t: [{ 'justify-self': 'start' }, { overflow: 'visible' }] },
      },
      custom_fields: Object.assign({ t: caption },
        btn ? { b: { card: btn } } : {}),
    });

    /* Text, not a filled pill. On a section heading the App Store
       sets Update All in the same type as the heading and the same
       color as the per-row actions - and a pill there is both heavier
       than the thing it sits beside and taller than it, which is what
       left it almost touching the list below. Matching the caption's
       line height gives it the caption's gap for free, rather than
       tuning a padding to fake one. */
    const btnLabel = (text, tint) =>
      '<div style="font-family:var(--primary-font-family,system-ui);'
        + 'font-size:15px;font-weight:500;letter-spacing:-0.01em;color:' + tint + ';'
        + 'white-space:nowrap;width:max-content;flex:none;'
        + 'overflow:visible;text-overflow:clip;">' + text + '</div>';

    const actionButton = (label, tap) => ({
      type: 'custom:button-card',
      show_icon: false, show_name: false, show_label: false, show_state: false,
      tap_action: tap,
      haptic: 'medium',
      card_mod: { style: [
        ':host { --ha-card-box-shadow: none !important;'
          + ' --button-card-box-shadow: none !important;'
          + ' --button-card-box-shadow-hover: none !important;'
          + ' --ha-card-backdrop-filter: none !important;'
          + ' display: block !important; }',
        /* border-radius: 0 and overflow: visible are the fix for the
           clipped last letter. ha-card clips to its own radius by
           default, and dropping the pill's background left the theme's
           radius still in place - so the corner cut the end off a
           nowrap label that runs to the card's edge. A text button has
           no shape of its own to preserve. */
        'ha-card { background: transparent !important; border: none !important;'
          + ' box-shadow: none !important; border-radius: 0 !important;'
          + ' overflow: visible !important;'
          + ' backdrop-filter: none !important; -webkit-backdrop-filter: none !important;'
          + ' cursor: pointer !important;'
          + ' width: max-content !important; min-width: max-content !important;'
          // and a few px so no glyph ever sits on an edge
          + ' padding: 2px 6px !important; margin: 0 !important;'
          + ' will-change: auto !important;'
          + ' transition: opacity .14s ease !important; }',
        'ha-card::before, ha-card::after { display: none !important; }',
        '#container { overflow: visible !important; }',
        '#t { overflow: visible !important; text-overflow: clip !important; }',
        '@media (hover: hover) { ha-card:hover { opacity: 0.7 !important; } }',
        'ha-card:active { opacity: 0.5 !important; }',
        'ha-ripple { display: none !important; }',
        '#container { padding: 0 !important; }',
      ].join('\n') },
      styles: {
        card: [{ background: 'transparent' }, { padding: '2px 6px' },
               { 'box-shadow': 'none' }, { width: 'max-content' }],
        grid: [{ 'grid-template-areas': '"t"' },
               { 'grid-template-columns': 'max-content' },
               { 'justify-items': 'end' }],
        custom_fields: { t: [{ 'justify-self': 'end' }, { overflow: 'visible' }] },
      },
      custom_fields: { t: label },
    });

    const TEAL = 'var(--hemma-color-teal, #00C3D0)';
    const WARN = 'var(--hemma-popup-ui-warn, #FF9F0A)';

    /* Counted in a nested template, which the parent card re-evaluates
       on every update.* state change - reading each id through the
       states Proxy is what subscribes it. Everything about the heading
       moves once the installs finish: the caption, the label, the tint
       and the service, and none of it can be settled here, because the
       popup's card is built once at open and never again. */
    const headCount = ' const _ids = ' + _allIds + ';'
      + ' const _pending = []; let _rest = 0;'
      + ' _ids.forEach(function (id) {'
      + '   const s = states[id]; if (!s) return;'
      + '   const a = s.attributes || {};'
      + '   if (s.state === "on") { if (!a.in_progress) _pending.push(id); return; }'
      + '   if (String(a.release_summary || "").toLowerCase().indexOf("restart") !== -1'
      + '       && a.installed_version && a.installed_version === a.latest_version) _rest++;'
      + ' });'
      + ' const _waiting = !_pending.length && _rest > 0;';

    if (n) {
      const rows = updates.map(e => ({
        entity: e.entity_id,
        image: logoOf(e),
        label: nameOf(e),
        sub: verOf(e),
        action: e.attributes.in_progress ? T('updates.updating', 'Updating') : T('updates.update', 'Update'),
        actionTone: 'accent',
        /* An update whose notes say it needs a restart is not finished
           when it installs - the new version is not running yet, which
           is exactly what HA itself calls "Restart required". Green
           "Installed" would say done.
           The test has to be a RULE the bridge evaluates, not a branch
           taken here: release_summary is empty while the update is
           pending and only says "Restart of Home Assistant required"
           once the install has finished, so reading it at build time
           sends every row down the "Installed" branch. */
        actionLive: {
          rules: [
            { attr: 'in_progress', text: T('updates.updating', 'Updating'),
              color: 'var(--hemma-popup-ui-fill-2, rgba(255,255,255,0.45))' },
            { attr: 'state', eq: 'off',
              and: [{ attr: 'release_summary', has: 'restart' }],
              text: T('updates.restart_required', 'Restart required'), color: WARN },
            { attr: 'state', eq: 'off', text: T('updates.installed', 'Installed'),
              color: 'var(--hemma-popup-ui-good, #30D158)' },
          ],
          text: T('updates.update', 'Update'),
          color: TEAL,
        },
      }));
      /* One heading that follows the work. Update All while more than
         one is left to install - a single update needs none, its own
         row is the button - then Restart Now the moment the last
         install lands on something that says it needs one. That last
         turn is the whole point: an update that needs a restart is not
         finished when it installs, and the popup you installed from is
         still open and is where you would look for the button. */
      const RESTART_NOW = T('updates.restart_now', 'Restart Now'), UPDATE_ALL = T('updates.update_all', 'Update All');
      const WAITING = T('updates.waiting_restart', 'Waiting on a restart'), AVAILABLE = T('updates.available', 'Available Updates');
      const RESTART_Q = T('updates.restart_confirm', 'Restart Home Assistant now?'), INSTALL_ALL_Q = T('updates.install_all_q', 'Install all {n} updates now?');
      const headBtn = actionButton(
        '[[[' + headCount
          + ' if (_waiting) return ' + JSON.stringify(btnLabel(RESTART_NOW, WARN)) + ';'
          + ' if (_pending.length > 1) return ' + JSON.stringify(btnLabel(UPDATE_ALL, TEAL)) + ';'
          + ' return ""; ]]]',
        '[[[' + headCount
          + ' if (_waiting) return { action: "call-service",'
          + '   service: "homeassistant.restart", service_data: {},'
          + '   confirmation: { text: ' + JSON.stringify(RESTART_Q) + ' } };'
          + ' if (_pending.length > 1) return { action: "call-service",'
          + '   service: "update.install", target: { entity_id: _pending },'
          + '   service_data: {},'
          + '   confirmation: { text: ' + JSON.stringify(INSTALL_ALL_Q) + '.split("{n}").join(_pending.length) } };'
          + ' return { action: "none" }; ]]]');
      add('listhead', { card: sectionHead(
        '[[[' + headCount
          + ' return _waiting ? ' + JSON.stringify(headText(WAITING))
          + ' : ' + JSON.stringify(headText(AVAILABLE)) + '; ]]]',
        headBtn) });
      add('list', UI.group(rows, null));
    }
    if (restartEntities.length) {
      const rrows = restartEntities.map(e => ({
        entity: e.entity_id,
        image: logoOf(e),
        label: nameOf(e),
        sub: e.attributes.installed_version || null,
        value: T('updates.restart_required', 'Restart required'),
        valueTone: 'warn',
      }));
      /* Same shape: the restart belongs to the section that is waiting
         on it, not to the floor of the popup. */
      const restartBtn = (!n && restartEntities.length)
        ? actionButton(btnLabel(T('updates.restart_now', 'Restart Now'), WARN), {
            action: 'call-service',
            service: 'homeassistant.restart',
            service_data: {},
            confirmation: { text: T('updates.restart_confirm', 'Restart Home Assistant now?') },
          })
        : null;
      if (n || restartBtn) {
        add('resthead', { card: sectionHead(
          headText(T('updates.waiting_restart', 'Waiting on a restart')), restartBtn) });
      }
      add('restart', UI.group(rrows, null));
    }


    const uiCard = {
      type: 'custom:button-card',
      tap_action: { action: 'none' },
      show_icon: false, show_name: false, show_label: false, show_state: false,
      card_mod: { style: noHoverStyle },
      styles: {
        card: [
          { background: 'transparent' }, { border: 'none' }, { 'box-shadow': 'none' },
          { padding: '6px 26px 22px 26px' },
        ],
        grid: [
          { 'grid-template-areas': areas.join(' ') },
          { 'grid-template-columns': '1fr' },
          { 'row-gap': '18px' },
        ],
        custom_fields: fstyle,
      },
      custom_fields: fields,
    };
    return { type: 'vertical-stack', cards: [uiCard] };
  }

  return { type: 'vertical-stack', cards: [] };
]]]

hemma_battery.state_display:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const list = variables.batteries || variables.entity_filter;
  const batteries = (list
    ? list.map(id => states[id]).filter(Boolean)
    : Object.values(states)
  ).filter(e => {
    if (e.state === 'unavailable' || e.state === 'unknown') return false;
    if (isNaN(parseFloat(e.state))) return false;
    return e.attributes.device_class === 'battery';
  });
  if (batteries.length === 0) return T('battery.no_sensors', 'No Sensors');
  const anyLow = batteries.some(e => parseFloat(e.state) <= 20);
  return anyLow ? T('state.needs_attention', 'Needs Attention') : T('state.healthy', 'Healthy');
]]]

state.value:
[[[
  const list = variables.batteries || variables.entity_filter;
  return (list
    ? list.map(id => states[id]).filter(Boolean)
    : Object.values(states)
  ).some(e => {
    if (e.state === 'unavailable' || e.state === 'unknown') return false;
    const pct = parseFloat(e.state);
    if (isNaN(pct)) return false;
    return e.attributes.device_class === 'battery' && pct <= 20;
  });
]]]

hemma_cameras.state_display:
[[[
  const T = window._hemmaT || ((k, en, v) => { let s = String(en); if (v) for (const p in v) s = s.split('{' + p + '}').join(String(v[p])); return s; });
  const cams = Array.isArray(variables.cameras) ? variables.cameras.filter(Boolean) : [];
  if (!cams.length) return T('cameras.none', 'No Cameras');
  const dead = cams.filter(id => ['unavailable','unknown',''].includes(String(states[id]?.state ?? '').toLowerCase())).length;
  if (dead === cams.length) return cams.length === 1 ? T('cameras.offline', 'Offline') : T('cameras.all_offline', 'All Offline');
  if (dead > 0) return T('cameras.n_offline', '{n} Offline', { n: dead });
  const alert = window.hemmaCameraAlert ? window.hemmaCameraAlert(hass, states, cams, variables.alert_window_minutes) : '';
  return alert || T('cameras.no_alerts', 'No Alerts');
]]]

