hemma_entity_actions.extra_styles:
:host {
  --hemma-actions-pad: var(--hemma-entity-inner-pad-current, var(--hemma-entity-inner-pad-desktop, 20px));
  --hemma-actions-btn-radius: 13px;
  --hemma-actions-icon-size: 23px;
  --hemma-actions-svg-size: 20px;
  --hemma-actions-corner-gap: 4px;
  --hemma-actions-more-size: 21px;
  --hemma-actions-more-offset: 16px;
  --hemma-actions-more-fill-r: 18px;
  --hemma-actions-corner-shift: 0.26s;
  --hemma-actions-pill-h: 40px;
  --hemma-actions-pill-gap: 8px;
  --hemma-actions-pill-bottom: var(--hemma-actions-pad);
  --hemma-actions-label-size: 15px;
  /* FIT_REF_PX in hemma-core must equal this floor. */
  --hemma-actions-label-min: 12px;
  --hemma-actions-glyph-gap: 10px;
  --hemma-actions-label-gap: 12px;

  --hemma-actions-dur-in: 0.30s;
  --hemma-actions-dur-out: 0.14s;
  --hemma-actions-ease-in: cubic-bezier(0.32, 0.72, 0, 1);
  --hemma-actions-ease-out: cubic-bezier(0.4, 0, 0.7, 1);
  --hemma-actions-pill-scale: 0.94;
  --hemma-actions-pill-rise: 6px;

  --hemma-actions-press-more: 0.86;
  --hemma-actions-press-pill: 0.97;
  --hemma-actions-press-down: 0.12s;
  --hemma-actions-press-up: 0.28s;
  --hemma-actions-ease-press-down: cubic-bezier(0.2, 0, 0.4, 1);
  --hemma-actions-ease-press-up: cubic-bezier(0.32, 0.72, 0, 1);
}

/* On ha-card, not :host: --hemma-icon-circle-size lives here and a :host
   var cannot read one from a descendant. */
ha-card {
  --hemma-actions-hit: var(--hemma-icon-circle-size, 40px);
  /* The button is one fixed size everywhere; only its distance from the
     corner follows the tile's own padding. --more-offset is half the dots
     plus the gap that keeps the fill off the edge. */
  --hemma-actions-more-inset: calc(
    var(--hemma-actions-hit) / 2 - var(--hemma-actions-more-offset));
  --hemma-actions-more-fill: radial-gradient(circle closest-side,
    var(--hemma-actions-pill-bg) var(--hemma-actions-more-fill-r),
    transparent calc(var(--hemma-actions-more-fill-r) + 0.5px));
  --hemma-actions-pill-pad-start: calc(
    (var(--hemma-actions-hit) - var(--hemma-actions-icon-size)) / 2);
  --hemma-side-lit: var(--hemma-active-overlay-opacity, 0);
  --hemma-actions-ink: color-mix(in srgb, #000 calc(var(--hemma-side-lit) * 100%), #fff);
  /* Matches the tile toggle, whose track is rgba(0,0,0,0.75) under
     --hemma-toggle-opacity. That 0.75 is the theme's track-fill alpha. */
  --hemma-actions-dots-opacity: calc(0.75 * var(--hemma-toggle-opacity, 0.8));
  --hemma-actions-pill-bg-on: color-mix(in srgb,
    rgba(0, 0, 0, 0.20) calc(var(--hemma-side-lit) * 100%),
    rgba(255, 255, 255, 0.26));
  --hemma-actions-pill-bg: color-mix(in srgb,
    rgba(0, 0, 0, 0.10) calc(var(--hemma-side-lit) * 100%),
    rgba(255, 255, 255, 0.13));
  --hemma-actions-pill-bg-hover: color-mix(in srgb,
    rgba(0, 0, 0, 0.16) calc(var(--hemma-side-lit) * 100%),
    rgba(255, 255, 255, 0.19));
}

@media (max-width: 767px), (max-height: 600px) {
  .hemma-act-pill .hemma-act-glyphbox { display: none; }
  .hemma-act-pill {
    gap: 0;
    --hemma-actions-label-inset: 0px;
    --hemma-actions-pill-pad-start: 14px;
  }

  :host {
    --hemma-actions-btn-radius: 12px;
    --hemma-actions-icon-size: 22px;
    --hemma-actions-svg-size: 19px;
    --hemma-actions-corner-gap: 2px;
    --hemma-actions-pill-h: 30px;
    --hemma-actions-pill-gap: 6px;
    --hemma-actions-pill-bottom: 10px;
    --hemma-actions-label-size: 14px;
  }
}
:host(.hemma-compact) .hemma-act-pill .hemma-act-glyphbox { display: none; }
:host(.hemma-compact) .hemma-act-pill {
  gap: 0;
  --hemma-actions-label-inset: 0px;
  --hemma-actions-pill-pad-start: 14px;
}

:host(.hemma-compact) {
  --hemma-actions-btn-radius: 12px;
  --hemma-actions-icon-size: 22px;
  --hemma-actions-svg-size: 19px;
  --hemma-actions-corner-gap: 2px;
  --hemma-actions-pill-h: 30px;
  --hemma-actions-pill-gap: 6px;
  --hemma-actions-pill-bottom: 10px;
  --hemma-actions-label-size: 14px;
}

/* The press lives one level in: the pill wrapper's transform belongs to
   the cross-fade. */
.hemma-act-hit {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  gap: var(--hemma-actions-glyph-gap, 10px);
  box-sizing: border-box;
  border-radius: inherit;
  overflow: hidden;
  cursor: pointer;
  user-select: none;
  -webkit-tap-highlight-color: transparent;

  transform: scale(1);
  transition:
    transform var(--hemma-actions-press-up, 0.28s)
      var(--hemma-actions-ease-press-up, cubic-bezier(0.32, 0.72, 0, 1)),
    background-color 0.18s ease;
}

.hemma-act-hit.pressed {
  transform: scale(var(--hemma-act-press, 0.96));
  background: var(--hemma-actions-pill-bg-hover);
  transition:
    transform var(--hemma-actions-press-down, 0.12s)
      var(--hemma-actions-ease-press-down, cubic-bezier(0.2, 0, 0.4, 1)),
    background-color var(--hemma-actions-press-down, 0.12s) ease;
}

@media (prefers-reduced-motion: reduce) {
  .hemma-act-hit, .hemma-act-hit.pressed { transform: none; }
}

.hemma-act-more {
  justify-content: center;
  background: transparent;
  --hemma-act-press: var(--hemma-actions-press-more, 0.86);
}

.hemma-act-more.pressed {
  background: radial-gradient(circle closest-side,
    var(--hemma-actions-pill-bg-hover) var(--hemma-actions-more-fill-r),
    transparent calc(var(--hemma-actions-more-fill-r) + 0.5px));
}

.hemma-act-dots {
  display: block;
  flex: none;
  width: var(--hemma-actions-more-size);
  height: var(--hemma-actions-more-size);
  fill: var(--hemma-actions-ink);
  opacity: var(--hemma-actions-dots-opacity);
  pointer-events: none;
}

.hemma-act-pill {
  background: var(--hemma-actions-pill-bg);
  --hemma-act-press: var(--hemma-actions-press-pill, 0.97);
  padding-inline-start: var(--hemma-actions-pill-pad-start);
  padding-inline-end: var(--hemma-actions-label-gap, 12px);
  /* The label sizes off 100cqi, which is the CONTENT box. */
  container-type: inline-size;
  --hemma-actions-label-inset: calc(
    var(--hemma-actions-icon-size)
    + var(--hemma-actions-glyph-gap, 10px));
}

.hemma-act-glyphbox {
  flex: none;
  display: grid;
  place-items: center;
  width: var(--hemma-actions-icon-size);
  height: var(--hemma-actions-icon-size);
}

.hemma-act-label {
  flex: 0 1 auto;
  /* Without it the label refuses to shrink and clips mid-word. */
  min-width: 0;
  display: block;
  line-height: 1.25;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;
  font-size: var(--hemma-actions-label-size);
  font-weight: 500;
  letter-spacing: -0.01em;
  color: var(--hemma-actions-ink);
  opacity: 0.9;
}

.hemma-act-icon {
  display: block;
  object-fit: contain;

  background: transparent !important;
  background-color: transparent !important;
  border-radius: 0 !important;
  box-shadow: none !important;
  filter: none;

  color: var(--hemma-actions-ink);
  opacity: 0.52;

  transition: color 0.18s ease, opacity 0.18s ease;
}

/* HA's own hook; without it mdi glyphs ride a text baseline and sit low. */
.hemma-act-ha-icon {
  --mdc-icon-size: var(--hemma-actions-icon-size);
  --ha-icon-display: block;
  width: var(--hemma-actions-icon-size);
  height: var(--hemma-actions-icon-size);
  line-height: 0;
}

.hemma-act-svg {
  filter: brightness(0) invert(calc(1 - var(--hemma-side-lit)));
  width: var(--hemma-actions-svg-size);
  height: var(--hemma-actions-svg-size);
  object-fit: contain;
}

.hemma-act-hit.active .hemma-act-icon {
  opacity: 1;
}

.hemma-act-pill.active {
  background: var(--hemma-actions-pill-bg-on);
}

.hemma-act-hit.unavailable .hemma-act-icon {
  opacity: 0.35;
  color: var(--disabled-text-color);
}

.hemma-act-hit.unavailable .hemma-act-label {
  opacity: 0.5;
}

#glyph_1, #glyph_2, #pill_1, #pill_2 {
  overflow: hidden !important;
}

/* Hover only. Press is a pointerdown class: :active on touch lands late
   and can stick. */
@media (hover: hover) and (pointer: fine) {
  .hemma-act-more:hover { background: var(--hemma-actions-more-fill); }
  .hemma-act-pill:hover { background: var(--hemma-actions-pill-bg-hover); }
}

card.--hemma-fan-animation:
[[[
  const s = String(entity?.state || '').toLowerCase();
  const isOn = s === 'on';
  const prev = this._hemmaPrevFan;
  this._hemmaPrevFan = isOn;
  const justOn  = isOn  && prev === false;
  const justOff = !isOn && prev === true;
  if (isOn) {
    return justOn
      ? 'hemma-fan-spin 1.5s ease-in 1, hemma-fan-spin 0.9s linear 1.5s infinite'
      : 'hemma-fan-spin 0.9s linear infinite';
  }
  if (justOff) return 'hemma-fan-coast 1.5s ease-out 1 forwards';
  return 'none';
]]]

