    + "w.animate([{transform:'scale(1)'},{transform:'scale('+d+')',offset:0.38},{transform:'scale(1)'}],"
    + "{duration:280,easing:'ease-out'});";
  const svc = "h.callService('input_number','decrement',{entity_id:'input_number.hemma_thermostat_target_temperature'});";
  const body = fx + getHass + svc;
  const tap = stop + noGhost + body + "window._hemmaCtlTouch=Date.now();";
  const clk = stop + "if(window._hemmaCtlTouch&&Date.now()-window._hemmaCtlTouch<600)return;" + body;
  return `<div class="hemma-ctl-hit" onpointerdown="${stop}" onpointerup="${stop}" ontouchstart="${stop}" ontouchend="${tap}" onclick="${clk}"></div>`;
]]]

hemma_thermostat.extra_styles:
/* Optical sizing: 800 is right at 17px, too heavy once the puck scales up.
   1740px is where --hemma-u leaves its floor, i.e. where the digits start growing. */
:host { --hemma-puck-font-weight: 800; }
@media (min-width: 1740px) { :host { --hemma-puck-font-weight: 700; } }

#temp_puck {
  grid-area: i !important;
  height: var(--hemma-icon-circle-size, 44px);
}

/* Closed by default; the JS-templated opacity lands a frame later. */
#target_temperature, #ctl_up, #ctl_set, #ctl_down {
  opacity: 0;
  pointer-events: none;
}

.hemma-ctl-hit {
  position: absolute;
  inset: 0;
  /* Under the glyph/label pseudo (z-index 1), which is pointer-events:none
     and so does not intercept the tap. */
  z-index: 0;
  cursor: pointer;
  touch-action: manipulation;
  -webkit-tap-highlight-color: transparent;
}

/* Control glyphs */
#ctl_up::before,
#ctl_down::before,
#ctl_set::before {
  content: '';
  position: absolute;
  inset: 0;
  z-index: 1;
  pointer-events: none;
  background-repeat: no-repeat;
  background-position: center center;
  background-size: var(--thermo-glyph-size, 68%) auto;
  filter: var(--thermostat-control-icon-filter, none);
}
/* Optical centering */
#ctl_up::before {
  background-image: var(--thermo-icon-up);
  background-position: center calc(50% - 1px);
}
#ctl_down::before {
  background-image: var(--thermo-icon-down);
  background-position: center calc(50% + 1px);
}
/* 22px on a 44px-tall button is exactly half its height, which is a full
   oval. 16px keeps it clearly a squircle while sitting a shade rounder
   than the entity-actions pills (13px on 40px, a 0.325 ratio, against
   0.364 here).
   A real media query, not a matchMedia snapshot baked into an inline
   style - that goes stale on rotation. */
ha-card { --thermo-btn-radius: 16px; }

@media (max-width: 767px), (max-height: 600px) {
  ha-card { --thermo-btn-radius: 15px; }
}
:host(.hemma-compact) ha-card { --thermo-btn-radius: 15px; }

/* Hover/press */
@media (hover: hover) {
  #ctl_up:hover,
  #ctl_set:hover,
  #ctl_down:hover {
    background: var(--thermo-btn-bg-hover, rgba(255,255,255,0.16)) !important;
    transform: scale(var(--thermo-btn-hover-scale, 1.02));
  }
}

#ctl_set::before {
  content: var(--hemma-set-label, 'Set');
  display: flex;
  align-items: center;
  justify-content: center;
  background-image: none;
  filter: none;
  font-size: var(--thermo-set-font, 18px);
  font-weight: 600;
  letter-spacing: -0.005em;
  line-height: 1.15;
  color: var(--thermo-set-color, #fff);
}

card_mod.style:
ha-card::after {
  transition: opacity var(--hemma-active-overlay-dur, .40s) ease, background-color .35s ease !important;
}
@media (hover: hover) {
  :host(:hover) ha-card::after {
    transition: opacity .18s ease, background-color .18s ease !important;
  }
  :host(:hover) ha-card {
    --hemma-active-overlay-opacity: var(--hemma-hover-overlay-opacity, 0.10);
    --hemma-entity-overlay-tint: var(--hemma-entity-hover-tint, rgba(255,255,255,0.55));
  }
}

